insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','lc',1,1,'Tendo, pois, muitos empreendido pôr em ordem a narração dos fatos que entre nós se cumpriram,'),
('acf','lc',1,2,'Segundo nos transmitiram os mesmos que os presenciaram desde oprincípio, e foram ministros da palavra,'),
('acf','lc',1,3,'Pareceu-me também a mim conveniente descrevê-los a ti, ó excelente Teófilo, por sua ordem, havendo-me já informado minuciosamente de tudo desde o princípio;'),
('acf','lc',1,4,'Para que conheças a certeza das coisas de que já estás informado.'),
('acf','lc',1,5,'Existiu, no tempo de Herodes, rei da Judéia, um sacerdote chamado Zacarias, da ordem de Abias, e cuja mulher era das filhas de Arão; e o seu nome era Isabel.'),
('acf','lc',1,6,'E eram ambos justos perante Deus, andando sem repreensão em todos os mandamentos e preceitos do Senhor.'),
('acf','lc',1,7,'E não tinham filhos, porque Isabel era estéril, e ambos eram avançados em idade.'),
('acf','lc',1,8,'E aconteceu que, exercendo ele o sacerdócio diante de Deus, na ordem da sua turma,'),
('acf','lc',1,9,'Segundo o costume sacerdotal, coube-lhe em sorte entrar no templo do Senhor para oferecer o incenso.'),
('acf','lc',1,10,'E toda a multidão do povo estava fora, orando, à hora do incenso.'),
('acf','lc',1,11,'E um anjo do Senhor lhe apareceu, posto em pé, à direita do altar do incenso.'),
('acf','lc',1,12,'E Zacarias, vendo-o, turbou-se, e caiu temor sobre ele.'),
('acf','lc',1,13,'Mas o anjo lhe disse: Zacarias, não temas, porque a tua oração foi ouvida, e Isabel, tua mulher, dará à luz um filho, e lhe porás o nome de João.'),
('acf','lc',1,14,'E terás prazer e alegria, e muitos se alegrarão no seu nascimento,'),
('acf','lc',1,15,'Porque será grande diante do Senhor, e não beberá vinho, nem bebida forte, e será cheio do Espírito Santo, já desde o ventre de sua mãe.'),
('acf','lc',1,16,'E converterá muitos dos filhos de Israel ao Senhor seu Deus,'),
('acf','lc',1,17,'E irá adiante dele no espírito e virtude de Elias, para converter os corações dos pais aos filhos, e os rebeldes à prudência dos justos, com o fim de preparar ao Senhor um povo bem disposto.'),
('acf','lc',1,18,'Disse então Zacarias ao anjo: Como saberei isto? pois eu já sou velho, e minha mulher avançada em idade.'),
('acf','lc',1,19,'E, respondendo o anjo, disse-lhe: Eu sou Gabriel, que assisto diante de Deus, e fui enviado a falar-te e dar-te estas alegres novas.'),
('acf','lc',1,20,'E eis que ficarás mudo, e não poderás falar até ao dia em que estas coisas aconteçam; porquanto não creste nas minhas palavras, que a seu tempo se hão de cumprir.'),
('acf','lc',1,21,'E o povo estava esperando a Zacarias, e maravilhava-se de que tanto se demorasse no templo.'),
('acf','lc',1,22,'E, saindo ele, não lhes podia falar; e entenderam que tinha tido uma visão no templo. E falava por acenos, e ficou mudo.'),
('acf','lc',1,23,'E sucedeu que, terminados os dias de seu ministério, voltou para sua casa.'),
('acf','lc',1,24,'E, depois daqueles dias, Isabel, sua mulher, concebeu, e por cinco meses se ocultou, dizendo:'),
('acf','lc',1,25,'Assim me fez o Senhor, nos dias em que atentou em mim, para destruir o meu opróbrio entre os homens.'),
('acf','lc',1,26,'E, no sexto mês, foi o anjo Gabriel enviado por Deus a uma cidade da Galiléia, chamada Nazaré,'),
('acf','lc',1,27,'A uma virgem desposada com um homem, cujo nome era José, da casa de Davi; e o nome da virgem era Maria.'),
('acf','lc',1,28,'E, entrando o anjo aonde ela estava, disse: Salve, agraciada; o Senhor é contigo; bendita és tu entre as mulheres.'),
('acf','lc',1,29,'E, vendo-o ela, turbou-se muito com aquelas palavras, e considerava que saudação seria esta.'),
('acf','lc',1,30,'Disse-lhe, então, o anjo: Maria, não temas, porque achaste graça diante de Deus.'),
('acf','lc',1,31,'E eis que em teu ventre conceberás e darás à luz um filho, e pôr-lhe-ás o nome de Jesus.'),
('acf','lc',1,32,'Este será grande, e será chamado filho do Altíssimo; e o Senhor Deus lhe dará o trono de Davi, seu pai;'),
('acf','lc',1,33,'E reinará eternamente na casa de Jacó, e o seu reino não terá fim.'),
('acf','lc',1,34,'E disse Maria ao anjo: Como se fará isto, visto que não conheço homem algum?'),
('acf','lc',1,35,'E, respondendo o anjo, disse-lhe: Descerá sobre ti o Espírito Santo, e a virtude do Altíssimo te cobrirá com a sua sombra; por isso também o Santo, que de ti há de nascer, será chamado Filho de Deus.'),
('acf','lc',1,36,'E eis que também Isabel, tua prima, concebeu um filho em sua velhice; e é este o sexto mês para aquela que era chamada estéril;'),
('acf','lc',1,37,'Porque para Deus nada é impossível.'),
('acf','lc',1,38,'Disse então Maria: Eis aqui a serva do Senhor; cumpra-se em mim segundo a tua palavra. E o anjo ausentou-se dela.'),
('acf','lc',1,39,'E, naqueles dias, levantando-se Maria, foi apressada às montanhas, a uma cidade de Judá,'),
('acf','lc',1,40,'E entrou em casa de Zacarias, e saudou a Isabel.'),
('acf','lc',1,41,'E aconteceu que, ao ouvir Isabel a saudação de Maria, a criancinha saltou no seu ventre; e Isabel foi cheia do Espírito Santo.'),
('acf','lc',1,42,'E exclamou com grande voz, e disse: Bendita és tu entre as mulheres, e bendito o fruto do teu ventre.'),
('acf','lc',1,43,'E de onde me provém isto a mim, que venha visitar-me a mãe do meu Senhor?'),
('acf','lc',1,44,'Pois eis que, ao chegar aos meus ouvidos a voz da tua saudação, a criancinha saltou de alegria no meu ventre.'),
('acf','lc',1,45,'Bem-aventurada a que creu, pois hão de cumprir-se as coisas que da parte do Senhor lhe foram ditas.'),
('acf','lc',1,46,'Disse então Maria: A minha alma engrandece ao Senhor,'),
('acf','lc',1,47,'E o meu espírito se alegra em Deus meu Salvador;'),
('acf','lc',1,48,'Porque atentou na baixeza de sua serva; Pois eis que desde agora todas as gerações me chamarão bem-aventurada,'),
('acf','lc',1,49,'Porque me fez grandes coisas o Poderoso; E santo é seu nome.'),
('acf','lc',1,50,'E a sua misericórdia é de geração em geração Sobre os que o temem.'),
('acf','lc',1,51,'Com o seu braço agiu valorosamente; Dissipou os soberbos no pensamento de seus corações.'),
('acf','lc',1,52,'Depôs dos tronos os poderosos, E elevou os humildes.'),
('acf','lc',1,53,'Encheu de bens os famintos, E despediu vazios os ricos.'),
('acf','lc',1,54,'Auxiliou a Israel seu servo, Recordando-se da sua misericórdia;'),
('acf','lc',1,55,'Como falou a nossos pais, Para com Abraão e a sua posteridade, para sempre.'),
('acf','lc',1,56,'E Maria ficou com ela quase três meses, e depois voltou para sua casa.'),
('acf','lc',1,57,'E completou-se para Isabel o tempo de dar à luz, e teve um filho.'),
('acf','lc',1,58,'E os seus vizinhos e parentes ouviram que tinha Deus usado para com ela de grande misericórdia, e alegraram-se com ela.'),
('acf','lc',1,59,'E aconteceu que, ao oitavo dia, vieram circuncidar o menino, e lhe chamavam Zacarias, o nome de seu pai.'),
('acf','lc',1,60,'E, respondendo sua mãe, disse: Não, porém será chamado João.'),
('acf','lc',1,61,'E disseram-lhe: Ninguém há na tua parentela que se chame por este nome.'),
('acf','lc',1,62,'E perguntaram por acenos ao pai como queria que lhe chamassem.'),
('acf','lc',1,63,'E, pedindo ele uma tabuinha de escrever, escreveu, dizendo: O seu nome é João. E todos se maravilharam.'),
('acf','lc',1,64,'E logo a boca se lhe abriu, e a língua se lhe soltou; e falava, louvando a Deus.'),
('acf','lc',1,65,'E veio temor sobre todos os seus vizinhos, e em todas as montanhas da Judéia foram divulgadas todas estas coisas.'),
('acf','lc',1,66,'E todos os que as ouviam as conservavam em seus corações, dizendo: Quem será, pois, este menino? E a mão do Senhor estava com ele.'),
('acf','lc',1,67,'E Zacarias, seu pai, foi cheio do Espírito Santo, e profetizou, dizendo:'),
('acf','lc',1,68,'Bendito o Senhor Deus de Israel, Porque visitou e remiu o seu povo,'),
('acf','lc',1,69,'E nos levantou uma salvação poderosa Na casa de Davi seu servo.'),
('acf','lc',1,70,'Como falou pela boca dos seus santos profetas, desde o princípio do mundo;'),
('acf','lc',1,71,'Para nos livrar dos nossos inimigos e da mão de todos os que nos odeiam;'),
('acf','lc',1,72,'Para manifestar misericórdia a nossos pais, E lembrar-se da sua santa aliança,'),
('acf','lc',1,73,'E do juramento que jurou a Abraão nosso pai,'),
('acf','lc',1,74,'De conceder-nos que, Libertados da mão de nossos inimigos, o serviríamos sem temor,'),
('acf','lc',1,75,'Em santidade e justiça perante ele, todos os dias da nossa vida.'),
('acf','lc',1,76,'E tu, ó menino, serás chamado profeta do Altíssimo, Porque hás de ir ante a face do Senhor, a preparar os seus caminhos;'),
('acf','lc',1,77,'Para dar ao seu povo conhecimento da salvação, Na remissão dos seus pecados;'),
('acf','lc',1,78,'Pelas entranhas da misericórdia do nosso Deus, Com que o oriente do alto nos visitou;'),
('acf','lc',1,79,'Para iluminar aos que estão assentados em trevas e na sombra da morte; A fim de dirigir os nossos pés pelo caminho da paz.'),
('acf','lc',1,80,'E o menino crescia, e se robustecia em espírito. E esteve nos desertos até ao dia em que havia de mostrar-se a Israel.'),
('acf','lc',2,1,'E aconteceu naqueles dias que saiu um decreto da parte de César Augusto, para que todo o mundo se alistasse'),
('acf','lc',2,2,'(Este primeiro alistamento foi feito sendo Quirino presidente da Síria).'),
('acf','lc',2,3,'E todos iam alistar-se, cada um à sua própria cidade.'),
('acf','lc',2,4,'E subiu também José da Galiléia, da cidade de Nazaré, à Judéia, à cidade de Davi, chamada Belém (porque era da casa e família de Davi),'),
('acf','lc',2,5,'A fim de alistar-se com Maria, sua esposa, que estava grávida.'),
('acf','lc',2,6,'E aconteceu que, estando eles ali, se cumpriram os dias em que ela havia de dar à luz.'),
('acf','lc',2,7,'E deu à luz a seu filho primogênito, e envolveu-o em panos, e deitou-o numa manjedoura, porque não havia lugar para eles na estalagem.'),
('acf','lc',2,8,'Ora, havia naquela mesma comarca pastores que estavam no campo, e guardavam, durante as vigílias da noite, o seu rebanho.'),
('acf','lc',2,9,'E eis que o anjo do Senhor veio sobre eles, e a glória do Senhor os cercou de resplendor, e tiveram grande temor.'),
('acf','lc',2,10,'E o anjo lhes disse: Não temais, porque eis aqui vos trago novas de grande alegria, que será para todo o povo:'),
('acf','lc',2,11,'Pois, na cidade de Davi, vos nasceu hoje o Salvador, que é Cristo, o Senhor.'),
('acf','lc',2,12,'E isto vos será por sinal: Achareis o menino envolto em panos, e deitado numa manjedoura.'),
('acf','lc',2,13,'E, no mesmo instante, apareceu com o anjo uma multidão dos exércitos celestiais, louvando a Deus, e dizendo:'),
('acf','lc',2,14,'Glória a Deus nas alturas, Paz na terra, boa vontade para com os homens.'),
('acf','lc',2,15,'E aconteceu que, ausentando-se deles os anjos para o céu, disseram os pastores uns aos outros: Vamos, pois, até Belém, e vejamos isso que aconteceu, e que o Senhor nos fez saber.'),
('acf','lc',2,16,'E foram apressadamente, e acharam Maria, e José, e o menino deitado na manjedoura.'),
('acf','lc',2,17,'E, vendo-o, divulgaram a palavra que acerca do menino lhes fora dita;'),
('acf','lc',2,18,'E todos os que a ouviram se maravilharam do que os pastores lhes diziam.'),
('acf','lc',2,19,'Mas Maria guardava todas estas coisas, conferindo-as em seu coração.'),
('acf','lc',2,20,'E voltaram os pastores, glorificando e louvando a Deus por tudo o que tinham ouvido e visto, como lhes havia sido dito.'),
('acf','lc',2,21,'E, quando os oito dias foram cumpridos, para circuncidar o menino, foi-lhe dado o nome de Jesus, que pelo anjo lhe fora posto antes de ser concebido.'),
('acf','lc',2,22,'E, cumprindo-se os dias da purificação dela, segundo a lei de Moisés, o levaram a Jerusalém, para o apresentarem ao Senhor'),
('acf','lc',2,23,'(Segundo o que está escrito na lei do Senhor: Todo o macho primogênito será consagrado ao Senhor);'),
('acf','lc',2,24,'E para darem a oferta segundo o disposto na lei do Senhor: Um par de rolas ou dois pombinhos.'),
('acf','lc',2,25,'Havia em Jerusalém um homem cujo nome era Simeão; e este homem era justo e temente a Deus, esperando a consolação de Israel; e o Espírito Santo estava sobre ele.'),
('acf','lc',2,26,'E fora-lhe revelado, pelo Espírito Santo, que ele não morreria antes de ter visto o Cristo do Senhor.'),
('acf','lc',2,27,'E pelo Espírito foi ao templo e, quando os pais trouxeram o menino Jesus, para com ele procederem segundo o uso da lei,'),
('acf','lc',2,28,'Ele, então, o tomou em seus braços, e louvou a Deus, e disse:'),
('acf','lc',2,29,'Agora, Senhor, despedes em paz o teu servo, Segundo a tua palavra;'),
('acf','lc',2,30,'Pois já os meus olhos viram a tua salvação,'),
('acf','lc',2,31,'A qual tu preparaste perante a face de todos os povos;'),
('acf','lc',2,32,'Luz para iluminar as nações, E para glória de teu povo Israel.'),
('acf','lc',2,33,'E José, e sua mãe, se maravilharam das coisas que dele se diziam.'),
('acf','lc',2,34,'E Simeão os abençoou, e disse a Maria, sua mãe: Eis que este é posto para queda e elevação de muitos em Israel, e para sinal que é contraditado'),
('acf','lc',2,35,'(E uma espada traspassará também a tua própria alma); para que se manifestem os pensamentos de muitos corações.'),
('acf','lc',2,36,'E estava ali a profetisa Ana, filha de Fanuel, da tribo de Aser. Esta era já avançada em idade, e tinha vivido com o marido sete anos, desde a sua virgindade;'),
('acf','lc',2,37,'E era viúva, de quase oitenta e quatro anos, e não se afastava do templo, servindo a Deus em jejuns e orações, de noite e de dia.'),
('acf','lc',2,38,'E sobrevindo na mesma hora, ela dava graças a Deus, e falava dele a todos os que esperavam a redenção em Jerusalém.'),
('acf','lc',2,39,'E, quando acabaram de cumprir tudo segundo a lei do Senhor, voltaram à Galiléia, para a sua cidade de Nazaré.'),
('acf','lc',2,40,'E o menino crescia, e se fortalecia em espírito, cheio de sabedoria; e a graça de Deus estava sobre ele.'),
('acf','lc',2,41,'Ora, todos os anos iam seus pais a Jerusalém à festa da páscoa;'),
('acf','lc',2,42,'E, tendo ele já doze anos, subiram a Jerusalém, segundo o costume do dia da festa.'),
('acf','lc',2,43,'E, regressando eles, terminados aqueles dias, ficou o menino Jesus em Jerusalém, e não o soube José, nem sua mãe.'),
('acf','lc',2,44,'Pensando, porém, eles que viria de companhia pelo caminho, andaram caminho de um dia, e procuravam-no entre os parentes e conhecidos;'),
('acf','lc',2,45,'E, como o não encontrassem, voltaram a Jerusalém em busca dele.'),
('acf','lc',2,46,'E aconteceu que, passados três dias, o acharam no templo, assentado no meio dos doutores, ouvindo-os, e interrogando-os.'),
('acf','lc',2,47,'E todos os que o ouviam admiravam a sua inteligência e respostas.'),
('acf','lc',2,48,'E quando o viram, maravilharam-se, e disse-lhe sua mãe: Filho, por que fizeste assim para conosco? Eis que teu pai e eu ansiosos te procurávamos.'),
('acf','lc',2,49,'E ele lhes disse: Por que é que me procuráveis? Não sabeis que me convém tratar dos negócios de meu Pai?'),
('acf','lc',2,50,'E eles não compreenderam as palavras que lhes dizia.'),
('acf','lc',2,51,'E desceu com eles, e foi para Nazaré, e era-lhes sujeito. E sua mãe guardava no seu coração todas estas coisas.'),
('acf','lc',2,52,'E crescia Jesus em sabedoria, e em estatura, e em graça para com Deus e os homens.'),
('acf','lc',3,1,'E no ano quinze do império de Tibério César, sendo Pôncio Pilatos presidente da Judéia, e Herodes tetrarca da Galiléia, e seu irmão Filipe tetrarca da Ituréia e da província de Traconites, e Lisânias tetrarca de Abilene,'),
('acf','lc',3,2,'Sendo Anás e Caifás sumos sacerdotes, veio no deserto a palavra de Deus a João, filho de Zacarias.'),
('acf','lc',3,3,'E percorreu toda a terra ao redor do Jordão, pregando o batismo de arrependimento, para o perdão dos pecados;'),
('acf','lc',3,4,'Segundo o que está escrito no livro das palavras do profeta Isaías, que diz: Voz do que clama no deserto: Preparai o caminho do Senhor; Endireitai as suas veredas.'),
('acf','lc',3,5,'Todo o vale se encherá, E se abaixará todo o monte e outeiro; E o que é tortuoso se endireitará, E os caminhos escabrosos se aplanarão;'),
('acf','lc',3,6,'E toda a carne verá a salvação de Deus.'),
('acf','lc',3,7,'Dizia, pois, João à multidão que saía para ser batizada por ele: Raça de víboras, quem vos ensinou a fugir da ira que está para vir?'),
('acf','lc',3,8,'Produzi, pois, frutos dignos de arrependimento, e não comeceis a dizer em vós mesmos: Temos Abraão por pai; porque eu vos digo que até destas pedras pode Deus suscitar filhos a Abraão.'),
('acf','lc',3,9,'E também já está posto o machado à raiz das árvores; toda a árvore, pois, que não dá bom fruto, corta-se e lança-se no fogo.'),
('acf','lc',3,10,'E a multidão o interrogava, dizendo: Que faremos, pois?'),
('acf','lc',3,11,'E, respondendo ele, disse-lhes: Quem tiver duas túnicas, reparta com o que não tem, e quem tiver alimentos, faça da mesma maneira.'),
('acf','lc',3,12,'E chegaram também uns publicanos, para serem batizados, e disseram-lhe: Mestre, que devemos fazer?'),
('acf','lc',3,13,'E ele lhes disse: Não peçais mais do que o que vos está ordenado.'),
('acf','lc',3,14,'E uns soldados o interrogaram também, dizendo: E nós que faremos? E ele lhes disse: A ninguém trateis mal nem defraudeis, e contentai-vos com o vosso soldo.'),
('acf','lc',3,15,'E, estando o povo em expectação, e pensando todos de João, em seus corações, se porventura seria o Cristo,'),
('acf','lc',3,16,'Respondeu João a todos, dizendo: Eu, na verdade, batizo-vos com água, mas eis que vem aquele que é mais poderoso do que eu, do qual não sou digno de desatar a correia das alparcas; esse vos batizará com o Espírito Santo e com fogo.'),
('acf','lc',3,17,'Ele tem a pá na sua mão; e limpará a sua eira, e ajuntará o trigo no seu celeiro, mas queimará a palha com fogo que nunca se apaga.'),
('acf','lc',3,18,'E assim, admoestando-os, muitas outras coisas também anunciava ao povo.'),
('acf','lc',3,19,'Sendo, porém, o tetrarca Herodes repreendido por ele por causa de Herodias, mulher de seu irmão Filipe, e por todas as maldades que Herodes tinha feito,'),
('acf','lc',3,20,'Acrescentou a todas as outras ainda esta, a de encerrar João num cárcere.'),
('acf','lc',3,21,'E aconteceu que, como todo o povo se batizava, sendo batizado também Jesus, orando ele, o céu se abriu;'),
('acf','lc',3,22,'E o Espírito Santo desceu sobre ele em forma corpórea, como pomba; e ouviu-se uma voz do céu, que dizia: Tu és o meu Filho amado, em ti me comprazo.'),
('acf','lc',3,23,'E o mesmo Jesus começava a ser de quase trinta anos, sendo (como se cuidava) filho de José, e José de Heli,'),
('acf','lc',3,24,'E Heli de Matã, e Matã de Levi, e Levi de Melqui, e Melqui de Janai, e Janai de José,'),
('acf','lc',3,25,'E José de Matatias, e Matatias de Amós, e Amós de Naum, e Naum de Esli, e Esli de Nagaí,'),
('acf','lc',3,26,'E Nagaí de Máate, e Máate de Matatias, e Matatias de Semei, e Semei de José, e José de Jodá,'),
('acf','lc',3,27,'E Jodá de Joanã, e Joanã de Resá, e Resá de Zorobabel, e Zorobabel de Salatiel, e Salatiel de Neri,'),
('acf','lc',3,28,'E Neri de Melqui, e Melqui de Adi, e Adi de Cosã, e Cosã de Elmadã, e Elmadã de Er,'),
('acf','lc',3,29,'E Er de Josué, e Josué de Eliézer, e Eliézer de Jorim, e Jorim de Matã, e Matã de Levi,'),
('acf','lc',3,30,'E Levi de Simeão, e Simeão de Judá, e Judá de José, e José de Jonã, e Jonã de Eliaquim,'),
('acf','lc',3,31,'E Eliaquim de Meleá, e Meleá de Mená, e Mená de Matatá, e Matatá de Natã, e Natã de Davi,'),
('acf','lc',3,32,'E Davi de Jessé, e Jessé de Obede, e Obede de Boaz, e Boaz de Salá, e Salá de Naassom,'),
('acf','lc',3,33,'E Naassom de Aminadabe, e Aminadabe de Arão, e Arão de Esrom, e Esrom Perez, e Perez de Judá,'),
('acf','lc',3,34,'E Judá de Jacó, e Jacó de Isaque, e Isaque de Abraão, e Abraão de Terá, e Terá de Nacor,'),
('acf','lc',3,35,'E Nacor de Seruque, e Seruque de Ragaú, e Ragaú de Fáleque, e Fáleque de Eber, e Eber de Salá,'),
('acf','lc',3,36,'E Salá de Cainã, e Cainã de Arfaxade, e Arfaxade de Sem, e Sem de Noé, e Noé de Lameque,'),
('acf','lc',3,37,'E Lameque de Matusalém, e Matusalém de Enoque, e Enoque de Jarete, e Jarete de Maleleel, e Maleleel de Cainã,'),
('acf','lc',3,38,'E Cainã de Enos, e Enos de Sete, e Sete de Adão, e Adão de Deus.'),
('acf','lc',4,1,'E Jesus, cheio do Espírito Santo, voltou do Jordão e foi levado pelo Espírito ao deserto;'),
('acf','lc',4,2,'E quarenta dias foi tentado pelo diabo, e naqueles dias não comeu coisa alguma; e, terminados eles, teve fome.'),
('acf','lc',4,3,'E disse-lhe o diabo: Se tu és o Filho de Deus, dize a esta pedra que se transforme em pão.'),
('acf','lc',4,4,'E Jesus lhe respondeu, dizendo: Está escrito que nem só de pão viverá o homem, mas de toda a palavra de Deus.'),
('acf','lc',4,5,'E o diabo, levando-o a um alto monte, mostrou-lhe num momento de tempo todos os reinos do mundo.'),
('acf','lc',4,6,'E disse-lhe o diabo: Dar-te-ei a ti todo este poder e a sua glória; porque a mim me foi entregue, e dou-o a quem quero.'),
('acf','lc',4,7,'Portanto, se tu me adorares, tudo será teu.'),
('acf','lc',4,8,'E Jesus, respondendo, disse-lhe: Vai-te para trás de mim, Satanás; porque está escrito: Adorarás o Senhor teu Deus, e só a ele servirás.'),
('acf','lc',4,9,'Levou-o também a Jerusalém, e pô-lo sobre o pináculo do templo, e disse-lhe: Se tu és o Filho de Deus, lança-te daqui abaixo;'),
('acf','lc',4,10,'Porque está escrito: Mandará aos seus anjos, acerca de ti, que te guardem,'),
('acf','lc',4,11,'E que te sustenham nas mãos, Para que nunca tropeces com o teu pé em alguma pedra.'),
('acf','lc',4,12,'E Jesus, respondendo, disse-lhe: Dito está: Não tentarás ao Senhor teu Deus.'),
('acf','lc',4,13,'E, acabando o diabo toda a tentação, ausentou-se dele por algum tempo.'),
('acf','lc',4,14,'Então, pela virtude do Espírito, voltou Jesus para a Galiléia, e a sua fama correu por todas as terras em derredor.'),
('acf','lc',4,15,'E ensinava nas suas sinagogas, e por todos era louvado.'),
('acf','lc',4,16,'E, chegando a Nazaré, onde fora criado, entrou num dia de sábado, segundo o seu costume, na sinagoga, e levantou-se para ler.'),
('acf','lc',4,17,'E foi-lhe dado o livro do profeta Isaías; e, quando abriu o livro, achou o lugar em que estava escrito:'),
('acf','lc',4,18,'O Espírito do Senhor é sobre mim, Pois que me ungiu para evangelizar os pobres. Enviou-me a curar os quebrantados de coração,'),
('acf','lc',4,19,'A pregar liberdade aos cativos, E restauração da vista aos cegos, A pôr em liberdade os oprimidos, A anunciar o ano aceitável do Senhor.'),
('acf','lc',4,20,'E, cerrando o livro, e tornando-o a dar ao ministro, assentou-se; e os olhos de todos na sinagoga estavam fitos nele.'),
('acf','lc',4,21,'Então começou a dizer-lhes: Hoje se cumpriu esta Escritura em vossos ouvidos.'),
('acf','lc',4,22,'E todos lhe davam testemunho, e se maravilhavam das palavras de graça que saíam da sua boca; e diziam: Não é este o filho de José?'),
('acf','lc',4,23,'E ele lhes disse: Sem dúvida me direis este provérbio: Médico, cura-te a ti mesmo; faze também aqui na tua pátria tudo que ouvimos ter sido feito em Cafarnaum.'),
('acf','lc',4,24,'E disse: Em verdade vos digo que nenhum profeta é bem recebido na sua pátria.'),
('acf','lc',4,25,'Em verdade vos digo que muitas viúvas existiam em Israel nos dias de Elias, quando o céu se cerrou por três anos e seis meses, de sorte que em toda a terra houve grande fome;'),
('acf','lc',4,26,'E a nenhuma delas foi enviado Elias, senão a Sarepta de Sidom, a uma mulher viúva.'),
('acf','lc',4,27,'E muitos leprosos havia em Israel no tempo do profeta Eliseu, e nenhum deles foi purificado, senão Naamã, o siro.'),
('acf','lc',4,28,'E todos, na sinagoga, ouvindo estas coisas, se encheram de ira.'),
('acf','lc',4,29,'E, levantando-se, o expulsaram da cidade, e o levaram até ao cume do monte em que a cidade deles estava edificada, para dali o precipitarem.'),
('acf','lc',4,30,'Ele, porém, passando pelo meio deles, retirou-se.'),
('acf','lc',4,31,'E desceu a Cafarnaum, cidade da Galiléia, e os ensinava nos sábados.'),
('acf','lc',4,32,'E admiravam a sua doutrina porque a sua palavra era com autoridade.'),
('acf','lc',4,33,'E estava na sinagoga um homem que tinha o espírito de um demônio imundo, e exclamou em alta voz,'),
('acf','lc',4,34,'Dizendo: Ah! que temos nós contigo, Jesus Nazareno? Vieste a destruir-nos? Bem sei quem és: O Santo de Deus.'),
('acf','lc',4,35,'E Jesus o repreendeu, dizendo: Cala-te, e sai dele. E o demônio, lançando-o por terra no meio do povo, saiu dele sem lhe fazer mal.'),
('acf','lc',4,36,'E veio espanto sobre todos, e falavam uns com os outros, dizendo: Que palavra é esta, que até aos espíritos imundos manda com autoridade e poder, e eles saem?'),
('acf','lc',4,37,'E a sua fama divulgava-se por todos os lugares, em redor daquela comarca.'),
('acf','lc',4,38,'Ora, levantando-se Jesus da sinagoga, entrou em casa de Simão; e a sogra de Simão estava enferma com muita febre, e rogaram-lhe por ela.'),
('acf','lc',4,39,'E, inclinando-se para ela, repreendeu a febre, e esta a deixou. E ela, levantando-se logo, servia-os.'),
('acf','lc',4,40,'E, ao pôr do sol, todos os que tinham enfermos de várias doenças lhos traziam; e, pondo as mãos sobre cada um deles, os curava.'),
('acf','lc',4,41,'E também de muitos saíam demônios, clamando e dizendo: Tu és o Cristo, o Filho de Deus. E ele, repreendendo-os, não os deixava falar, pois sabiam que ele era o Cristo.'),
('acf','lc',4,42,'E, sendo já dia, saiu, e foi para um lugar deserto; e a multidão o procurava, e chegou junto dele; e o detinham, para que não se ausentasse deles.'),
('acf','lc',4,43,'Ele, porém, lhes disse: Também é necessário que eu anuncie a outras cidades o evangelho do reino de Deus; porque para isso fui enviado.'),
('acf','lc',4,44,'E pregava nas sinagogas da Galiléia.'),
('acf','lc',5,1,'E aconteceu que, apertando-o a multidão, para ouvir a palavra de Deus, estava ele junto ao lago de Genesaré;'),
('acf','lc',5,2,'E viu estar dois barcos junto à praia do lago; e os pescadores, havendo descido deles, estavam lavando as redes.'),
('acf','lc',5,3,'E, entrando num dos barcos, que era o de Simão, pediu-lhe que o afastasse um pouco da terra; e, assentando-se, ensinava do barco a multidão.'),
('acf','lc',5,4,'E, quando acabou de falar, disse a Simão: Faze-te ao mar alto, e lançai as vossas redes para pescar.'),
('acf','lc',5,5,'E, respondendo Simão, disse-lhe: Mestre, havendo trabalhado toda a noite, nada apanhamos; mas, sobre a tua palavra, lançarei a rede.'),
('acf','lc',5,6,'E, fazendo assim, colheram uma grande quantidade de peixes, e rompia-se-lhes a rede.'),
('acf','lc',5,7,'E fizeram sinal aos companheiros que estavam no outro barco, para que os fossem ajudar. E foram, e encheram ambos os barcos, de maneira tal que quase iam a pique.'),
('acf','lc',5,8,'E vendo isto Simão Pedro, prostrou-se aos pés de Jesus, dizendo: Senhor, ausenta-te de mim, que sou um homem pecador.'),
('acf','lc',5,9,'Pois que o espanto se apoderara dele, e de todos os que com ele estavam, por causa da pesca de peixe que haviam feito.'),
('acf','lc',5,10,'E, de igual modo, também de Tiago e João, filhos de Zebedeu, que eram companheiros de Simão. E disse Jesus a Simão: Não temas; de agora em diante serás pescador de homens.'),
('acf','lc',5,11,'E, levando os barcos para terra, deixaram tudo, e o seguiram.'),
('acf','lc',5,12,'E aconteceu que, quando estava numa daquelas cidades, eis que um homem cheio de lepra, vendo a Jesus, prostrou-se sobre o rosto, e rogou-lhe, dizendo: Senhor, se quiseres, bem podes limpar-me.'),
('acf','lc',5,13,'E ele, estendendo a mão, tocou-lhe, dizendo: Quero, sê limpo. E logo a lepra desapareceu dele.'),
('acf','lc',5,14,'E ordenou-lhe que a ninguém o dissesse. Mas vai, disse, mostra-te ao sacerdote, e oferece pela tua purificação, o que Moisés determinou para que lhes sirva de testemunho.'),
('acf','lc',5,15,'A sua fama, porém, se propagava ainda mais, e ajuntava-se muita gente para o ouvir e para ser por ele curada das suas enfermidades.'),
('acf','lc',5,16,'Ele, porém, retirava-se para os desertos, e ali orava.'),
('acf','lc',5,17,'E aconteceu que, num daqueles dias, estava ensinando, e estavam ali assentados fariseus e doutores da lei, que tinham vindo de todas as aldeias da Galiléia, e da Judéia, e de Jerusalém. E a virtude do Senhor estava ali para os curar.'),
('acf','lc',5,18,'E eis que uns homens transportaram numa cama um homem que estava paralítico, e procuravam fazê-lo entrar e pô-lo diante dele.'),
('acf','lc',5,19,'E, não achando por onde o pudessem levar, por causa da multidão, subiram ao telhado, e por entre as telhas o baixaram com a cama, até ao meio, diante de Jesus.'),
('acf','lc',5,20,'E, vendo ele a fé deles, disse-lhe: Homem, os teus pecados te são perdoados.'),
('acf','lc',5,21,'E os escribas e os fariseus começaram a arrazoar, dizendo: Quem é este que diz blasfêmias? Quem pode perdoar pecados, senão só Deus?'),
('acf','lc',5,22,'Jesus, porém, conhecendo os seus pensamentos, respondeu, e disse-lhes: Que arrazoais em vossos corações?'),
('acf','lc',5,23,'Qual é mais fácil? dizer: Os teus pecados te são perdoados; ou dizer: Levanta-te, e anda?'),
('acf','lc',5,24,'Ora, para que saibais que o Filho do homem tem sobre a terra poder de perdoar pecados (disse ao paralítico), a ti te digo: Levanta-te, toma a tua cama, e vai para tua casa.'),
('acf','lc',5,25,'E, levantando-se logo diante deles, e tomando a cama em que estava deitado, foi para sua casa, glorificando a Deus.'),
('acf','lc',5,26,'E todos ficaram maravilhados, e glorificaram a Deus; e ficaram cheios de temor, dizendo: Hoje vimos prodígios.'),
('acf','lc',5,27,'E, depois disto, saiu, e viu um publicano, chamado Levi, assentado na recebedoria, e disse-lhe: Segue-me.'),
('acf','lc',5,28,'E ele, deixando tudo, levantou-se e o seguiu.'),
('acf','lc',5,29,'E fez-lhe Levi um grande banquete em sua casa; e havia ali uma multidão de publicanos e outros que estavam com eles à mesa.'),
('acf','lc',5,30,'E os escribas deles, e os fariseus, murmuravam contra os seus discípulos, dizendo: Por que comeis e bebeis com publicanos e pecadores?'),
('acf','lc',5,31,'E Jesus, respondendo, disse-lhes: Não necessitam de médico os que estão sãos, mas, sim, os que estão enfermos;'),
('acf','lc',5,32,'Eu não vim chamar os justos, mas, sim, os pecadores, ao arrependimento.'),
('acf','lc',5,33,'Disseram-lhe, então, eles: Por que jejuam os discípulos de João muitas vezes, e fazem orações, como também os dos fariseus, mas os teus comem e bebem?'),
('acf','lc',5,34,'E ele lhes disse: Podeis vós fazer jejuar os filhos das bodas, enquanto o esposo está com eles?'),
('acf','lc',5,35,'Dias virão, porém, em que o esposo lhes será tirado, e então, naqueles dias, jejuarão.'),
('acf','lc',5,36,'E disse-lhes também uma parábola: Ninguém deita um pedaço de uma roupa nova para a coser em roupa velha, pois romperá a nova e o remendo não condiz com a velha.'),
('acf','lc',5,37,'E ninguém deita vinho novo em odres velhos; de outra sorte o vinho novo romperá os odres, e entornar-se-á o vinho, e os odres se estragarão;'),
('acf','lc',5,38,'Mas o vinho novo deve deitar-se em odres novos, e ambos juntamente se conservarão.'),
('acf','lc',5,39,'E ninguém tendo bebido o velho quer logo o novo, porque diz: Melhor é o velho.'),
('acf','lc',6,1,'E aconteceu que, no segundo sábado após o primeiro, passou pelas searas, e os seus discípulos iam arrancando espigas e, esfregando-as com as mãos, as comiam.'),
('acf','lc',6,2,'E alguns dos fariseus lhes disseram: Por que fazeis o que não é lícito fazer nos sábados?'),
('acf','lc',6,3,'E Jesus, respondendo-lhes, disse: Nunca lestes o que fez Davi quando teve fome, ele e os que com ele estavam?'),
('acf','lc',6,4,'Como entrou na casa de Deus, e tomou os pães da proposição, e os comeu, e deu também aos que estavam com ele, os quais não é lícito comer senão só aos sacerdotes?'),
('acf','lc',6,5,'E dizia-lhes: O Filho do homem é Senhor até do sábado.'),
('acf','lc',6,6,'E aconteceu também noutro sábado, que entrou na sinagoga, e estava ensinando; e havia ali um homem que tinha a mão direita mirrada.'),
('acf','lc',6,7,'E os escribas e fariseus observavam-no, se o curaria no sábado, para acharem de que o acusar.'),
('acf','lc',6,8,'Mas ele bem conhecia os seus pensamentos; e disse ao homem que tinha a mão mirrada: Levanta-te, e fica em pé no meio. E, levantando-se ele, ficou em pé.'),
('acf','lc',6,9,'Então Jesus lhes disse: Uma coisa vos hei de perguntar: É lícito nos sábados fazer bem, ou fazer mal? salvar a vida, ou matar?'),
('acf','lc',6,10,'E, olhando para todos em redor, disse ao homem: Estende a tua mão. E ele assim o fez, e a mão lhe foi restituída sã como a outra.'),
('acf','lc',6,11,'E ficaram cheios de furor, e uns com os outros conferenciavam sobre o que fariam a Jesus.'),
('acf','lc',6,12,'E aconteceu que naqueles dias subiu ao monte a orar, e passou a noite em oração a Deus.'),
('acf','lc',6,13,'E, quando já era dia, chamou a si os seus discípulos, e escolheu doze deles, a quem também deu o nome de apóstolos:'),
('acf','lc',6,14,'Simão, ao qual também chamou Pedro, e André, seu irmão; Tiago e João; Filipe e Bartolomeu;'),
('acf','lc',6,15,'Mateus e Tomé; Tiago, filho de Alfeu, e Simão, chamado Zelote;'),
('acf','lc',6,16,'E Judas, irmão de Tiago, e Judas Iscariotes, que foi o traidor.'),
('acf','lc',6,17,'E, descendo com eles, parou num lugar plano, e também um grande número de seus discípulos, e grande multidão de povo de toda a Judéia, e de Jerusalém, e da costa marítima de Tiro e de Sidom; os quais tinham vindo para o ouvir, e serem curados das suas enfermidades,'),
('acf','lc',6,18,'Como também os atormentados dos espíritos imundos; e eram curados.'),
('acf','lc',6,19,'E toda a multidão procurava tocar-lhe, porque saía dele virtude, e curava a todos.'),
('acf','lc',6,20,'E, levantando ele os olhos para os seus discípulos, dizia: Bem-aventurados vós, os pobres, porque vosso é o reino de Deus.'),
('acf','lc',6,21,'Bem-aventurados vós, que agora tendes fome, porque sereis fartos. Bem-aventurados vós, que agora chorais, porque haveis de rir.'),
('acf','lc',6,22,'Bem-aventurados sereis quando os homens vos odiarem e quando vos separarem, e vos injuriarem, e rejeitarem o vosso nome como mau, por causa do Filho do homem.'),
('acf','lc',6,23,'Folgai nesse dia, exultai; porque eis que é grande o vosso galardão no céu, pois assim faziam os seus pais aos profetas.'),
('acf','lc',6,24,'Mas ai de vós, ricos! porque já tendes a vossa consolação.'),
('acf','lc',6,25,'Ai de vós, os que estais fartos, porque tereis fome. Ai de vós, os que agora rides, porque vos lamentareis e chorareis.'),
('acf','lc',6,26,'Ai de vós quando todos os homens de vós disserem bem, porque assim faziam seus pais aos falsos profetas.'),
('acf','lc',6,27,'Mas a vós, que isto ouvis, digo: Amai a vossos inimigos, fazei bem aos que vos odeiam;'),
('acf','lc',6,28,'Bendizei os que vos maldizem, e orai pelos que vos caluniam.'),
('acf','lc',6,29,'Ao que te ferir numa face, oferece-lhe também a outra; e ao que te houver tirado a capa, nem a túnica recuses;'),
('acf','lc',6,30,'E dá a qualquer que te pedir; e ao que tomar o que é teu, não lho tornes a pedir.'),
('acf','lc',6,31,'E como vós quereis que os homens vos façam, da mesma maneira lhes fazei vós, também.'),
('acf','lc',6,32,'E se amardes aos que vos amam, que recompensa tereis? Também os pecadores amam aos que os amam.'),
('acf','lc',6,33,'E se fizerdes bem aos que vos fazem bem, que recompensa tereis? Também os pecadores fazem o mesmo.'),
('acf','lc',6,34,'E se emprestardes àqueles de quem esperais tornar a receber, que recompensa tereis? Também os pecadores emprestam aos pecadores, para tornarem a receber outro tanto.'),
('acf','lc',6,35,'Amai, pois, a vossos inimigos, e fazei bem, e emprestai, sem nada esperardes, e será grande o vosso galardão, e sereis filhos do Altíssimo; porque ele é benigno até para com os ingratos e maus.'),
('acf','lc',6,36,'Sede, pois, misericordiosos, como também vosso Pai é misericordioso.'),
('acf','lc',6,37,'Não julgueis, e não sereis julgados; não condeneis, e não sereis condenados; soltai, e soltar-vos-ão.'),
('acf','lc',6,38,'Dai, e ser-vos-á dado; boa medida, recalcada, sacudida e transbordando, vos deitarão no vosso regaço; porque com a mesma medida com que medirdes também vos medirão de novo.'),
('acf','lc',6,39,'E dizia-lhes uma parábola: Pode porventura o cego guiar o cego? Não cairão ambos na cova?'),
('acf','lc',6,40,'O discípulo não é superior a seu mestre, mas todo o que for perfeito será como o seu mestre.'),
('acf','lc',6,41,'E por que atentas tu no argueiro que está no olho de teu irmão, e não reparas na trave que está no teu próprio olho?'),
('acf','lc',6,42,'Ou como podes dizer a teu irmão: Irmão, deixa-me tirar o argueiro que está no teu olho, não atentando tu mesmo na trave que está no teu olho? Hipócrita, tira primeiro a trave do teu olho, e então verás bem para tirar o argueiro que está no olho de teu irmão.'),
('acf','lc',6,43,'Porque não há boa árvore que dê mau fruto, nem má árvore que dê bom fruto.'),
('acf','lc',6,44,'Porque cada árvore se conhece pelo seu próprio fruto; pois não se colhem figos dos espinheiros, nem se vindimam uvas dos abrolhos.'),
('acf','lc',6,45,'O homem bom, do bom tesouro do seu coração tira o bem, e o homem mau, do mau tesouro do seu coração tira o mal, porque da abundância do seu coração fala a boca.'),
('acf','lc',6,46,'E por que me chamais, Senhor, Senhor, e não fazeis o que eu digo?'),
('acf','lc',6,47,'Qualquer que vem a mim e ouve as minhas palavras, e as observa, eu vos mostrarei a quem é semelhante:'),
('acf','lc',6,48,'É semelhante ao homem que edificou uma casa, e cavou, e abriu bem fundo, e pôs os alicerces sobre a rocha; e, vindo a enchente, bateu com ímpeto a corrente naquela casa, e não a pôde abalar, porque estava fundada sobre a rocha.'),
('acf','lc',6,49,'Mas o que ouve e não pratica é semelhante ao homem que edificou uma casa sobre terra, sem alicerces, na qual bateu com ímpeto a corrente, e logo caiu; e foi grande a ruína daquela casa.'),
('acf','lc',7,1,'E, depois de concluir todos estes discursos perante o povo, entrou em Cafarnaum.'),
('acf','lc',7,2,'E o servo de um certo centurião, a quem muito estimava, estava doente, e moribundo.'),
('acf','lc',7,3,'E, quando ouviu falar de Jesus, enviou-lhe uns anciãos dos judeus, rogando-lhe que viesse curar o seu servo.'),
('acf','lc',7,4,'E, chegando eles junto de Jesus, rogaram-lhe muito, dizendo: É digno de que lhe concedas isto,'),
('acf','lc',7,5,'Porque ama a nossa nação, e ele mesmo nos edificou a sinagoga.'),
('acf','lc',7,6,'E foi Jesus com eles; mas, quando já estava perto da casa, enviou-lhe o centurião uns amigos, dizendo-lhe: Senhor, não te incomodes, porque não sou digno de que entres debaixo do meu telhado.'),
('acf','lc',7,7,'E por isso nem ainda me julguei digno de ir ter contigo; dize, porém, uma palavra, e o meu criado sarará.'),
('acf','lc',7,8,'Porque também eu sou homem sujeito à autoridade, e tenho soldados sob o meu poder, e digo a este: Vai, e ele vai; e a outro: Vem, e ele vem; e ao meu servo: Faze isto, e ele o faz.'),
('acf','lc',7,9,'E, ouvindo isto Jesus, maravilhou-se dele, e voltando-se, disse à multidão que o seguia: Digo-vos que nem ainda em Israel tenho achado tanta fé.'),
('acf','lc',7,10,'E, voltando para casa os que foram enviados, acharam são o servo enfermo.'),
('acf','lc',7,11,'E aconteceu que, no dia seguinte, ele foi à cidade chamada Naim, e com ele iam muitos dos seus discípulos, e uma grande multidão;'),
('acf','lc',7,12,'E, quando chegou perto da porta da cidade, eis que levavam um defunto, filho único de sua mãe, que era viúva; e com ela ia uma grande multidão da cidade.'),
('acf','lc',7,13,'E, vendo-a, o Senhor moveu-se de íntima compaixão por ela, e disse-lhe: Não chores.'),
('acf','lc',7,14,'E, chegando-se, tocou o esquife (e os que o levavam pararam), e disse: Jovem, a ti te digo: Levanta-te. E o que fora defunto assentou-se, e começou a falar.'),
('acf','lc',7,15,'E entregou-o à sua mãe.'),
('acf','lc',7,16,'E de todos se apoderou o temor, e glorificavam a Deus, dizendo: Um grande profeta se levantou entre nós, e Deus visitou o seu povo.'),
('acf','lc',7,17,'E correu dele esta fama por toda a Judéia e por toda a terra circunvizinha.'),
('acf','lc',7,18,'E os discípulos de João anunciaram-lhe todas estas coisas.'),
('acf','lc',7,19,'E João, chamando dois dos seusdiscípulos, enviou-os a Jesus, dizendo: És tu aquele que havia de vir, ou esperamos outro?'),
('acf','lc',7,20,'E, quando aqueles homens chegaram junto dele, disseram: João o Batista enviou-nos a perguntar-te: És tu aquele que havia de vir, ou esperamos outro?'),
('acf','lc',7,21,'E, na mesma hora, curou muitos de enfermidades, e males, e espíritos maus, e deu vista a muitos cegos.'),
('acf','lc',7,22,'Respondendo, então, Jesus, disse-lhes: Ide, e anunciai a João o que tendes visto e ouvido: que os cegos vêem, os coxos andam, os leprosos são purificados, os surdos ouvem, os mortos ressuscitam e aos pobres anuncia-se o evangelho.'),
('acf','lc',7,23,'E bem-aventurado é aquele que em mim se não escandalizar.'),
('acf','lc',7,24,'E, tendo-se retirado os mensageiros de João, começou a dizer à multidão acerca de João: Que saístes a ver no deserto? uma cana abalada pelo vento?'),
('acf','lc',7,25,'Mas que saístes a ver? um homem trajado de vestes delicadas? Eis que os que andam com preciosas vestiduras, e em delícias, estão nos paços reais.'),
('acf','lc',7,26,'Mas que saístes a ver? um profeta? Sim, vos digo, e muito mais do que profeta.'),
('acf','lc',7,27,'Este é aquele de quem está escrito: Eis que envio o meu anjo diante da tua face, O qual preparará diante de ti o teu caminho.'),
('acf','lc',7,28,'E eu vos digo que, entre os nascidos de mulheres, não há maior profeta do que João o Batista; mas o menor no reino de Deus é maior do que ele.'),
('acf','lc',7,29,'E todo o povo que o ouviu e os publicanos, tendo sido batizados com o batismo de João, justificaram a Deus.'),
('acf','lc',7,30,'Mas os fariseus e os doutores da lei rejeitaram o conselho de Deus contra si mesmos, não tendo sido batizados por ele.'),
('acf','lc',7,31,'E disse o Senhor: A quem, pois, compararei os homens desta geração, e a quem são semelhantes?'),
('acf','lc',7,32,'São semelhantes aos meninos que, assentados nas praças, clamam uns aos outros, e dizem: Tocamo-vos flauta, e não dançastes; cantamo-vos lamentações, e não chorastes.'),
('acf','lc',7,33,'Porque veio João o Batista, que não comia pão nem bebia vinho, e dizeis: Tem demônio;'),
('acf','lc',7,34,'Veio o Filho do homem, que come e bebe, e dizeis: Eis aí um homem comilão e bebedor de vinho, amigo dos publicanos e pecadores.'),
('acf','lc',7,35,'Mas a sabedoria é justificada por todos os seus filhos.'),
('acf','lc',7,36,'E rogou-lhe um dos fariseus que comesse com ele; e, entrando em casa do fariseu, assentou-se à mesa.'),
('acf','lc',7,37,'E eis que uma mulher da cidade, uma pecadora, sabendo que ele estava à mesa em casa do fariseu, levou um vaso de alabastro com ungüento;'),
('acf','lc',7,38,'E, estando por detrás, aos seus pés, chorando, começou a regar-lhe os pés com lágrimas, e enxugava-lhos com os cabelos da sua cabeça; e beijava-lhe os pés, e ungia-lhos com o ungüento.'),
('acf','lc',7,39,'Quando isto viu o fariseu que o tinha convidado, falava consigo, dizendo: Se este fora profeta, bem saberia quem e qual é a mulher que lhe tocou, pois é uma pecadora.'),
('acf','lc',7,40,'E respondendo, Jesus disse-lhe: Simão, uma coisa tenho a dizer-te. E ele disse: Dize-a, Mestre.'),
('acf','lc',7,41,'Um certo credor tinha dois devedores: um devia-lhe quinhentos dinheiros, e outro cinqüenta.'),
('acf','lc',7,42,'E, não tendo eles com que pagar, perdoou-lhes a ambos. Dize, pois, qual deles o amará mais?'),
('acf','lc',7,43,'E Simão, respondendo, disse: Tenho para mim que é aquele a quem mais perdoou. E ele lhe disse: Julgaste bem.'),
('acf','lc',7,44,'E, voltando-se para a mulher, disse a Simão: Vês tu esta mulher? Entrei em tua casa, e não me deste água para os pés; mas esta regou-me os pés com lágrimas, e os enxugou com os cabelos de sua cabeça.'),
('acf','lc',7,45,'Não me deste ósculo, mas esta, desde que entrou, não tem cessado de me beijar os pés.'),
('acf','lc',7,46,'Não me ungiste a cabeça com óleo, mas esta ungiu-me os pés com ungüento.'),
('acf','lc',7,47,'Por isso te digo que os seus muitos pecados lhe são perdoados, porque muito amou; mas aquele a quem pouco é perdoado pouco ama.'),
('acf','lc',7,48,'E disse-lhe a ela: Os teus pecados te são perdoados.'),
('acf','lc',7,49,'E os que estavam à mesa começaram a dizer entre si: Quem é este, que até perdoa pecados?'),
('acf','lc',7,50,'E disse à mulher: A tua fé te salvou; vai-te em paz.'),
('acf','lc',8,1,'E aconteceu, depois disto, que andava de cidade em cidade, e de aldeia em aldeia, pregando e anunciando o evangelho do reino de Deus; e os doze iam com ele,'),
('acf','lc',8,2,'E algumas mulheres que haviam sido curadas de espíritos malignos e de enfermidades: Maria, chamada Madalena, da qual saíram sete demônios;'),
('acf','lc',8,3,'E Joana, mulher de Cuza, procurador de Herodes, e Suzana, e muitas outras que o serviam com seus bens.'),
('acf','lc',8,4,'E, ajuntando-se uma grande multidão, e vindo de todas as cidades ter com ele, disse por parábola:'),
('acf','lc',8,5,'Um semeador saiu a semear a sua semente e, quando semeava, caiu alguma junto do caminho, e foi pisada, e as aves do céu a comeram;'),
('acf','lc',8,6,'E outra caiu sobre pedra e, nascida, secou-se, pois que não tinha umidade;'),
('acf','lc',8,7,'E outra caiu entre espinhos e crescendo com ela os espinhos, a sufocaram;'),
('acf','lc',8,8,'E outra caiu em boa terra, e, nascida, produziu fruto, a cento por um. Dizendo ele estas coisas, clamava: Quem tem ouvidos para ouvir, ouça.'),
('acf','lc',8,9,'E os seus discípulos o interrogaram, dizendo: Que parábola é esta?'),
('acf','lc',8,10,'E ele disse: A vós vos é dado conhecer os mistérios do reino de Deus, mas aos outros por parábolas, para que vendo, não vejam, e ouvindo, não entendam.'),
('acf','lc',8,11,'Esta é, pois, a parábola: A semente é a palavra de Deus;'),
('acf','lc',8,12,'E os que estão junto do caminho, estes são os que ouvem; depois vem o diabo, e tira-lhes do coração a palavra, para que não se salvem, crendo;'),
('acf','lc',8,13,'E os que estão sobre pedra, estes são os que, ouvindo a palavra, a recebem com alegria, mas, como não têm raiz, apenas crêem por algum tempo, e no tempo da tentação se desviam;'),
('acf','lc',8,14,'E a que caiu entre espinhos, esses são os que ouviram e, indo pordiante, são sufocados com os cuidados e riquezas e deleites da vida, e não dão fruto com perfeição;'),
('acf','lc',8,15,'E a que caiu em boa terra, esses são os que, ouvindo a palavra, a conservam num coração honesto e bom, e dão fruto com perseverança.'),
('acf','lc',8,16,'E ninguém, acendendo uma candeia, a cobre com algum vaso, ou a põe debaixo da cama; mas põe-na no velador, para que os que entram vejam a luz.'),
('acf','lc',8,17,'Porque não há coisa oculta que não haja de manifestar-se, nem escondida que não haja de saber-se e vir à luz.'),
('acf','lc',8,18,'Vede, pois, como ouvis; porque a qualquer que tiver lhe será dado, e a qualquer que não tiver até o que parece ter lhe será tirado.'),
('acf','lc',8,19,'E foram ter com ele sua mãe e seus irmãos, e não podiam aproximar-se dele, por causa da multidão.'),
('acf','lc',8,20,'E foi-lhe dito: Estão lá fora tua mãe e teus irmãos, que querem ver-te.'),
('acf','lc',8,21,'Mas, respondendo ele, disse-lhes: Minha mãe e meus irmãos são aqueles que ouvem a palavra de Deus e a executam.'),
('acf','lc',8,22,'E aconteceu que, num daqueles dias, entrou num barco com seus discípulos, e disse-lhes: Passemos para o outro lado do lago. E partiram.'),
('acf','lc',8,23,'E, navegando eles, adormeceu; e sobreveio uma tempestade de vento no lago, e enchiam-se de água, estando em perigo.'),
('acf','lc',8,24,'E, chegando-se a ele, o despertaram, dizendo: Mestre, Mestre, perecemos. E ele, levantando-se, repreendeu o vento e a fúria da água; e cessaram, e fez-se bonança.'),
('acf','lc',8,25,'E disse-lhes: Onde está a vossa fé? E eles, temendo, maravilharam-se, dizendo uns aos outros: Quem é este, que até aos ventos e à água manda, e lhe obedecem?'),
('acf','lc',8,26,'E navegaram para a terra dos gadarenos, que está defronte da Galiléia.'),
('acf','lc',8,27,'E, quando desceu para terra, saiu-lhe ao encontro, vindo da cidade, um homem que desde muito tempo estava possesso de demônios, e não andava vestido, nem habitava em qualquer casa, mas nos sepulcros.'),
('acf','lc',8,28,'E, quando viu a Jesus, prostrou-se diante dele, exclamando, e dizendo com grande voz: Que tenho eu contigo, Jesus, Filho do Deus Altíssimo? Peço-te que não me atormentes.'),
('acf','lc',8,29,'Porque tinha ordenado ao espírito imundo que saísse daquele homem; pois já havia muito tempo que o arrebatava. E guardavamno preso, com grilhões e cadeias; mas, quebrando as prisões, era impelido pelo demônio para os desertos.'),
('acf','lc',8,30,'E perguntou-lhe Jesus, dizendo: Qual é o teu nome? E ele disse: Legião; porque tinham entrado nele muitos demônios.'),
('acf','lc',8,31,'E rogavam-lhe que os não mandasse para o abismo.'),
('acf','lc',8,32,'E andava ali pastando no monte uma vara de muitos porcos; e rogaram-lhe que lhes concedesse entrar neles; e concedeu-lho.'),
('acf','lc',8,33,'E, tendo saído os demônios do homem, entraram nos porcos, e a manada precipitou-se de um despenhadeiro no lago, e afogou-se.'),
('acf','lc',8,34,'E aqueles que os guardavam, vendo o que acontecera, fugiram, e foram anunciá-lo na cidade e nos campos.'),
('acf','lc',8,35,'E saíram a ver o que tinha acontecido, e vieram ter com Jesus. Acharam então o homem, de quem haviam saído os demônios, vestido, e em seu juízo, assentado aos pés de Jesus; e temeram.'),
('acf','lc',8,36,'E os que tinham visto contaram-lhes também como fora salvo aquele endemoninhado.'),
('acf','lc',8,37,'E toda a multidão da terra dos gadarenos ao redor lhe rogou que se retirasse deles; porque estavam possuídos de grande temor. E entrando ele no barco, voltou.'),
('acf','lc',8,38,'E aquele homem, de quem haviam saído os demônios, rogou-lhe que o deixasse estar com ele; mas Jesus o despediu, dizendo:'),
('acf','lc',8,39,'Torna para tua casa, e conta quão grandes coisas te fez Deus. E ele foi apregoando por toda a cidade quão grandes coisas Jesus lhe tinha feito.'),
('acf','lc',8,40,'E aconteceu que, quando voltou Jesus, a multidão o recebeu, porque todos o estavam esperando.'),
('acf','lc',8,41,'E eis que chegou um homem de nome Jairo, que era príncipe da sinagoga; e, prostrando-se aos pés de Jesus, rogava-lhe que entrasse em sua casa;'),
('acf','lc',8,42,'Porque tinha uma filha única, quase de doze anos, que estava à morte. E indo ele, apertava-o a multidão.'),
('acf','lc',8,43,'E uma mulher, que tinha um fluxo de sangue, havia doze anos, e gastara com os médicos todos os seus haveres, e por nenhum pudera ser curada,'),
('acf','lc',8,44,'Chegando por detrás dele, tocou na orla do seu vestido, e logo estancou o fluxo do seu sangue.'),
('acf','lc',8,45,'E disse Jesus: Quem é que me tocou? E, negando todos, disse Pedro e os que estavam com ele: Mestre, a multidão te aperta e te oprime, e dizes: Quem é que me tocou?'),
('acf','lc',8,46,'E disse Jesus: Alguém me tocou, porque bem conheci que de mim saiu virtude.'),
('acf','lc',8,47,'Então, vendo a mulher que não podia ocultar-se, aproximou-se tremendo e, prostrando-se ante ele, declarou-lhe diante de todo o povo a causa por que lhe havia tocado, e como logo sarara.'),
('acf','lc',8,48,'E ele lhe disse: Tem bom ânimo, filha, a tua fé te salvou; vai em paz.'),
('acf','lc',8,49,'Estando ele ainda falando, chegou um dos do príncipe da sinagoga, dizendo: A tua filha já está morta, não incomodes o Mestre.'),
('acf','lc',8,50,'Jesus, porém, ouvindo-o, respondeu-lhe, dizendo: Não temas; crê somente, e será salva.'),
('acf','lc',8,51,'E, entrando em casa, a ninguém deixou entrar, senão a Pedro, e a Tiago, e a João, e ao pai e a mãe da menina.'),
('acf','lc',8,52,'E todos choravam, e a pranteavam; e ele disse: Não choreis; não está morta, mas dorme.'),
('acf','lc',8,53,'E riam-se dele, sabendo que estava morta.'),
('acf','lc',8,54,'Mas ele, pondo-os todos fora, e pegando-lhe na mão, clamou, dizendo: Levanta-te, menina.'),
('acf','lc',8,55,'E o seu espírito voltou, e ela logo se levantou; e Jesus mandou que lhe dessem de comer.'),
('acf','lc',8,56,'E seus pais ficaram maravilhados; e ele lhes mandou que a ninguém dissessem o que havia sucedido.'),
('acf','lc',9,1,'E, convocando os seus doze discípulos, deu-lhes virtude e poder sobre todos os demônios, para curarem enfermidades.'),
('acf','lc',9,2,'E enviou-os a pregar o reino de Deus, e a curar os enfermos.'),
('acf','lc',9,3,'E disse-lhes: Nada leveis convosco para o caminho, nem bordões, nem alforje, nem pão, nem dinheiro; nem tenhais duas túnicas.'),
('acf','lc',9,4,'E em qualquer casa em que entrardes, ficai ali, e de lá saireis.'),
('acf','lc',9,5,'E se em qualquer cidade vos não receberem, saindo vós dali, sacudi o pó dos vossos pés, em testemunho contra eles.'),
('acf','lc',9,6,'E, saindo eles, percorreram todas as aldeias, anunciando o evangelho, e fazendo curas por toda a parte.'),
('acf','lc',9,7,'E o tetrarca Herodes ouviu todas as coisas que por ele foram feitas, e estava em dúvida, porque diziam alguns que João ressuscitara dentre os mortos; e outros que Elias tinha aparecido;'),
('acf','lc',9,8,'E outros que um profeta dos antigos havia ressuscitado.'),
('acf','lc',9,9,'E disse Herodes: A João mandei eu degolar; quem é, pois, este de quem ouço dizer tais coisas? E procurava vê-lo.'),
('acf','lc',9,10,'E, regressando os apóstolos, contaram-lhe tudo o que tinham feito. E, tomando-os consigo, retirou-se para um lugar deserto de uma cidade chamada Betsaida.'),
('acf','lc',9,11,'E, sabendo-o a multidão, o seguiu; e ele os recebeu, e falava-lhes do reino de Deus, e sarava os que necessitavam de cura.'),
('acf','lc',9,12,'E já o dia começava a declinar; então, chegando-se a ele os doze, disseram-lhe: Despede a multidão, para que, indo aos lugares e aldeias em redor, se agasalhem, e achem o que comer; porque aqui estamos em lugar deserto.'),
('acf','lc',9,13,'Mas ele lhes disse: Dai-lhes vós de comer. E eles disseram: Não temos senão cinco pães e dois peixes, salvo se nós próprios formos comprar comida para todo este povo.'),
('acf','lc',9,14,'Porquanto estavam ali quase cinco mil homens. Disse, então, aos seus discípulos: Fazei-os assentar, em ranchos de cinqüenta em cinqüenta.'),
('acf','lc',9,15,'E assim o fizeram, fazendo-os assentar a todos.'),
('acf','lc',9,16,'E, tomando os cinco pães e os dois peixes, e olhando para o céu, abençoou-os, e partiu-os, e deu-os aos seus discípulos para os porem diante da multidão.'),
('acf','lc',9,17,'E comeram todos, e saciaram-se; e levantaram, do que lhes sobejou, doze alcofas de pedaços.'),
('acf','lc',9,18,'E aconteceu que, estando ele só, orando, estavam com ele os discípulos; e perguntou-lhes, dizendo: Quem diz a multidão que eu sou?'),
('acf','lc',9,19,'E, respondendo eles, disseram: João o Batista; outros, Elias, e outros que um dos antigos profetas ressuscitou.'),
('acf','lc',9,20,'E disse-lhes: E vós, quem dizeis que eu sou? E, respondendo Pedro, disse: O Cristo de Deus.'),
('acf','lc',9,21,'E, admoestando-os, mandou que a ninguém referissem isso,'),
('acf','lc',9,22,'Dizendo: É necessário que o Filho do homem padeça muitas coisas, e seja rejeitado dos anciãos edos escribas, e seja morto, e ressuscite ao terceiro dia.'),
('acf','lc',9,23,'E dizia a todos: Se alguém quer vir após mim, negue-se a si mesmo, e tome cada dia a sua cruz, e siga-me.'),
('acf','lc',9,24,'Porque, qualquer que quiser salvar a sua vida, perdê-la-á; mas qualquer que, por amor de mim, perder a sua vida, a salvará.'),
('acf','lc',9,25,'Porque, que aproveita ao homem granjear o mundo todo, perdendo-se ou prejudicando-se a si mesmo?'),
('acf','lc',9,26,'Porque, qualquer que de mim e das minhas palavras se envergonhar, dele se envergonhará o Filho do homem, quando vier na sua glória, e na do Pai e dos santos anjos.'),
('acf','lc',9,27,'E em verdade vos digo que, dos que aqui estão, alguns há que não provarão a morte até que vejam o reino de Deus.'),
('acf','lc',9,28,'E aconteceu que, quase oito dias depois destas palavras, tomou consigo a Pedro, a João e a Tiago, e subiu ao monte a orar.'),
('acf','lc',9,29,'E, estando ele orando, transfigurou-se a aparência do seu rosto, e a sua roupa ficou branca e mui resplandecente.'),
('acf','lc',9,30,'E eis que estavam falando com ele dois homens, que eram Moisés e Elias,'),
('acf','lc',9,31,'Os quais apareceram com glória, e falavam da sua morte, a qual havia de cumprir-se em Jerusalém.'),
('acf','lc',9,32,'E Pedro e os que estavam com ele estavam carregados de sono; e, quando despertaram, viram a sua glória e aqueles dois homens que estavam com ele.'),
('acf','lc',9,33,'E aconteceu que, quando aqueles se apartaram dele, disse Pedro a Jesus: Mestre, bom é que nós estejamos aqui, e façamos três tendas: uma para ti, uma para Moisés, e uma para Elias, não sabendo o que dizia.'),
('acf','lc',9,34,'E, dizendo ele isto, veio uma nuvem que os cobriu com a sua sombra; e, entrando eles na nuvem, temeram.'),
('acf','lc',9,35,'E saiu da nuvem uma voz que dizia: Este é o meu amado Filho; a ele ouvi.'),
('acf','lc',9,36,'E, tendo soado aquela voz, Jesus foi achado só; e eles calaram-se, e por aqueles dias não contaram a ninguém nada do que tinham visto.'),
('acf','lc',9,37,'E aconteceu, no dia seguinte, que, descendo eles do monte, lhes saiu ao encontro uma grande multidão;'),
('acf','lc',9,38,'E eis que um homem da multidão clamou, dizendo: Mestre, peço-te que olhes para meu filho, porque é o único que eu tenho.'),
('acf','lc',9,39,'Eis que um espírito o toma e de repente clama, e o despedaça até espumar; e só o larga depois de o ter quebrantado.'),
('acf','lc',9,40,'E roguei aos teus discípulos que o expulsassem, e não puderam.'),
('acf','lc',9,41,'E Jesus, respondendo, disse: Ó geração incrédula e perversa! até quando estarei ainda convosco e vos sofrerei? Traze-me aqui o teu filho.'),
('acf','lc',9,42,'E, quando vinha chegando, o demônio o derrubou e convulsionou; porém, Jesus repreendeu o espírito imundo, e curou o menino, e o entregou a seu pai.'),
('acf','lc',9,43,'E todos pasmavam da majestade de Deus. E, maravilhando-se todos de todas as coisas que Jesus fazia, disse aos seus discípulos:'),
('acf','lc',9,44,'Ponde vós estas palavras em vossos ouvidos, porque o Filho do homem será entregue nas mãos dos homens.'),
('acf','lc',9,45,'Mas eles não entendiam esta palavra, que lhes era encoberta, para que a não compreendessem; e temiam interrogá-lo acerca desta palavra.'),
('acf','lc',9,46,'E suscitou-se entre eles uma discussão sobre qual deles seria o maior.'),
('acf','lc',9,47,'Mas Jesus, vendo o pensamento de seus corações, tomou um menino, pô-lo junto a si,'),
('acf','lc',9,48,'E disse-lhes: Qualquer que receber este menino em meu nome, recebe-me a mim; e qualquer que me receber a mim, recebe o que me enviou; porque aquele que entre vós todos for o menor, esse mesmo será grande.'),
('acf','lc',9,49,'E, respondendo João, disse: Mestre, vimos um que em teu nome expulsava os demônios, e lho proibimos, porque não te segue conosco.'),
('acf','lc',9,50,'E Jesus lhe disse: Não o proibais, porque quem não é contra nós é por nós.'),
('acf','lc',9,51,'E aconteceu que, completando-se os dias para a sua assunção, manifestou o firme propósito de ir a Jerusalém.'),
('acf','lc',9,52,'E mandou mensageiros adiante de si; e, indo eles, entraram numa aldeia de samaritanos, para lhe prepararem pousada,'),
('acf','lc',9,53,'Mas não o receberam, porque o seu aspecto era como de quem ia a Jerusalém.'),
('acf','lc',9,54,'E os seus discípulos, Tiago e João, vendo isto, disseram: Senhor, queres que digamos que desça fogo do céu e os consuma, como Elias também fez?'),
('acf','lc',9,55,'Voltando-se, porém, repreendeu-os, e disse: Vós não sabeis de que espírito sois.'),
('acf','lc',9,56,'Porque o Filho do homem não veio para destruir as almas dos homens, mas para salvá-las. E foram para outra aldeia.'),
('acf','lc',9,57,'E aconteceu que, indo eles pelo caminho, lhe disse um: Senhor, seguir-te-ei para onde quer que fores.'),
('acf','lc',9,58,'E disse-lhe Jesus: As raposas têm covis, e as aves do céu, ninhos, mas o Filho do homem não tem onde reclinar a cabeça.'),
('acf','lc',9,59,'E disse a outro: Segue-me. Mas ele respondeu: Senhor, deixa que primeiro eu vá a enterrar meu pai.'),
('acf','lc',9,60,'Mas Jesus lhe observou: Deixa aos mortos o enterrar os seus mortos; porém tu vai e anuncia o reino de Deus.'),
('acf','lc',9,61,'Disse também outro: Senhor, eu te seguirei, mas deixa-me despedir primeiro dos que estão em minha casa.'),
('acf','lc',9,62,'E Jesus lhe disse: Ninguém, que lança mão do arado e olha para trás, é apto para o reino de Deus.'),
('acf','lc',10,1,'E depois disto designou o Senhor ainda outros setenta, e mandou-os adiante da sua face, de dois em dois, a todas as cidades e lugares aonde ele havia de ir.'),
('acf','lc',10,2,'E dizia-lhes: Grande é, em verdade, a seara, mas os obreiros são poucos; rogai, pois, ao Senhor da seara que envie obreiros para a sua seara.'),
('acf','lc',10,3,'Ide; eis que vos mando como cordeiros ao meio de lobos.'),
('acf','lc',10,4,'Não leveis bolsa, nem alforje, nem alparcas; e a ninguém saudeis pelo caminho.'),
('acf','lc',10,5,'E, em qualquer casa onde entrardes, dizei primeiro: Paz seja nesta casa.'),
('acf','lc',10,6,'E, se ali houver algum filho de paz, repousará sobre ele a vossa paz; e, se não, voltará para vós.'),
('acf','lc',10,7,'E ficai na mesma casa, comendo e bebendo do que eles tiverem, pois digno é o obreiro de seu salário. Não andeis de casa em casa.'),
('acf','lc',10,8,'E, em qualquer cidade em que entrardes, e vos receberem, comei do que vos for oferecido.'),
('acf','lc',10,9,'E curai os enfermos que nela houver, e dizei-lhes: É chegado a vós o reino de Deus.'),
('acf','lc',10,10,'Mas em qualquer cidade, em que entrardes e vos não receberem, saindo por suas ruas, dizei:'),
('acf','lc',10,11,'Até o pó, que da vossa cidade se nos pegou, sacudimos sobre vós. Sabei, contudo, isto, que já o reino de Deus é chegado a vós.'),
('acf','lc',10,12,'E digo-vos que mais tolerância haverá naquele dia para Sodoma do que para aquela cidade.'),
('acf','lc',10,13,'Ai de ti, Corazim, ai de ti, Betsaida! Porque, se em Tiro e em Sidom se fizessem as maravilhas que em vós foram feitas, já há muito, assentadas em saco e cinza, se teriam arrependido.'),
('acf','lc',10,14,'Portanto, para Tiro e Sidom haverá menos rigor, no juízo, do que para vós.'),
('acf','lc',10,15,'E tu, Cafarnaum, que te levantaste até ao céu, até ao inferno serás abatida.'),
('acf','lc',10,16,'Quem vos ouve a vós, a mim me ouve; e quem vos rejeita a vós, a mim me rejeita; e quem a mim me rejeita, rejeita aquele que me enviou.'),
('acf','lc',10,17,'E voltaram os setenta com alegria, dizendo: Senhor, pelo teu nome, até os demônios se nos sujeitam.'),
('acf','lc',10,18,'E disse-lhes: Eu via Satanás, como raio, cair do céu.'),
('acf','lc',10,19,'Eis que vos dou poder para pisar serpentes e escorpiões, e toda a força do inimigo, e nada vos fará dano algum.'),
('acf','lc',10,20,'Mas, não vos alegreis porque se vos sujeitem os espíritos; alegrai-vos antes por estarem os vossos nomes escritos nos céus.'),
('acf','lc',10,21,'Naquela mesma hora se alegrou Jesus no Espírito Santo, e disse: Graças te dou, ó Pai, Senhor do céu e da terra, que escondeste estas coisas aos sábios e inteligentes, e as revelaste às criancinhas; assim é, ó Pai, porque assim te aprouve.'),
('acf','lc',10,22,'Tudo por meu Pai foi entregue; e ninguém conhece quem é o Filho senão o Pai, nem quem é o Pai senão o Filho, e aquele a quem o Filho o quiser revelar.'),
('acf','lc',10,23,'E, voltando-se para os discípulos, disse-lhes em particular: Bem-aventurados os olhos que vêem o que vós vedes.'),
('acf','lc',10,24,'Pois vos digo que muitos profetas e reis desejaram ver o que vós vedes, e não o viram; e ouvir o que ouvis, e não o ouviram.'),
('acf','lc',10,25,'E eis que se levantou um certo doutor da lei, tentando-o, e dizendo: Mestre, que farei para herdar a vida eterna?'),
('acf','lc',10,26,'E ele lhe disse: Que está escrito na lei? Como lês?'),
('acf','lc',10,27,'E, respondendo ele, disse: Amarás ao Senhor teu Deus de todo o teu coração, e de toda a tua alma, e de todas as tuas forças, e de todo o teu entendimento, e ao teu próximo como a ti mesmo.'),
('acf','lc',10,28,'E disse-lhe: Respondeste bem; faze isso, e viverás.'),
('acf','lc',10,29,'Ele, porém, querendo justificar-se a si mesmo, disse a Jesus: E quem é o meu próximo?'),
('acf','lc',10,30,'E, respondendo Jesus, disse: Descia um homem de Jerusalém para Jericó, e caiu nas mãos dos salteadores, os quais o despojaram, e espancando-o, se retiraram, deixando-o meio morto.'),
('acf','lc',10,31,'E, ocasionalmente descia pelo mesmo caminho certo sacerdote; e, vendo-o, passou de largo.'),
('acf','lc',10,32,'E de igual modo também um levita, chegando àquele lugar, e, vendo-o, passou de largo.'),
('acf','lc',10,33,'Mas um samaritano, que ia de viagem, chegou ao pé dele e, vendo-o, moveu-se de íntima compaixão;'),
('acf','lc',10,34,'E, aproximando-se, atou-lhe as feridas, deitando-lhes azeite e vinho; e, pondo-o sobre o seu animal, levou-o para uma estalagem, e cuidou dele;'),
('acf','lc',10,35,'E, partindo no outro dia, tirou dois dinheiros, e deu-os ao hospedeiro, e disse-lhe: Cuida dele; e tudo o que de mais gastares eu to pagarei quando voltar.'),
('acf','lc',10,36,'Qual, pois, destes três te parece que foi o próximo daquele que caiu nas mãos dos salteadores?'),
('acf','lc',10,37,'E ele disse: O que usou de misericórdia para com ele. Disse, pois, Jesus: Vai, e faze da mesma maneira.'),
('acf','lc',10,38,'E aconteceu que, indo eles de caminho, entrou Jesus numa aldeia; e certa mulher, por nome Marta, o recebeu em sua casa;'),
('acf','lc',10,39,'E tinha esta uma irmã chamada Maria, a qual, assentando-se também aos pés de Jesus, ouvia a sua palavra.'),
('acf','lc',10,40,'Marta, porém, andava distraída em muitos serviços; e, aproximando-se, disse: Senhor, não se te dá de que minha irmã me deixe servir só? Dize-lhe que me ajude.'),
('acf','lc',10,41,'E respondendo Jesus, disse-lhe: Marta, Marta, estás ansiosa e afadigada com muitas coisas, mas uma só é necessária;'),
('acf','lc',10,42,'E Maria escolheu a boa parte, a qual não lhe será tirada.'),
('acf','lc',11,1,'E aconteceu que, estando ele a orar num certo lugar, quando acabou, lhe disse um dos seus discípulos: Senhor, ensina-nos a orar, como também João ensinou aos seus discípulos.'),
('acf','lc',11,2,'E ele lhes disse: Quando orardes, dizei: Pai nosso, que estás nos céus, santificado seja o teu nome; venha o teu reino; seja feita a tua vontade, assim na terra, como no céu.'),
('acf','lc',11,3,'Dá-nos cada dia o nosso pão cotidiano;'),
('acf','lc',11,4,'E perdoa-nos os nossos pecados, pois também nós perdoamos a qualquer que nos deve, e não nos conduzas à tentação, mas livra-nos do mal.'),
('acf','lc',11,5,'Disse-lhes também: Qual de vós terá um amigo, e, se for procurá-lo à meia-noite, e lhe disser: Amigo, empresta-me três pães,'),
('acf','lc',11,6,'Pois que um amigo meu chegou a minha casa, vindo de caminho, e não tenho que apresentar-lhe;'),
('acf','lc',11,7,'Se ele, respondendo de dentro, disser: Não me importunes; já está a porta fechada, e os meus filhos estão comigo na cama; não posso levantar-me para tos dar;'),
('acf','lc',11,8,'Digo-vos que, ainda que não se levante a dar-lhos, por ser seu amigo, levantar-se-á, todavia, por causa da sua importunação, e lhe dará tudo o que houver mister.'),
('acf','lc',11,9,'E eu vos digo a vós: Pedi, e dar-se-vos-á; buscai, e achareis; batei, e abrir-se-vos-á;'),
('acf','lc',11,10,'Porque qualquer que pede recebe; e quem busca acha; e a quem bate abrir-se-lhe-á.'),
('acf','lc',11,11,'E qual o pai de entre vós que, se o filho lhe pedir pão, lhe dará uma pedra? Ou, também, se lhe pedir peixe, lhe dará por peixe uma serpente?'),
('acf','lc',11,12,'Ou, também, se lhe pedir um ovo, lhe dará um escorpião?'),
('acf','lc',11,13,'Pois se vós, sendo maus, sabeis dar boas dádivas aos vossos filhos, quanto mais dará o Pai celestial o Espírito Santo àqueles que lho pedirem?'),
('acf','lc',11,14,'E estava ele expulsando um demônio, o qual era mudo. E aconteceu que, saindo o demônio, o mudo falou; e maravilhou-se a multidão.'),
('acf','lc',11,15,'Mas alguns deles diziam: Ele expulsa os demônios por Belzebu, príncipe dos demônios.'),
('acf','lc',11,16,'E outros, tentando-o, pediam-lhe um sinal do céu.'),
('acf','lc',11,17,'Mas, conhecendo ele os seus pensamentos, disse-lhes: Todo o reino, dividido contra si mesmo, será assolado; e a casa, dividida contra si mesma, cairá.'),
('acf','lc',11,18,'E, se também Satanás está dividido contra si mesmo, como subsistirá o seu reino? Pois dizeis que eu expulso os demônios por Belzebu.'),
('acf','lc',11,19,'E, se eu expulso os demônios por Belzebu, por quem os expulsam vossos filhos? Eles, pois, serão os vossos juízes.'),
('acf','lc',11,20,'Mas, se eu expulso os demônios pelo dedo de Deus, certamente a vós é chegado o reino de Deus.'),
('acf','lc',11,21,'Quando o valente guarda, armado, a sua casa, em segurança está tudo quanto tem;'),
('acf','lc',11,22,'Mas, sobrevindo outro mais valente do que ele, e vencendo-o, tira-lhe toda a sua armadura em que confiava, e reparte os seus despojos.'),
('acf','lc',11,23,'Quem não é comigo é contra mim; e quem comigo não ajunta, espalha.'),
('acf','lc',11,24,'Quando o espírito imundo tem saído do homem, anda por lugares secos, buscando repouso; e, não o achando, diz: Tornarei para minha casa, de onde saí.'),
('acf','lc',11,25,'E, chegando, acha-a varrida e adornada.'),
('acf','lc',11,26,'Então vai, e leva consigo outros sete espíritos piores do que ele e, entrando, habitam ali; e o último estado desse homem é pior do que o primeiro.'),
('acf','lc',11,27,'E aconteceu que, dizendo ele estas coisas, uma mulher dentre a multidão, levantando a voz, lhe disse: Bem-aventurado o ventre que te trouxe e os peitos em que mamaste.'),
('acf','lc',11,28,'Mas ele disse: Antes bemaventurados os que ouvem a palavra de Deus e a guardam.'),
('acf','lc',11,29,'E, ajuntando-se a multidão, começou a dizer: Maligna é esta geração; ela pede um sinal; e não lhe será dado outro sinal, senão o sinal do profeta Jonas;'),
('acf','lc',11,30,'Porquanto, assim como Jonas foi sinal para os ninivitas, assim o Filho do homem o será também para esta geração.'),
('acf','lc',11,31,'A rainha do sul se levantará no juízo com os homens desta geração, e os condenará; pois até dos confins da terra veio ouvir a sabedoria de Salomão; e eis aqui está quem é maior do que Salomão.'),
('acf','lc',11,32,'Os homens de Nínive se levantarão no juízo com esta geração, e a condenarão; pois se converteram com a pregação de Jonas; e eis aqui está quem é maior do que Jonas.'),
('acf','lc',11,33,'E ninguém, acendendo uma candeia, a põe em oculto, nem debaixo do alqueire, mas no velador, para que os que entram vejam a luz.'),
('acf','lc',11,34,'A candeia do corpo é o olho. Sendo, pois, o teu olho simples, também todo o teu corpo será luminoso; mas, se for mau, também o teu corpo será tenebroso.'),
('acf','lc',11,35,'Vê, pois, que a luz que em ti há não sejam trevas.'),
('acf','lc',11,36,'Se, pois, todo o teu corpo é luminoso, não tendo em trevas parte alguma, todo será luminoso, como quando a candeia te ilumina com o seu resplendor.'),
('acf','lc',11,37,'E, estando ele ainda falando, rogou-lhe um fariseu que fosse jantar com ele; e, entrando, assentou-se à mesa.'),
('acf','lc',11,38,'Mas o fariseu admirou-se, vendo que não se lavara antes de jantar.'),
('acf','lc',11,39,'E o Senhor lhe disse: Agora vós, os fariseus, limpais o exterior do copo e do prato; mas o vosso interior está cheio de rapina e maldade.'),
('acf','lc',11,40,'Loucos! Quem fez o exterior não fez também o interior?'),
('acf','lc',11,41,'Antes dai esmola do que tiverdes, e eis que tudo vos será limpo.'),
('acf','lc',11,42,'Mas ai de vós, fariseus, que dizimais a hortelã, e a arruda, e toda a hortaliça, e desprezais o juízo e o amor de Deus. Importava fazer estas coisas, e não deixar as outras.'),
('acf','lc',11,43,'Ai de vós, fariseus, que amais os primeiros assentos nas sinagogas, e as saudações nas praças.'),
('acf','lc',11,44,'Ai de vós, escribas e fariseus, hipócritas! que sois como as sepulturas que não aparecem, e os homens que sobre elas andam não o sabem.'),
('acf','lc',11,45,'E, respondendo um dos doutores da lei, disse-lhe: Mestre, quando dizes isso, também nos afrontas a nós.'),
('acf','lc',11,46,'E ele lhe disse: Ai de vós também, doutores da lei, que carregais os homens com cargas difíceis de transportar, e vós mesmos nem ainda com um dos vossos dedos tocais essas cargas.'),
('acf','lc',11,47,'Ai de vós que edificais os sepulcros dos profetas, e vossos pais os mataram.'),
('acf','lc',11,48,'Bem testificais, pois, que consentis nas obras de vossos pais; porque eles os mataram, e vós edificais os seus sepulcros.'),
('acf','lc',11,49,'Por isso diz também a sabedoria de Deus: Profetas e apóstolos lhes mandarei; e eles matarão uns, e perseguirão outros;'),
('acf','lc',11,50,'Para que desta geração seja requerido o sangue de todos os profetas que, desde a fundação do mundo, foi derramado;'),
('acf','lc',11,51,'Desde o sangue de Abel, até ao sangue de Zacarias, que foi morto entre o altar e o templo; assim, vos digo, será requerido desta geração.'),
('acf','lc',11,52,'Ai de vós, doutores da lei, que tirastes a chave da ciência; vós mesmos não entrastes, e impedistes os que entravam.'),
('acf','lc',11,53,'E, dizendo-lhes ele isto, começaram os escribas e os fariseus a apertá-lo fortemente, e a fazê-lo falar acerca de muitas coisas,'),
('acf','lc',11,54,'Armando-lhe ciladas, e procurando apanhar da sua boca alguma coisa para o acusarem.'),
('acf','lc',12,1,'Ajuntando-se entretanto muitos milhares de pessoas, de sorte que se atropelavam uns aos outros, começou a dizer aos seus discípulos: Acautelai-vos primeiramente do fermento dos fariseus, que é a hipocrisia.'),
('acf','lc',12,2,'Mas nada há encoberto que não haja de ser descoberto; nem oculto, que não haja de ser sabido.'),
('acf','lc',12,3,'Porquanto tudo o que em trevas dissestes, à luz será ouvido; e o que falastes ao ouvido no gabinete, sobre os telhados será apregoado.'),
('acf','lc',12,4,'E digo-vos, amigos meus: Não temais os que matam o corpo e, depois, não têm mais que fazer.'),
('acf','lc',12,5,'Mas eu vos mostrarei a quem deveis temer; temei aquele que, depois de matar, tem poder para lançar no inferno; sim, vos digo, a esse temei.'),
('acf','lc',12,6,'Não se vendem cinco passarinhos por dois ceitis? E nenhum deles está esquecido diante de Deus.'),
('acf','lc',12,7,'E até os cabelos da vossa cabeça estão todos contados. Não temais pois; mais valeis vós do que muitos passarinhos.'),
('acf','lc',12,8,'E digo-vos que todo aquele que me confessar diante dos homens também o Filho do homem o confessará diante dos anjos de Deus.'),
('acf','lc',12,9,'Mas quem me negar diante dos homens será negado diante dos anjos de Deus.'),
('acf','lc',12,10,'E a todo aquele que disser uma palavra contra o Filho do homem ser-lhe-á perdoada, mas ao que blasfemar contra o Espírito Santo não lhe será perdoado.'),
('acf','lc',12,11,'E, quando vos conduzirem às sinagogas, aos magistrados e potestades, não estejais solícitos de como ou do que haveis de responder, nem do que haveis de dizer.'),
('acf','lc',12,12,'Porque na mesma hora vos ensinará o Espírito Santo o que vos convenha falar.'),
('acf','lc',12,13,'E disse-lhe um da multidão: Mestre, dize a meu irmão que reparta comigo a herança.'),
('acf','lc',12,14,'Mas ele lhe disse: Homem, quem me pôs a mim por juiz ou repartidor entre vós?'),
('acf','lc',12,15,'E disse-lhes: Acautelai-vos e guardai-vos da avareza; porque a vida de qualquer não consiste na abundância do que possui.'),
('acf','lc',12,16,'E propôs-lhe uma parábola, dizendo: A herdade de um homem rico tinha produzido com abundância;'),
('acf','lc',12,17,'E arrazoava ele entre si, dizendo: Que farei? Não tenho onde recolher os meus frutos.'),
('acf','lc',12,18,'E disse: Farei isto: Derrubarei os meus celeiros, e edificarei outros maiores, e ali recolherei todas as minhas novidades e os meus bens;'),
('acf','lc',12,19,'E direi a minha alma: Alma, tens em depósito muitos bens para muitos anos; descansa, come, bebe e folga.'),
('acf','lc',12,20,'Mas Deus lhe disse: Louco! esta noite te pedirão a tua alma; e o que tens preparado, para quem será?'),
('acf','lc',12,21,'Assim é aquele que para si ajunta tesouros, e não é rico para com Deus.'),
('acf','lc',12,22,'E disse aos seus discípulos: Portanto vos digo: Não estejais apreensivos pela vossa vida, sobre o que comereis, nem pelo corpo, sobre o que vestireis.'),
('acf','lc',12,23,'Mais é a vida do que o sustento, e o corpo mais do que as vestes.'),
('acf','lc',12,24,'Considerai os corvos, que nem semeiam, nem segam, nem têm despensa nem celeiro, e Deus os alimenta; quanto mais valeis vós do que as aves?'),
('acf','lc',12,25,'E qual de vós, sendo solícito, pode acrescentar um côvado à sua estatura?'),
('acf','lc',12,26,'Pois, se nem ainda podeis as coisas mínimas, por que estais ansiosos pelas outras?'),
('acf','lc',12,27,'Considerai os lírios, como eles crescem; não trabalham, nem fiam; e digo-vos que nem ainda Salomão, em toda a sua glória, se vestiu como um deles.'),
('acf','lc',12,28,'E, se Deus assim veste a erva que hoje está no campo e amanhã é lançada no forno, quanto mais a vós, homens de pouca fé?'),
('acf','lc',12,29,'Não pergunteis, pois, que haveis de comer, ou que haveis de beber, e não andeis inquietos.'),
('acf','lc',12,30,'Porque as nações do mundo buscam todas essas coisas; mas vosso Pai sabe que precisais delas.'),
('acf','lc',12,31,'Buscai antes o reino de Deus, e todas estas coisas vos serão acrescentadas.'),
('acf','lc',12,32,'Não temais, ó pequeno rebanho, porque a vosso Pai agradou dar-vos o reino.'),
('acf','lc',12,33,'Vendei o que tendes, e dai esmolas. Fazei para vós bolsas que não se envelheçam; tesouro nos céus que nunca acabe, aonde não chega ladrão e a traça não rói.'),
('acf','lc',12,34,'Porque, onde estiver o vosso tesouro, ali estará também o vosso coração.'),
('acf','lc',12,35,'Estejam cingidos os vossos lombos, e acesas as vossas candeias.'),
('acf','lc',12,36,'E sede vós semelhantes aos homens que esperam o seu senhor, quando houver de voltar das bodas, para que, quando vier, e bater, logo possam abrir-lhe.'),
('acf','lc',12,37,'Bem-aventurados aqueles servos, os quais, quando o Senhor vier, achar vigiando! Em verdade vos digo que se cingirá, e os fará assentar à mesa e, chegando-se, os servirá.'),
('acf','lc',12,38,'E, se vier na segunda vigília, e se vier na terceira vigília, e os achar assim, bem-aventurados são os tais servos.'),
('acf','lc',12,39,'Sabei, porém, isto: que, se o pai de família soubesse a que hora havia de vir o ladrão, vigiaria, e não deixaria minar a sua casa.'),
('acf','lc',12,40,'Portanto, estai vós também apercebidos; porque virá o Filho do homem à hora que não imaginais.'),
('acf','lc',12,41,'E disse-lhe Pedro: Senhor, dizes essa parábola a nós, ou também a todos?'),
('acf','lc',12,42,'E disse o Senhor: Qual é, pois, o mordomo fiel e prudente, a quem o senhor pôs sobre os seus servos, para lhes dar a tempo a ração?'),
('acf','lc',12,43,'Bem-aventurado aquele servo a quem o seu senhor, quando vier, achar fazendo assim.'),
('acf','lc',12,44,'Em verdade vos digo que sobre todos os seus bens o porá.'),
('acf','lc',12,45,'Mas, se aquele servo disser em seu coração: O meu senhor tarda em vir; e começar a espancar os criados e criadas, e a comer, e a beber, e a embriagar-se,'),
('acf','lc',12,46,'Virá o senhor daquele servo no dia em que o não espera, e numa hora que ele não sabe, e separá-lo-á, e lhe dará a sua parte com os infiéis.'),
('acf','lc',12,47,'E o servo que soube a vontade do seu senhor, e não se aprontou, nem fez conforme a sua vontade, será castigado com muitos açoites;'),
('acf','lc',12,48,'Mas o que a não soube, e fez coisas dignas de açoites, com poucos açoites será castigado. E, a qualquer que muito for dado, muito se lhe pedirá, e ao que muito se lhe confiou, muito mais se lhe pedirá.'),
('acf','lc',12,49,'Vim lançar fogo na terra; e que mais quero, se já está aceso?'),
('acf','lc',12,50,'Importa, porém, que seja batizado com um certo batismo; e como me angustio até que venha a cumprir-se!'),
('acf','lc',12,51,'Cuidais vós que vim trazer paz à terra? Não, vos digo, mas antes dissensão;'),
('acf','lc',12,52,'Porque daqui em diante estarão cinco divididos numa casa: três contra dois, e dois contra três.'),
('acf','lc',12,53,'O pai estará dividido contra o filho, e o filho contra o pai; a mãe contra a filha, e a filha contra a mãe; a sogra contra sua nora, e a nora contra sua sogra.'),
('acf','lc',12,54,'E dizia também à multidão: Quando vedes a nuvem que vem do ocidente, logo dizeis: Lá vem chuva, e assim sucede.'),
('acf','lc',12,55,'E, quando assopra o sul, dizeis: Haverá calma; e assim sucede.'),
('acf','lc',12,56,'Hipócritas, sabeis discernir a face da terra e do céu; como não sabeis então discernir este tempo?'),
('acf','lc',12,57,'E por que não julgais também por vós mesmos o que é justo?'),
('acf','lc',12,58,'Quando, pois, vais com o teu adversário ao magistrado, procura livrar-te dele no caminho; para que não suceda que te conduza ao juiz, e o juiz te entregue ao meirinho, e o meirinho te encerre na prisão.'),
('acf','lc',12,59,'Digo-te que não sairás dali enquanto não pagares o derradeiro ceitil.'),
('acf','lc',13,1,'E, Naquele mesmo tempo, estavam presentes ali alguns que lhe falavam dos galileus, cujo sangue Pilatos misturara com os seus sacrifícios.'),
('acf','lc',13,2,'E, respondendo Jesus, disse-lhes: Cuidais vós que esses galileus foram mais pecadores do que todos os galileus, por terem padecido tais coisas?'),
('acf','lc',13,3,'Não, vos digo; antes, se não vos arrependerdes, todos de igual modo perecereis.'),
('acf','lc',13,4,'E aqueles dezoito, sobre os quais caiu a torre de Siloé e os matou, cuidais que foram mais culpados do que todos quantos homens habitam em Jerusalém?'),
('acf','lc',13,5,'Não, vos digo; antes, se não vos arrependerdes, todos de igual modo perecereis.'),
('acf','lc',13,6,'E dizia esta parábola: Um certo homem tinha uma figueira plantada na sua vinha, e foi procurar nela fruto, não o achando;'),
('acf','lc',13,7,'E disse ao vinhateiro: Eis que há três anos venho procurar fruto nesta figueira, e não o acho. Corta-a; por que ocupa ainda a terra inutilmente?'),
('acf','lc',13,8,'E, respondendo ele, disse-lhe: Senhor, deixa-a este ano, até que eu a escave e a esterque;'),
('acf','lc',13,9,'E, se der fruto, ficará e, se não, depois a mandarás cortar.'),
('acf','lc',13,10,'E ensinava no sábado, numa das sinagogas.'),
('acf','lc',13,11,'E eis que estava ali uma mulher que tinha um espírito de enfermidade, havia já dezoito anos; e andava curvada, e não podia de modo algum endireitar-se.'),
('acf','lc',13,12,'E, vendo-a Jesus, chamou-a a si, e disse-lhe: Mulher, estás livre da tua enfermidade.'),
('acf','lc',13,13,'E pôs as mãos sobre ela, e logo se endireitou, e glorificava a Deus.'),
('acf','lc',13,14,'E, tomando a palavra o príncipe da sinagoga, indignado porque Jesus curava no sábado, disse à multidão: Seis dias há em que é mister trabalhar; nestes, pois, vinde para serdes curados, e não no dia de sábado.'),
('acf','lc',13,15,'Respondeu-lhe, porém, o Senhor, e disse: Hipócrita, no sábado não desprende da manjedoura cada um de vós o seu boi, ou jumento, e não o leva a beber?'),
('acf','lc',13,16,'E não convinha soltar desta prisão, no dia de sábado, esta filha de Abraão, a qual há dezoito anos Satanás tinha presa?'),
('acf','lc',13,17,'E, dizendo ele isto, todos os seus adversários ficaram envergonhados, e todo o povo se alegrava por todas as coisas gloriosas que eram feitas por ele.'),
('acf','lc',13,18,'E dizia: A que é semelhante o reino de Deus, e a que o compararei?'),
('acf','lc',13,19,'É semelhante ao grão de mostarda que um homem, tomando-o, lançou na sua horta; e cresceu, e fez-se grande árvore, e em seus ramos se aninharam as aves do céu.'),
('acf','lc',13,20,'E disse outra vez: A que compararei o reino de Deus?'),
('acf','lc',13,21,'É semelhante ao fermento que uma mulher, tomando-o, escondeu em três medidas de farinha, até que tudo levedou.'),
('acf','lc',13,22,'E percorria as cidades e as aldeias, ensinando, e caminhando para Jerusalém.'),
('acf','lc',13,23,'E disse-lhe um: Senhor, são poucos os que se salvam? E ele lhe respondeu:'),
('acf','lc',13,24,'Porfiai por entrar pela porta estreita; porque eu vos digo que muitos procurarão entrar, e não poderão.'),
('acf','lc',13,25,'Quando o pai de família se levantar e cerrar a porta, e começardes, de fora, a bater à porta, dizendo: Senhor, Senhor, abre-nos; e, respondendo ele, vos disser: Não sei de onde vós sois;'),
('acf','lc',13,26,'Então começareis a dizer: Temos comido e bebido na tua presença, e tu tens ensinado nas nossas ruas.'),
('acf','lc',13,27,'E ele vos responderá: Digo-vos que não vos conheço nem sei de onde vós sois; apartai-vos de mim, vós todos os que praticais a iniqüidade.'),
('acf','lc',13,28,'Ali haverá choro e ranger de dentes, quando virdes Abraão, e Isaque, e Jacó, e todos os profetas no reino de Deus, e vós lançados fora.'),
('acf','lc',13,29,'E virão do oriente, e do ocidente, e do norte, e do sul, e assentar-se-ão à mesa no reino de Deus.'),
('acf','lc',13,30,'E eis que derradeiros há que serão os primeiros; e primeiros há que serão os derradeiros.'),
('acf','lc',13,31,'Naquele mesmo dia chegaram uns fariseus, dizendo-lhe: Sai, e retira-te daqui, porque Herodes quer matar-te.'),
('acf','lc',13,32,'E respondeu-lhes: Ide, e dizei àquela raposa: Eis que eu expulso demônios, e efetuo curas, hoje e amanhã, e no terceiro dia sou consumado.'),
('acf','lc',13,33,'Importa, porém, caminhar hoje, amanhã, e no dia seguinte, para que não suceda que morra um profeta fora de Jerusalém.'),
('acf','lc',13,34,'Jerusalém, Jerusalém, que matas os profetas, e apedrejas os que te são enviados! Quantas vezes quis eu ajuntar os teus filhos, como a galinha os seus pintos debaixo das asas, e não quiseste?'),
('acf','lc',13,35,'Eis que a vossa casa se vos deixará deserta. E em verdade vos digo que não me vereis até que venha o tempo em que digais: Bendito aquele que vem em nome do Senhor.'),
('acf','lc',14,1,'Aconteceu num sábado que, entrando ele em casa de um dos principais dos fariseus para comer pão, eles o estavam observando.'),
('acf','lc',14,2,'E eis que estava ali diante dele um certo homem hidrópico.'),
('acf','lc',14,3,'E Jesus, tomando a palavra, falou aos doutores da lei, e aos fariseus, dizendo: É lícito curar no sábado?'),
('acf','lc',14,4,'Eles, porém, calaram-se. E, tomando-o, o curou e despediu.'),
('acf','lc',14,5,'E respondendo-lhes disse: Qual será de vós o que, caindo-lhe num poço, em dia de sábado, o jumento ou o boi, o não tire logo?'),
('acf','lc',14,6,'E nada lhe podiam replicar sobre isto.'),
('acf','lc',14,7,'E disse aos convidados uma parábola, reparando como escolhiam os primeiros assentos, dizendo-lhes:'),
('acf','lc',14,8,'Quando por alguém fores convidado às bodas, não te assentes no primeiro lugar; não aconteça que esteja convidado outro mais digno do que tu;'),
('acf','lc',14,9,'E, vindo o que te convidou a ti e a ele, te diga: Dá o lugar a este; e então, com vergonha, tenhas de tomar o derradeiro lugar.'),
('acf','lc',14,10,'Mas, quando fores convidado, vai, e assenta-te no derradeiro lugar, para que, quando vier o que te convidou, te diga: Amigo, sobe mais para cima. Então terás honra diante dos que estiverem contigo à mesa.'),
('acf','lc',14,11,'Porquanto qualquer que a si mesmo se exaltar será humilhado, e aquele que a si mesmo se humilhar será exaltado.'),
('acf','lc',14,12,'E dizia também ao que o tinha convidado: Quando deres um jantar, ou uma ceia, não chames os teus amigos, nem os teus irmãos, nem os teus parentes, nem vizinhos ricos, para que não suceda que também eles te tornem a convidar, e te seja isso recompensado.'),
('acf','lc',14,13,'Mas, quando fizeres convite, chama os pobres, aleijados, mancos e cegos,'),
('acf','lc',14,14,'E serás bem-aventurado; porque eles não têm com que to recompensar; mas recompensado te será na ressurreição dos justos.'),
('acf','lc',14,15,'E, ouvindo isto, um dos que estavam com ele à mesa, disse-lhe: Bem-aventurado o que comer pão no reino de Deus.'),
('acf','lc',14,16,'Porém, ele lhe disse: Um certo homem fez uma grande ceia, e convidou a muitos.'),
('acf','lc',14,17,'E à hora da ceia mandou o seu servo dizer aos convidados: Vinde, que já tudo está preparado.'),
('acf','lc',14,18,'E todos à uma começaram a escusar-se. Disse-lhe o primeiro: Comprei um campo, e importa ir vê-lo; rogo-te que me hajas por escusado.'),
('acf','lc',14,19,'E outro disse: Comprei cinco juntas de bois, e vou experimentá-los; rogo-te que me hajas por escusado.'),
('acf','lc',14,20,'E outro disse: Casei, e portanto não posso ir.'),
('acf','lc',14,21,'E, voltando aquele servo, anunciou estas coisas ao seu senhor. Então o pai de família, indignado, disse ao seu servo: Sai depressa pelas ruas e bairros da cidade, e traze aqui os pobres, e aleijados, e mancos e cegos.'),
('acf','lc',14,22,'E disse o servo: Senhor, feito está como mandaste; e ainda há lugar.'),
('acf','lc',14,23,'E disse o senhor ao servo: Sai pelos caminhos e valados, e força-os a entrar, para que a minha casa se encha.'),
('acf','lc',14,24,'Porque eu vos digo que nenhum daqueles homens que foram convidados provará a minha ceia.'),
('acf','lc',14,25,'Ora, ia com ele uma grande multidão; e, voltando-se, disse-lhe:'),
('acf','lc',14,26,'Se alguém vier a mim, e não aborrecer a seu pai, e mãe, e mulher, e filhos, e irmãos, e irmãs, e ainda também a sua própria vida, não pode ser meu discípulo.'),
('acf','lc',14,27,'E qualquer que não levar a sua cruz, e não vier após mim, não pode ser meu discípulo.'),
('acf','lc',14,28,'Pois qual de vós, querendo edificar uma torre, não se assenta primeiro a fazer as contas dos gastos, para ver se tem com que a acabar?'),
('acf','lc',14,29,'Para que não aconteça que, depois de haver posto os alicerces, e não a podendo acabar, todos os que a virem comecem a escarnecer dele,'),
('acf','lc',14,30,'Dizendo: Este homem começou a edificar e não pôde acabar.'),
('acf','lc',14,31,'Ou qual é o rei que, indo à guerra a pelejar contra outro rei, não se assenta primeiro a tomar conselho sobre se com dez mil pode sair ao encontro do que vem contra ele com vinte mil?'),
('acf','lc',14,32,'De outra maneira, estando o outro ainda longe, manda embaixadores, e pede condições de paz.'),
('acf','lc',14,33,'Assim, pois, qualquer de vós, que não renuncia a tudo quanto tem, não pode ser meu discípulo.'),
('acf','lc',14,34,'Bom é o sal; mas, se o sal degenerar, com que se há de salgar?'),
('acf','lc',14,35,'Nem presta para a terra, nem para o monturo; lançam-no fora. Quem tem ouvidos para ouvir, ouça.'),
('acf','lc',15,1,'E Chegavam-se a ele todos os publicanos e pecadores para o ouvir.'),
('acf','lc',15,2,'E os fariseus e os escribas murmuravam, dizendo: Este recebe pecadores, e come com eles.'),
('acf','lc',15,3,'E ele lhes propôs esta parábola, dizendo:'),
('acf','lc',15,4,'Que homem dentre vós, tendo cem ovelhas, e perdendo uma delas, não deixa no deserto as noventa e nove, e vai após a perdida até que venha a achá-la?'),
('acf','lc',15,5,'E achando-a, a põe sobre os seus ombros, jubiloso;'),
('acf','lc',15,6,'E, chegando a casa, convoca os amigos e vizinhos, dizendo-lhes: Alegrai-vos comigo, porque já achei a minha ovelha perdida.'),
('acf','lc',15,7,'Digo-vos que assim haverá alegria no céu por um pecador que se arrepende, mais do que por noventa e nove justos que não necessitam de arrependimento.'),
('acf','lc',15,8,'Ou qual a mulher que, tendo dez dracmas, se perder uma dracma, não acende a candeia, e varre a casa, e busca com diligência até a achar?'),
('acf','lc',15,9,'E achando-a, convoca as amigas e vizinhas, dizendo: Alegrai-vos comigo, porque já achei a dracma perdida.'),
('acf','lc',15,10,'Assim vos digo que há alegria diante dos anjos de Deus por um pecador que se arrepende.'),
('acf','lc',15,11,'E disse: Um certo homem tinha dois filhos;'),
('acf','lc',15,12,'E o mais moço deles disse ao pai: Pai, dá-me a parte dos bens que me pertence. E ele repartiu por eles a fazenda.'),
('acf','lc',15,13,'E, poucos dias depois, o filho mais novo, ajuntando tudo, partiu para uma terra longínqua, e ali desperdiçou os seus bens, vivendo dissolutamente.'),
('acf','lc',15,14,'E, havendo ele gastado tudo, houve naquela terra uma grande fome, e começou a padecer necessidades.'),
('acf','lc',15,15,'E foi, e chegou-se a um dos cidadãos daquela terra, o qual o mandou para os seus campos, a apascentar porcos.'),
('acf','lc',15,16,'E desejava encher o seu estômago com as bolotas que os porcos comiam, e ninguém lhe dava nada.'),
('acf','lc',15,17,'E, tornando em si, disse: Quantos jornaleiros de meu pai têm abundância de pão, e eu aqui pereço de fome!'),
('acf','lc',15,18,'Levantar-me-ei, e irei ter com meu pai, e dir-lhe-ei: Pai, pequei contra o céu e perante ti;'),
('acf','lc',15,19,'Já não sou digno de ser chamado teu filho; faze-me como um dos teus jornaleiros.'),
('acf','lc',15,20,'E, levantando-se, foi para seu pai; e, quando ainda estava longe, viu-o seu pai, e se moveu de íntima compaixão e, correndo, lançou-se-lhe ao pescoço e o beijou.'),
('acf','lc',15,21,'E o filho lhe disse: Pai, pequei contra o céu e perante ti, e já não sou digno de ser chamado teu filho.'),
('acf','lc',15,22,'Mas o pai disse aos seus servos: Trazei depressa a melhor roupa; e vesti-lho, e ponde-lhe um anel na mão, e alparcas nos pés;'),
('acf','lc',15,23,'E trazei o bezerro cevado, e matai-o; e comamos, e alegremo-nos;'),
('acf','lc',15,24,'Porque este meu filho estava morto, e reviveu, tinha-se perdido, e foi achado. E começaram a alegrar-se.'),
('acf','lc',15,25,'E o seu filho mais velho estava no campo; e quando veio, e chegou perto de casa, ouviu a música e as danças.'),
('acf','lc',15,26,'E, chamando um dos servos, perguntou-lhe que era aquilo.'),
('acf','lc',15,27,'E ele lhe disse: Veio teu irmão; e teu pai matou o bezerro cevado, porque o recebeu são e salvo.'),
('acf','lc',15,28,'Mas ele se indignou, e não queria entrar.'),
('acf','lc',15,29,'E saindo o pai, instava com ele. Mas, respondendo ele, disse ao pai: Eis que te sirvo há tantos anos, sem nunca transgredir o teu mandamento, e nunca me deste um cabrito para alegrar-me com os meus amigos;'),
('acf','lc',15,30,'Vindo, porém, este teu filho, que desperdiçou os teus bens com as meretrizes, mataste-lhe o bezerro cevado.'),
('acf','lc',15,31,'E ele lhe disse: Filho, tu sempre estás comigo, e todas as minhas coisas são tuas;'),
('acf','lc',15,32,'Mas era justo alegrarmo-nos e folgarmos, porque este teu irmão estava morto, e reviveu; e tinha-se perdido, e achou-se.'),
('acf','lc',16,1,'E dizia também aos seus discípulos: Havia um certo homem rico, o qual tinha um mordomo; e este foi acusado perante ele de dissipar os seus bens.'),
('acf','lc',16,2,'E ele, chamando-o, disse-lhe: Que é isto que ouço de ti? Dá contas da tua mordomia, porque já não poderás ser mais meu mordomo.'),
('acf','lc',16,3,'E o mordomo disse consigo: Que farei, pois que o meu senhor me tira a mordomia? Cavar, não posso; de mendigar, tenho vergonha.'),
('acf','lc',16,4,'Eu sei o que hei de fazer, para que, quando for desapossado da mordomia, me recebam em suas casas.'),
('acf','lc',16,5,'E, chamando a si cada um dos devedores do seu senhor, disse ao primeiro: Quanto deves ao meu senhor?'),
('acf','lc',16,6,'E ele respondeu: Cem medidas de azeite. E disse-lhe: Toma a tua obrigação, e assentando-te já, escreve cinqüenta.'),
('acf','lc',16,7,'Disse depois a outro: E tu, quanto deves? E ele respondeu: Cem alqueires de trigo. E disse-lhe: Toma a tua obrigação, e escreve oitenta.'),
('acf','lc',16,8,'E louvou aquele senhor o injusto mordomo por haver procedido prudentemente, porque os filhos deste mundo são mais prudentes na sua geração do que os filhos da luz.'),
('acf','lc',16,9,'E eu vos digo: Granjeai amigos com as riquezas da injustiça; para que, quando estas vos faltarem, vos recebam eles nos tabernáculos eternos.'),
('acf','lc',16,10,'Quem é fiel no mínimo, também é fiel no muito; quem é injusto no mínimo, também é injusto no muito.'),
('acf','lc',16,11,'Pois, se nas riquezas injustas não fostes fiéis, quem vos confiará as verdadeiras?'),
('acf','lc',16,12,'E, se no alheio não fostes fiéis, quem vos dará o que é vosso?'),
('acf','lc',16,13,'Nenhum servo pode servir dois senhores; porque, ou há de odiar um e amar o outro, ou se há de chegar a um e desprezar o outro. Não podeis servir a Deus e a Mamom.'),
('acf','lc',16,14,'E os fariseus, que eram avarentos, ouviam todas estas coisas, e zombavam dele.'),
('acf','lc',16,15,'E disse-lhes: Vós sois os que vos justificais a vós mesmos diante dos homens, mas Deus conhece os vossos corações, porque o que entre os homens é elevado, perante Deus é abominação.'),
('acf','lc',16,16,'A lei e os profetas duraram até João; desde então é anunciado o reino de Deus, e todo o homem emprega força para entrar nele.'),
('acf','lc',16,17,'E é mais fácil passar o céu e a terra do que cair um til da lei.'),
('acf','lc',16,18,'Qualquer que deixa sua mulher, e casa com outra, adultera; e aquele que casa com a repudiada pelo marido, adultera também.'),
('acf','lc',16,19,'Ora, havia um homem rico, e vestia-se de púrpura e de linho finíssimo, e vivia todos os dias regalada e esplendidamente.'),
('acf','lc',16,20,'Havia também um certo mendigo, chamado Lázaro, que jazia cheio de chagas à porta daquele;'),
('acf','lc',16,21,'E desejava alimentar-se com as migalhas que caíam da mesa do rico; e os próprios cães vinham lamber-lhe as chagas.'),
('acf','lc',16,22,'E aconteceu que o mendigo morreu, e foi levado pelos anjos para o seio de Abraão; e morreu também o rico, e foi sepultado.'),
('acf','lc',16,23,'E no inferno, ergueu os olhos, estando em tormentos, e viu ao longe Abraão, e Lázaro no seu seio.'),
('acf','lc',16,24,'E, clamando, disse: Pai Abraão, tem misericórdia de mim, e manda a Lázaro, que molhe na água a ponta do seu dedo e me refresque a língua, porque estou atormentado nesta chama.'),
('acf','lc',16,25,'Disse, porém, Abraão: Filho, lembra-te de que recebeste os teus bens em tua vida, e Lázaro somente males; e agora este é consolado e tu atormentado.'),
('acf','lc',16,26,'E, além disso, está posto um grande abismo entre nós e vós, de sorte que os que quisessem passar daqui para vós não poderiam, nem tampouco os de lá passar para cá.'),
('acf','lc',16,27,'E disse ele: Rogo-te, pois, ó pai, que o mandes à casa de meu pai,'),
('acf','lc',16,28,'Pois tenho cinco irmãos; para que lhes dê testemunho, a fim de que não venham também para este lugar de tormento.'),
('acf','lc',16,29,'Disse-lhe Abraão: Têm Moisés e os profetas; ouçam-nos.'),
('acf','lc',16,30,'E disse ele: Não, pai Abraão; mas, se algum dentre os mortos fosse ter com eles, arrepender-se-iam.'),
('acf','lc',16,31,'Porém, Abraão lhe disse: Se não ouvem a Moisés e aos profetas, tampouco acreditarão, ainda que algum dos mortos ressuscite.'),
('acf','lc',17,1,'E disse aos discípulos: É impossível que não venham escândalos, mas ai daquele por quem vierem!'),
('acf','lc',17,2,'Melhor lhe fora que lhe pusessem ao pescoço uma mó de atafona, e fosse lançado ao mar, do que fazer tropeçar um destes pequenos.'),
('acf','lc',17,3,'Olhai por vós mesmos. E, se teu irmão pecar contra ti, repreende-o e, se ele se arrepender, perdoa-lhe.'),
('acf','lc',17,4,'E, se pecar contra ti sete vezes no dia, e sete vezes no dia vier ter contigo, dizendo: Arrependo-me; perdoa-lhe.'),
('acf','lc',17,5,'Disseram então os apóstolos ao Senhor: Acrescenta-nos a fé.'),
('acf','lc',17,6,'E disse o Senhor: Se tivésseis fé como um grão de mostarda, diríeis a esta amoreira: Desarraiga-te daqui, e planta-te no mar; e ela vos obedeceria.'),
('acf','lc',17,7,'E qual de vós terá um servo a lavrar ou a apascentar gado, a quem, voltando ele do campo, diga: Chega-te, e assenta-te à mesa?'),
('acf','lc',17,8,'E não lhe diga antes: Prepara-me a ceia, e cinge-te, e serve-me até que tenha comido e bebido, e depois comerás e beberás tu?'),
('acf','lc',17,9,'Porventura dá graças ao tal servo, porque fez o que lhe foi mandado? Creio que não.'),
('acf','lc',17,10,'Assim também vós, quando fizerdes tudo o que vos for mandado, dizei: Somos servos inúteis, porque fizemos somente o que devíamos fazer.'),
('acf','lc',17,11,'E aconteceu que, indo ele a Jerusalém, passou pelo meio de Samaria e da Galiléia;'),
('acf','lc',17,12,'E, entrando numa certa aldeia, saíram-lhe ao encontro dez homens leprosos, os quais pararam de longe;'),
('acf','lc',17,13,'E levantaram a voz, dizendo: Jesus, Mestre, tem misericórdia de nós.'),
('acf','lc',17,14,'E ele, vendo-os, disse-lhes: Ide, e mostrai-vos aos sacerdotes. E aconteceu que, indo eles, ficaram limpos.'),
('acf','lc',17,15,'E um deles, vendo que estava são, voltou glorificando a Deus em alta voz;'),
('acf','lc',17,16,'E caiu aos seus pés, com o rosto em terra, dando-lhe graças; e este era samaritano.'),
('acf','lc',17,17,'E, respondendo Jesus, disse: Não foram dez os limpos? E onde estão os nove?'),
('acf','lc',17,18,'Não houve quem voltasse para dar glória a Deus senão este estrangeiro?'),
('acf','lc',17,19,'E disse-lhe: Levanta-te, e vai; a tua fé te salvou.'),
('acf','lc',17,20,'E, interrogado pelos fariseus sobre quando havia de vir o reino de Deus, respondeu-lhes, e disse: O reino de Deus não vem com aparência exterior.'),
('acf','lc',17,21,'Nem dirão: Ei-lo aqui, ou: Ei-lo ali; porque eis que o reino de Deus está entre vós.'),
('acf','lc',17,22,'E disse aos discípulos: Dias virão em que desejareis ver um dos dias do Filho do homem, e não o vereis.'),
('acf','lc',17,23,'E dir-vos-ão: Ei-lo aqui, ou: Ei-lo ali. Não vades, nem os sigais;'),
('acf','lc',17,24,'Porque, como o relâmpago ilumina desde uma extremidade inferior do céu até à outra extremidade, assim será também o Filho do homem no seu dia.'),
('acf','lc',17,25,'Mas primeiro convém que ele padeça muito, e seja reprovado por esta geração.'),
('acf','lc',17,26,'E, como aconteceu nos dias de Noé, assim será também nos dias do Filho do homem.'),
('acf','lc',17,27,'Comiam, bebiam, casavam, e davam-se em casamento, até ao dia em que Noé entrou na arca, e veio o dilúvio, e os consumiu a todos.'),
('acf','lc',17,28,'Como também da mesma maneira aconteceu nos dias de Ló: Comiam, bebiam, compravam, vendiam, plantavam e edificavam;'),
('acf','lc',17,29,'Mas no dia em que Ló saiu de Sodoma choveu do céu fogo e enxofre, e os consumiu a todos.'),
('acf','lc',17,30,'Assim será no dia em que o Filho do homem se há de manifestar.'),
('acf','lc',17,31,'Naquele dia, quem estiver no telhado, tendo as suas alfaias em casa, não desça a tomá-las; e, da mesma sorte, o que estiver no campo não volte para trás.'),
('acf','lc',17,32,'Lembrai-vos da mulher de Ló.'),
('acf','lc',17,33,'Qualquer que procurar salvar a sua vida, perdê-la-á, e qualquer que a perder, salvá-la-á.'),
('acf','lc',17,34,'Digo-vos que naquela noite estarão dois numa cama; um será tomado, e outro será deixado.'),
('acf','lc',17,35,'Duas estarão juntas, moendo; uma será tomada, e outra será deixada.'),
('acf','lc',17,36,'Dois estarão no campo; um será tomado, e o outro será deixado.'),
('acf','lc',17,37,'E, respondendo, disseram-lhe: Onde, Senhor? E ele lhes disse: Onde estiver o corpo, aí se ajuntarão as águias.'),
('acf','lc',18,1,'E contou-lhes também uma parábola sobre o dever de orar sempre, e nunca desfalecer,'),
('acf','lc',18,2,'Dizendo: Havia numa cidade um certo juiz, que nem a Deus temia, nem respeitava o homem.'),
('acf','lc',18,3,'Havia também, naquela mesma cidade, uma certa viúva, que ia ter com ele, dizendo: Faze-me justiça contra o meu adversário.'),
('acf','lc',18,4,'E por algum tempo não quis atendê-la; mas depois disse consigo: Ainda que não temo a Deus, nem respeito os homens,'),
('acf','lc',18,5,'Todavia, como esta viúva me molesta, hei de fazer-lhe justiça, para que enfim não volte, e me importune muito.'),
('acf','lc',18,6,'E disse o Senhor: Ouvi o que diz o injusto juiz.'),
('acf','lc',18,7,'E Deus não fará justiça aos seus escolhidos, que clamam a ele de dia e de noite, ainda que tardio para com eles?'),
('acf','lc',18,8,'Digo-vos que depressa lhes fará justiça. Quando porém vier o Filho do homem, porventura achará fé na terra?'),
('acf','lc',18,9,'E disse também esta parábola a uns que confiavam em si mesmos, crendo que eram justos, e desprezavam os outros:'),
('acf','lc',18,10,'Dois homens subiram ao templo, para orar; um, fariseu, e o outro, publicano.'),
('acf','lc',18,11,'O fariseu, estando em pé, orava consigo desta maneira: Ó Deus, graças te dou porque não sou como os demais homens, roubadores, injustos e adúlteros; nem ainda como este publicano.'),
('acf','lc',18,12,'Jejuo duas vezes na semana, e dou os dízimos de tudo quanto possuo.'),
('acf','lc',18,13,'O publicano, porém, estando em pé, de longe, nem ainda queria levantar os olhos ao céu, mas batia no peito, dizendo: Ó Deus, tem misericórdia de mim, pecador!'),
('acf','lc',18,14,'Digo-vos que este desceu justificado para sua casa, e não aquele; porque qualquer que a si mesmo se exalta será humilhado, e qualquer que a si mesmo se humilha será exaltado.'),
('acf','lc',18,15,'E traziam-lhe também meninos, para que ele lhes tocasse; e os discípulos, vendo isto, repreendiam-nos.'),
('acf','lc',18,16,'Mas Jesus, chamando-os para si, disse: Deixai vir a mim os meninos, e não os impeçais, porque dos tais é o reino de Deus.'),
('acf','lc',18,17,'Em verdade vos digo que, qualquer que não receber o reino de Deus como menino, não entrará nele.'),
('acf','lc',18,18,'E perguntou-lhe um certo príncipe, dizendo: Bom Mestre, que hei de fazer para herdar a vida eterna?'),
('acf','lc',18,19,'Jesus lhe disse: Por que me chamas bom? Ninguém há bom, senão um, que é Deus.'),
('acf','lc',18,20,'Sabes os mandamentos: Não adulterarás, não matarás, não furtarás, não dirás falso testemunho, honra a teu pai e a tua mãe.'),
('acf','lc',18,21,'E disse ele: Todas essas coisas tenho observado desde a minha mocidade.'),
('acf','lc',18,22,'E quando Jesus ouviu isto, disse-lhe: Ainda te falta uma coisa; vende tudo quanto tens, reparte-o pelos pobres, e terás um tesouro no céu; vem, e segue-me.'),
('acf','lc',18,23,'Mas, ouvindo ele isto, ficou muito triste, porque era muito rico.'),
('acf','lc',18,24,'E, vendo Jesus que ele ficara muito triste, disse: Quão dificilmente entrarão no reino de Deus os que têm riquezas!'),
('acf','lc',18,25,'Porque é mais fácil entrar um camelo pelo fundo de uma agulha do que entrar um rico no reino de Deus.'),
('acf','lc',18,26,'E os que ouviram isto disseram: Logo quem pode salvar-se?'),
('acf','lc',18,27,'Mas ele respondeu: As coisas que são impossíveis aos homens são possíveis a Deus.'),
('acf','lc',18,28,'E disse Pedro: Eis que nós deixamos tudo e te seguimos.'),
('acf','lc',18,29,'E ele lhes disse: Na verdade vos digo que ninguém há, que tenha deixado casa, ou pais, ou irmãos, ou mulher, ou filhos, pelo reino de Deus,'),
('acf','lc',18,30,'Que não haja de receber muito mais neste mundo, e na idade vindoura a vida eterna.'),
('acf','lc',18,31,'E, tomando consigo os doze, disse-lhes: Eis que subimos a Jerusalém, e se cumprirá no Filho do homem tudo o que pelos profetas foi escrito;'),
('acf','lc',18,32,'Pois há de ser entregue aos gentios, e escarnecido, injuriado e cuspido;'),
('acf','lc',18,33,'E, havendo-o açoitado, o matarão; e ao terceiro dia ressuscitará.'),
('acf','lc',18,34,'E eles nada disto entendiam, e esta palavra lhes era encoberta, não percebendo o que se lhes dizia.'),
('acf','lc',18,35,'E aconteceu que chegando ele perto de Jericó, estava um cego assentado junto do caminho, mendigando.'),
('acf','lc',18,36,'E, ouvindo passar a multidão, perguntou que era aquilo.'),
('acf','lc',18,37,'E disseram-lhe que Jesus Nazareno passava.'),
('acf','lc',18,38,'Então clamou, dizendo: Jesus, Filho de Davi, tem misericórdia de mim.'),
('acf','lc',18,39,'E os que iam passando repreendiam-no para que se calasse; mas ele clamava ainda mais: Filho de Davi, tem misericórdia de mim!'),
('acf','lc',18,40,'Então Jesus, parando, mandou que lho trouxessem; e, chegando ele, perguntou-lhe,'),
('acf','lc',18,41,'Dizendo: Que queres que te faça? E ele disse: Senhor, que eu veja.'),
('acf','lc',18,42,'E Jesus lhe disse: Vê; a tua fé te salvou.'),
('acf','lc',18,43,'E logo viu, e seguia-o, glorificando a Deus. E todo o povo, vendo isto, dava louvores a Deus.'),
('acf','lc',19,1,'E, tendo Jesus entrado em Jericó, ia passando.'),
('acf','lc',19,2,'E eis que havia ali um homem chamado Zaqueu; e era este um chefe dos publicanos, e era rico.'),
('acf','lc',19,3,'E procurava ver quem era Jesus, e não podia, por causa da multidão, pois era de pequena estatura.'),
('acf','lc',19,4,'E, correndo adiante, subiu a uma figueira brava para o ver; porque havia de passar por ali.'),
('acf','lc',19,5,'E quando Jesus chegou àquele lugar, olhando para cima, viu-o e disse-lhe: Zaqueu, desce depressa, porque hoje me convém pousar em tua casa.'),
('acf','lc',19,6,'E, apressando-se, desceu, e recebeu-o alegremente.'),
('acf','lc',19,7,'E, vendo todos isto, murmuravam, dizendo que entrara para ser hóspede de um homem pecador.'),
('acf','lc',19,8,'E, levantando-se Zaqueu, disse ao Senhor: Senhor, eis que eu dou aos pobres metade dos meus bens; e, se nalguma coisa tenho defraudado alguém, o restituo quadruplicado.'),
('acf','lc',19,9,'E disse-lhe Jesus: Hoje veio a salvação a esta casa, pois também este é filho de Abraão.'),
('acf','lc',19,10,'Porque o Filho do homem veio buscar e salvar o que se havia perdido.'),
('acf','lc',19,11,'E, ouvindo eles estas coisas, ele prosseguiu, e contou uma parábola; porquanto estava perto de Jerusalém, e cuidavam que logo se havia de manifestar o reino de Deus.'),
('acf','lc',19,12,'Disse pois: Certo homem nobre partiu para uma terra remota, a fim de tomar para si um reino e voltar depois.'),
('acf','lc',19,13,'E, chamando dez servos seus, deu-lhes dez minas, e disse-lhes: Negociai até que eu venha.'),
('acf','lc',19,14,'Mas os seus concidadãos odiavam-no, e mandaram após ele embaixadores, dizendo: Não queremos que este reine sobre nós.'),
('acf','lc',19,15,'E aconteceu que, voltando ele, depois de ter tomado o reino, disse que lhe chamassem aqueles servos, a quem tinha dado o dinheiro, para saber o que cada um tinha ganhado, negociando.'),
('acf','lc',19,16,'E veio o primeiro, dizendo: Senhor, a tua mina rendeu dez minas.'),
('acf','lc',19,17,'E ele lhe disse: Bem está, servo bom, porque no mínimo foste fiel, sobre dez cidades terás autoridade.'),
('acf','lc',19,18,'E veio o segundo, dizendo: Senhor, a tua mina rendeu cinco minas.'),
('acf','lc',19,19,'E a este disse também: Sê tu também sobre cinco cidades.'),
('acf','lc',19,20,'E veio outro, dizendo: Senhor, aqui está a tua mina, que guardei num lenço;'),
('acf','lc',19,21,'Porque tive medo de ti, que és homem rigoroso, que tomas o que não puseste, e segas o que não semeaste.'),
('acf','lc',19,22,'Porém, ele lhe disse: Mau servo, pela tua boca te julgarei. Sabias que eu sou homem rigoroso, que tomo o que não pus, e sego o que não semeei;'),
('acf','lc',19,23,'Por que não puseste, pois, o meu dinheiro no banco, para que eu, vindo, o exigisse com os juros?'),
('acf','lc',19,24,'E disse aos que estavam com ele: Tirai-lhe a mina, e dai-a ao que tem dez minas.'),
('acf','lc',19,25,'(E disseram-lhe eles: Senhor, ele tem dez minas. )'),
('acf','lc',19,26,'Pois eu vos digo que a qualquer que tiver ser-lhe-á dado, mas ao que não tiver, até o que tem lhe será tirado.'),
('acf','lc',19,27,'E quanto àqueles meus inimigos que não quiseram que eu reinasse sobre eles, trazei-os aqui, e matai-os diante de mim.'),
('acf','lc',19,28,'E, dito isto, ia caminhando adiante, subindo para Jerusalém.'),
('acf','lc',19,29,'E aconteceu que, chegando perto de Betfagé, e de Betânia, ao monte chamado das Oliveiras, mandou dois dos seus discípulos,'),
('acf','lc',19,30,'Dizendo: Ide à aldeia que está defronte, e aí, ao entrar, achareis preso um jumentinho em que nenhum homem ainda montou; soltai-o e trazei-o.'),
('acf','lc',19,31,'E, se alguém vos perguntar: Por que o soltais? assim lhe direis: Porque o Senhor o há de mister.'),
('acf','lc',19,32,'E, indo os que haviam sido mandados, acharam como lhes dissera.'),
('acf','lc',19,33,'E, quando soltaram o jumentinho, seus donos lhes disseram: Por que soltais o jumentinho?'),
('acf','lc',19,34,'E eles responderam: O Senhor o há de mister.'),
('acf','lc',19,35,'E trouxeram-no a Jesus; e, lançando sobre o jumentinho as suas vestes, puseram Jesus em cima.'),
('acf','lc',19,36,'E, indo ele, estendiam no caminho as suas vestes.'),
('acf','lc',19,37,'E, quando já chegava perto da descida do Monte das Oliveiras, toda a multidão dos discípulos, regozijando-se, começou a dar louvores a Deus em alta voz, por todas as maravilhas que tinham visto,'),
('acf','lc',19,38,'Dizendo: Bendito o Rei que vem em nome do Senhor; paz no céu, e glória nas alturas.'),
('acf','lc',19,39,'E disseram-lhe de entre a multidão alguns dos fariseus: Mestre, repreende os teus discípulos.'),
('acf','lc',19,40,'E, respondendo ele, disse-lhes: Digo-vos que, se estes se calarem, as próprias pedras clamarão.'),
('acf','lc',19,41,'E, quando ia chegando, vendo a cidade, chorou sobre ela,'),
('acf','lc',19,42,'Dizendo: Ah! se tu conhecesses também, ao menos neste teu dia, o que à tua paz pertence! Mas agora isto está encoberto aos teus olhos.'),
('acf','lc',19,43,'Porque dias virão sobre ti, em que os teus inimigos te cercarão de trincheiras, e te sitiarão, e te estreitarão de todos os lados;'),
('acf','lc',19,44,'E te derrubarão, a ti e aos teus filhos que dentro de ti estiverem, e não deixarão em ti pedra sobre pedra, pois que não conheceste o tempo da tua visitação.'),
('acf','lc',19,45,'E, entrando no templo, começou a expulsar todos os que nele vendiam e compravam,'),
('acf','lc',19,46,'Dizendo-lhes: Está escrito: A minha casa é casa de oração; mas vós fizestes dela covil de salteadores.'),
('acf','lc',19,47,'E todos os dias ensinava no templo; mas os principais dos sacerdotes, e os escribas, e os principais do povo procuravam matá-lo.'),
('acf','lc',19,48,'E não achavam meio de o fazer, porque todo o povo pendia para ele, escutando-o.'),
('acf','lc',20,1,'E aconteceu num daqueles dias que, estando ele ensinando o povo no templo, e anunciando o evangelho, sobrevieram os principais dos sacerdotes e os escribas com os anciãos,'),
('acf','lc',20,2,'E falaram-lhe, dizendo: Dize-nos, com que autoridade fazes estas coisas? Ou, quem é que te deu esta autoridade?'),
('acf','lc',20,3,'E, respondendo ele, disse-lhes: Também eu vos farei uma pergunta: Dizei-me pois:'),
('acf','lc',20,4,'O batismo de João era do céu ou dos homens?'),
('acf','lc',20,5,'E eles arrazoavam entre si, dizendo: Se dissermos: Do céu, ele nos dirá: Então por que o não crestes?'),
('acf','lc',20,6,'E se dissermos: Dos homens; todo o povo nos apedrejará, pois têm por certo que João era profeta.'),
('acf','lc',20,7,'E responderam que não sabiam de onde era.'),
('acf','lc',20,8,'E Jesus lhes disse: Tampouco vos direi com que autoridade faço isto.'),
('acf','lc',20,9,'E começou a dizer ao povo esta parábola: Certo homem plantou uma vinha, e arrendou-a a uns lavradores, e partiu para fora da terra por muito tempo;'),
('acf','lc',20,10,'E no tempo próprio mandou um servo aos lavradores, para que lhe dessem dos frutos da vinha; mas os lavradores, espancando-o, mandaram-no vazio.'),
('acf','lc',20,11,'E tornou ainda a mandar outro servo; mas eles, espancando também a este, e afrontando-o, mandaram-no vazio.'),
('acf','lc',20,12,'E tornou ainda a mandar um terceiro; mas eles, ferindo também a este, o expulsaram.'),
('acf','lc',20,13,'E disse o senhor da vinha: Que farei? Mandarei o meu filho amado; talvez que, vendo, o respeitem.'),
('acf','lc',20,14,'Mas, vendo-o os lavradores, arrazoaram entre si, dizendo: Este é o herdeiro; vinde, matemo-lo, para que a herança seja nossa.'),
('acf','lc',20,15,'E, lançando-o fora da vinha, o mataram. Que lhes fará, pois, o senhor da vinha?'),
('acf','lc',20,16,'Irá, e destruirá estes lavradores, e dará a outros a vinha. E, ouvindo eles isto, disseram: Não seja assim!'),
('acf','lc',20,17,'Mas ele, olhando para eles, disse: Que é isto, pois, que está escrito? A pedra, que os edificadores reprovaram, Essa foi feita cabeça da esquina.'),
('acf','lc',20,18,'Qualquer que cair sobre aquela pedra ficará em pedaços, e aquele sobre quem ela cair será feito em pó.'),
('acf','lc',20,19,'E os principais dos sacerdotes e os escribas procuravam lançar mão dele naquela mesma hora; mas temeram o povo; porque entenderam que contra eles dissera esta parábola.'),
('acf','lc',20,20,'E, observando-o, mandaram espias, que se fingissem justos, para o apanharem nalguma palavra, e o entregarem à jurisdição e poder do presidente.'),
('acf','lc',20,21,'E perguntaram-lhe, dizendo: Mestre, nós sabemos que falas e ensinas bem e retamente, e que não consideras a aparência da pessoa, mas ensinas com verdade o caminho de Deus.'),
('acf','lc',20,22,'É-nos lícito dar tributo a César ou não?'),
('acf','lc',20,23,'E, entendendo ele a sua astúcia, disse-lhes: Por que me tentais?'),
('acf','lc',20,24,'Mostrai-me uma moeda. De quem tem a imagem e a inscrição? E, respondendo eles, disseram: De César.'),
('acf','lc',20,25,'Disse-lhes então: Dai, pois, a César o que é de César, e a Deus o que é de Deus.'),
('acf','lc',20,26,'E não puderam apanhá-lo em palavra alguma diante do povo; e, maravilhados da sua resposta, calaram-se.'),
('acf','lc',20,27,'E, chegando-se alguns dos saduceus, que dizem não haver ressurreição, perguntaram-lhe,'),
('acf','lc',20,28,'Dizendo: Mestre, Moisés nos deixou escrito que, se o irmão de algum falecer, tendo mulher, e não deixar filhos, o irmão dele tome a mulher, e suscite posteridade a seu irmão.'),
('acf','lc',20,29,'Houve, pois, sete irmãos, e o primeiro tomou mulher, e morreu sem filhos;'),
('acf','lc',20,30,'E tomou-a o segundo por mulher, e ele morreu sem filhos.'),
('acf','lc',20,31,'E tomou-a o terceiro, e igualmente também os sete; e morreram, e nào deixaram filhos.'),
('acf','lc',20,32,'E por último, depois de todos, morreu também a mulher.'),
('acf','lc',20,33,'Portanto, na ressurreição, de qual deles será a mulher, pois que os sete por mulher a tiveram?'),
('acf','lc',20,34,'E, respondendo Jesus, disse-lhes: Os filhos deste mundo casam-se, e dão-se em casamento;'),
('acf','lc',20,35,'Mas os que forem havidos por dignos de alcançar o mundo vindouro, e a ressurreição dentre os mortos, nem hão de casar, nem ser dados em casamento;'),
('acf','lc',20,36,'Porque já não podem mais morrer; pois são iguais aos anjos, e são filhos de Deus, sendo filhos da ressurreição.'),
('acf','lc',20,37,'E que os mortos hão de ressuscitar também o mostrou Moisés junto da sarça, quando chama ao Senhor Deus de Abraão, e Deus de Isaque, e Deus de Jacó.'),
('acf','lc',20,38,'Ora, Deus não é Deus de mortos, mas de vivos; porque para ele vivem todos.'),
('acf','lc',20,39,'E, respondendo alguns dos escribas, disseram: Mestre, disseste bem.'),
('acf','lc',20,40,'E não ousavam perguntar-lhe mais coisa alguma.'),
('acf','lc',20,41,'E ele lhes disse: Como dizem que o Cristo é filho de Davi?'),
('acf','lc',20,42,'Visto como o mesmo Davi diz no livro dos Salmos: Disse o SENHOR ao meu Senhor: Assenta-te à minha direita,'),
('acf','lc',20,43,'Até que eu ponha os teus inimigos por escabelo de teus pés.'),
('acf','lc',20,44,'Se Davi lhe chama Senhor, como é ele seu filho?'),
('acf','lc',20,45,'E, ouvindo-o todo o povo, disse Jesus aos seus discípulos:'),
('acf','lc',20,46,'Guardai-vos dos escribas, que querem andar com vestes compridas; e amam as saudações nas praças, e as principais cadeiras nas sinagogas, e os primeiros lugares nos banquetes;'),
('acf','lc',20,47,'Que devoram as casas das viúvas, fazendo, por pretexto, largas orações. Estes receberão maior condenação.'),
('acf','lc',21,1,'E, olhando ele, viu os ricos lançarem as suas ofertas na arca do tesouro;'),
('acf','lc',21,2,'E viu também uma pobre viúva lançar ali duas pequenas moedas;'),
('acf','lc',21,3,'E disse: Em verdade vos digo que lançou mais do que todos, esta pobre viúva;'),
('acf','lc',21,4,'Porque todos aqueles deitaram para as ofertas de Deus do que lhes sobeja; mas esta, da sua pobreza, deitou todo o sustento que tinha.'),
('acf','lc',21,5,'E, dizendo alguns a respeito do templo, que estava ornado de formosas pedras e dádivas, disse:'),
('acf','lc',21,6,'Quanto a estas coisas que vedes, dias virão em que não se deixará pedra sobre pedra, que não seja derrubada.'),
('acf','lc',21,7,'E perguntaram-lhe, dizendo: Mestre, quando serão, pois, estas coisas? E que sinal haverá quando isto estiver para acontecer?'),
('acf','lc',21,8,'Disse então ele: Vede não vos enganem, porque virão muitos em meu nome, dizendo: Sou eu, e o tempo está próximo. Não vades, portanto, após eles.'),
('acf','lc',21,9,'E, quando ouvirdes de guerras e sedições, não vos assusteis. Porque é necessário que isto aconteça primeiro, mas o fim não será logo.'),
('acf','lc',21,10,'Então lhes disse: Levantar-se-á nação contra nação, e reino contra reino;'),
('acf','lc',21,11,'E haverá em vários lugares grandes terremotos, e fomes e pestilências; haverá também coisas espantosas, e grandes sinais do céu.'),
('acf','lc',21,12,'Mas antes de todas estas coisas lançarão mão de vós, e vos perseguirão, entregando-vos às sinagogas e às prisões, e conduzindo-vos à presença de reis e presidentes, por amor do meu nome.'),
('acf','lc',21,13,'E vos acontecerá isto para testemunho.'),
('acf','lc',21,14,'Proponde, pois, em vossos corações não premeditar como haveis de responder;'),
('acf','lc',21,15,'Porque eu vos darei boca e sabedoria a que não poderão resistir nem contradizer todos quantos se vos opuserem.'),
('acf','lc',21,16,'E até pelos pais, e irmãos, e parentes, e amigos sereis entregues; e matarão alguns de vós.'),
('acf','lc',21,17,'E de todos sereis odiados por causa do meu nome.'),
('acf','lc',21,18,'Mas não perecerá um único cabelo da vossa cabeça.'),
('acf','lc',21,19,'Na vossa paciência possuí as vossas almas.'),
('acf','lc',21,20,'Mas, quando virdes Jerusalém cercada de exércitos, sabei então que é chegada a sua desolação.'),
('acf','lc',21,21,'Então, os que estiverem na Judéia, fujam para os montes; os que estiverem no meio da cidade, saiam; e os que nos campos não entrem nela.'),
('acf','lc',21,22,'Porque dias de vingança são estes, para que se cumpram todas as coisas que estão escritas.'),
('acf','lc',21,23,'Mas ai das grávidas, e das que criarem naqueles dias! porque haverá grande aperto na terra, e ira sobre este povo.'),
('acf','lc',21,24,'E cairão ao fio da espada, e para todas as nações serão levados cativos; e Jerusalém será pisada pelos gentios, até que os tempos dos gentios se completem.'),
('acf','lc',21,25,'E haverá sinais no sol e na lua e nas estrelas; e na terra angústia das nações, em perplexidade pelo bramido do mar e das ondas.'),
('acf','lc',21,26,'Homens desmaiando de terror, na expectação das coisas que sobrevirão ao mundo; porquanto as virtudes do céu serão abaladas.'),
('acf','lc',21,27,'E então verão vir o Filho do homem numa nuvem, com poder e grande glória.'),
('acf','lc',21,28,'Ora, quando estas coisas começarem a acontecer, olhai para cima e levantai as vossas cabeças, porque a vossa redenção está próxima.'),
('acf','lc',21,29,'E disse-lhes uma parábola: Olhai para a figueira, e para todas as árvores;'),
('acf','lc',21,30,'Quando já têm rebentado, vós sabeis por vós mesmos, vendo-as, que perto está já o verão.'),
('acf','lc',21,31,'Assim também vós, quando virdes acontecer estas coisas, sabei que o reino de Deus está perto.'),
('acf','lc',21,32,'Em verdade vos digo que não passará esta geração até que tudo aconteça.'),
('acf','lc',21,33,'Passará o céu e a terra, mas as minhas palavras não hão de passar.'),
('acf','lc',21,34,'E olhai por vós, não aconteça que os vossos corações se carreguem de glutonaria, de embriaguez, e dos cuidados da vida, e venha sobre vós de improviso aquele dia.'),
('acf','lc',21,35,'Porque virá como um laço sobre todos os que habitam na face de toda a terra.'),
('acf','lc',21,36,'Vigiai, pois, em todo o tempo, orando, para que sejais havidos por dignos de evitar todas estas coisas que hão de acontecer, e de estar em pé diante do Filho do homem.'),
('acf','lc',21,37,'E de dia ensinava no templo, e à noite, saindo, ficava no monte chamado das Oliveiras.'),
('acf','lc',21,38,'E todo o povo ia ter com ele ao templo, de manhã cedo, para o ouvir.'),
('acf','lc',22,1,'Estava, pois, perto a festa dos pães ázimos, chamada a páscoa.'),
('acf','lc',22,2,'E os principais dos sacerdotes, e os escribas, andavam procurando como o matariam; porque temiam o povo.'),
('acf','lc',22,3,'Entrou, porém, Satanás em Judas, que tinha por sobrenome Iscariotes, o qual era do número dos doze.'),
('acf','lc',22,4,'E foi, e falou com os principais dos sacerdotes, e com os capitães, de como lho entregaria;'),
('acf','lc',22,5,'Os quais se alegraram, e convieram em lhe dar dinheiro.'),
('acf','lc',22,6,'E ele concordou; e buscava oportunidade para lho entregar sem alvoroço.'),
('acf','lc',22,7,'Chegou, porém, o dia dos ázimos, em que importava sacrificar a páscoa.'),
('acf','lc',22,8,'E mandou a Pedro e a João, dizendo: Ide, preparai-nos a páscoa, para que a comamos.'),
('acf','lc',22,9,'E eles lhe perguntaram: Onde queres que a preparemos?'),
('acf','lc',22,10,'E ele lhes disse: Eis que, quando entrardes na cidade, encontrareis um homem, levando um cântaro de água; segui-o até à casa em que ele entrar.'),
('acf','lc',22,11,'E direis ao pai de família da casa: O Mestre te diz: Onde está o aposento em que hei de comer a páscoa com os meus discípulos?'),
('acf','lc',22,12,'Então ele vos mostrará um grande cenáculo mobilado; aí fazei preparativos.'),
('acf','lc',22,13,'E, indo eles, acharam como lhes havia sido dito; e prepararam a páscoa.'),
('acf','lc',22,14,'E, chegada a hora, pôs-se à mesa, e com ele os doze apóstolos.'),
('acf','lc',22,15,'E disse-lhes: Desejei muito comer convosco esta páscoa, antes que padeça;'),
('acf','lc',22,16,'Porque vos digo que não a comerei mais até que ela se cumpra no reino de Deus.'),
('acf','lc',22,17,'E, tomando o cálice, e havendo dado graças, disse: Tomai-o, e reparti-o entre vós;'),
('acf','lc',22,18,'Porque vos digo que já não beberei do fruto da vide, até que venha o reino de Deus.'),
('acf','lc',22,19,'E, tomando o pão, e havendo dado graças, partiu-o, e deu-lho, dizendo: Isto é o meu corpo, que por vós é dado; fazei isto em memória de mim.'),
('acf','lc',22,20,'Semelhantemente, tomou o cálice, depois da ceia, dizendo: Este cálice é o novo testamento no meu sangue, que é derramado por vós.'),
('acf','lc',22,21,'Mas eis que a mão do que me trai está comigo à mesa.'),
('acf','lc',22,22,'E, na verdade, o Filho do homem vai segundo o que está determinado; mas ai daquele homem por quem é traído!'),
('acf','lc',22,23,'E começaram a perguntar entre si qual deles seria o que havia de fazer isto.'),
('acf','lc',22,24,'E houve também entre eles contenda, sobre qual deles parecia ser o maior.'),
('acf','lc',22,25,'E ele lhes disse: Os reis dos gentios dominam sobre eles, e os que têm autoridade sobre eles são chamados benfeitores.'),
('acf','lc',22,26,'Mas não sereis vós assim; antes o maior entre vós seja como o menor; e quem governa como quem serve.'),
('acf','lc',22,27,'Pois qual é maior: quem está à mesa, ou quem serve? Porventura não é quem está à mesa? Eu, porém, entre vós sou como aquele que serve.'),
('acf','lc',22,28,'E vós sois os que tendes permanecido comigo nas minhas tentações.'),
('acf','lc',22,29,'E eu vos destino o reino, como meu Pai mo destinou,'),
('acf','lc',22,30,'Para que comais e bebais à minha mesa no meu reino, e vos assenteis sobre tronos, julgando as doze tribos de Israel.'),
('acf','lc',22,31,'Disse também o Senhor: Simão, Simão, eis que Satanás vos pediu para vos cirandar como trigo;'),
('acf','lc',22,32,'Mas eu roguei por ti, para que a tua fé não desfaleça; e tu, quando te converteres, confirma teus irmãos.'),
('acf','lc',22,33,'E ele lhe disse: Senhor, estou pronto a ir contigo até à prisão e à morte.'),
('acf','lc',22,34,'Mas ele disse: Digo-te, Pedro, que não cantará hoje o galo antes que três vezes negues que me conheces.'),
('acf','lc',22,35,'E disse-lhes: Quando vos mandei sem bolsa, alforje, ou alparcas, faltou-vos porventura alguma coisa? Eles responderam: Nada.'),
('acf','lc',22,36,'Disse-lhes pois: Mas agora, aquele que tiver bolsa, tome-a, como também o alforje; e, o que não tem espada, venda a sua capa e compre-a;'),
('acf','lc',22,37,'Porquanto vos digo que importa que em mim se cumpra aquilo que está escrito: E com os malfeitores foi contado. Porque o que está escrito de mim terá cumprimento.'),
('acf','lc',22,38,'E eles disseram: Senhor, eis aqui duas espadas. E ele lhes disse: Basta.'),
('acf','lc',22,39,'E, saindo, foi, como costumava, para o Monte das Oliveiras; e também os seus discípulos o seguiram.'),
('acf','lc',22,40,'E quando chegou àquele lugar, disse-lhes: Orai, para que não entreis em tentação.'),
('acf','lc',22,41,'E apartou-se deles cerca de um tiro de pedra; e, pondo-se de joelhos, orava,'),
('acf','lc',22,42,'Dizendo: Pai, se queres, passa de mim este cálice; todavia não se faça a minha vontade, mas a tua.'),
('acf','lc',22,43,'E apareceu-lhe um anjo do céu, que o fortalecia.'),
('acf','lc',22,44,'E, posto em agonia, orava mais intensamente. E o seu suor tornou-se como grandes gotas de sangue, que corriam até ao chão.'),
('acf','lc',22,45,'E, levantando-se da oração, veio para os seus discípulos, e achou-os dormindo de tristeza.'),
('acf','lc',22,46,'E disse-lhes: Por que estais dormindo? Levantai-vos, e orai, para que não entreis em tentação.'),
('acf','lc',22,47,'E, estando ele ainda a falar, surgiu uma multidão; e um dos doze, que se chamava Judas, ia adiante dela, e chegou-se a Jesus para o beijar.'),
('acf','lc',22,48,'E Jesus lhe disse: Judas, com um beijo trais o Filho do homem?'),
('acf','lc',22,49,'E, vendo os que estavam com ele o que ia suceder, disseram-lhe: Senhor, feriremos à espada?'),
('acf','lc',22,50,'E um deles feriu o servo do sumo sacerdote, e cortou-lhe a orelha direita.'),
('acf','lc',22,51,'E, respondendo Jesus, disse: Deixai-os; basta. E, tocando-lhe a orelha, o curou.'),
('acf','lc',22,52,'E disse Jesus aos principais dos sacerdotes, e capitães do templo, e anciãos, que tinham ido contra ele: Saístes, como a um salteador, com espadas e varapaus?'),
('acf','lc',22,53,'Tenho estado todos os dias convosco no templo, e não estendestes as mãos contra mim, mas esta é a vossa hora e o poder das trevas.'),
('acf','lc',22,54,'Então, prendendo-o, o levaram, e o puseram em casa do sumo sacerdote. E Pedro seguia-o de longe.'),
('acf','lc',22,55,'E, havendo-se acendido fogo no meio do pátio, estando todos sentados, assentou-se Pedro entre eles.'),
('acf','lc',22,56,'E como certa criada, vendo-o estar assentado ao fogo, pusesse os olhos nele, disse: Este também estava com ele.'),
('acf','lc',22,57,'Porém, ele negou-o, dizendo: Mulher, não o conheço.'),
('acf','lc',22,58,'E, um pouco depois, vendo-o outro, disse: Tu és também deles. Mas Pedro disse: Homem, não sou.'),
('acf','lc',22,59,'E, passada quase uma hora, um outro afirmava, dizendo: Também este verdadeiramente estava com ele, pois também é galileu.'),
('acf','lc',22,60,'E Pedro disse: Homem, não sei o que dizes. E logo, estando ele ainda a falar, cantou o galo.'),
('acf','lc',22,61,'E, virando-se o Senhor, olhou para Pedro, e Pedro lembrou-se da palavra do Senhor, como lhe havia dito: Antes que o galo cante hoje, me negarás três vezes.'),
('acf','lc',22,62,'E, saindo Pedro para fora, chorou amargamente.'),
('acf','lc',22,63,'E os homens que detinham Jesus zombavam dele, ferindo-o.'),
('acf','lc',22,64,'E, vendando-lhe os olhos, feriam-no no rosto, e perguntavam-lhe, dizendo: Profetiza, quem é que te feriu?'),
('acf','lc',22,65,'E outras muitas coisas diziam contra ele, blasfemando.'),
('acf','lc',22,66,'E logo que foi dia ajuntaram-se os anciãos do povo, e os principais dos sacerdotes e os escribas, e o conduziram ao seu concílio, e lhe perguntaram:'),
('acf','lc',22,67,'És tu o Cristo? Dize-no-lo. Ele replicou: Se vo-lo disser, não o crereis;'),
('acf','lc',22,68,'E também, se vos perguntar, não me respondereis, nem me soltareis.'),
('acf','lc',22,69,'Desde agora o Filho do homem se assentará à direita do poder de Deus.'),
('acf','lc',22,70,'E disseram todos: Logo, és tu o Filho de Deus? E ele lhes disse: Vós dizeis que eu sou.'),
('acf','lc',22,71,'Então disseram: De que mais testemunho necessitamos? pois nós mesmos o ouvimos da sua boca.'),
('acf','lc',23,1,'E, levantando-se toda a multidão deles, o levaram a Pilatos.'),
('acf','lc',23,2,'E começaram a acusá-lo, dizendo: Havemos achado este pervertendo a nação, proibindo dar o tributo a César, e dizendo que ele mesmo é Cristo, o rei.'),
('acf','lc',23,3,'E Pilatos perguntou-lhe, dizendo: Tu és o Rei dos Judeus? E ele, respondendo, disse-lhe: Tu o dizes.'),
('acf','lc',23,4,'E disse Pilatos aos principais dos sacerdotes, e à multidão: Não acho culpa alguma neste homem.'),
('acf','lc',23,5,'Mas eles insistiam cada vez mais, dizendo: Alvoroça o povo ensinando por toda a Judéia, começando desde a Galiléia até aqui.'),
('acf','lc',23,6,'Então Pilatos, ouvindo falar da Galiléia perguntou se aquele homem era galileu.'),
('acf','lc',23,7,'E, sabendo que era da jurisdição de Herodes, remeteu-o a Herodes, que também naqueles dias estava em Jerusalém.'),
('acf','lc',23,8,'E Herodes, quando viu a Jesus, alegrou-se muito; porque havia muito que desejava vê-lo, por ter ouvido dele muitas coisas; e esperava que lhe veria fazer algum sinal.'),
('acf','lc',23,9,'E interrogava-o com muitas palavras, mas ele nada lhe respondia.'),
('acf','lc',23,10,'E estavam os principais dos sacerdotes, e os escribas, acusando-o com grande veemência.'),
('acf','lc',23,11,'E Herodes, com os seus soldados, desprezou-o e, escarnecendo dele, vestiu-o de uma roupa resplandecente e tornou a enviá-lo a Pilatos.'),
('acf','lc',23,12,'E no mesmo dia, Pilatos e Herodes entre si se fizeram amigos; pois dantes andavam em inimizade um com o outro.'),
('acf','lc',23,13,'E, convocando Pilatos os principais dos sacerdotes, e os magistrados, e o povo,'),
('acf','lc',23,14,'Disse-lhes: Haveis-me apresentado este homem como pervertedor do povo; e eis que, examinando-o na vossa presença, nenhuma culpa, das de que o acusais, acho neste homem.'),
('acf','lc',23,15,'Nem mesmo Herodes, porque a ele vos remeti, e eis que não tem feito coisa alguma digna de morte.'),
('acf','lc',23,16,'Castigá-lo-ei, pois, e soltá-lo-ei.'),
('acf','lc',23,17,'E era-lhe necessário soltar-lhes um pela festa.'),
('acf','lc',23,18,'Mas toda a multidão clamou a uma, dizendo: Fora daqui com este, e solta-nos Barrabás.'),
('acf','lc',23,19,'O qual fora lançado na prisão por causa de uma sedição feita na cidade, e de um homicídio.'),
('acf','lc',23,20,'Falou, pois, outra vez Pilatos, querendo soltar a Jesus.'),
('acf','lc',23,21,'Mas eles clamavam em contrário, dizendo: Crucifica-o, crucifica-o.'),
('acf','lc',23,22,'Então ele, pela terceira vez, lhes disse: Mas que mal fez este? Não acho nele culpa alguma de morte. Castigá-lo-ei pois, e soltá-lo-ei.'),
('acf','lc',23,23,'Mas eles instavam com grandes gritos, pedindo que fosse crucificado. E os seus gritos, e os dos principais dos sacerdotes, prevaleciam.'),
('acf','lc',23,24,'Então Pilatos julgou que devia fazer o que eles pediam.'),
('acf','lc',23,25,'E soltou-lhes o que fora lançado na prisão por uma sedição e homicídio, que era o que pediam; mas entregou Jesus à vontade deles.'),
('acf','lc',23,26,'E quando o iam levando, tomaram um certo Simão, cireneu, que vinha do campo, e puseram-lhe a cruz às costas, para que a levasse após Jesus.'),
('acf','lc',23,27,'E seguia-o grande multidão de povo e de mulheres, as quais batiam nos peitos, e o lamentavam.'),
('acf','lc',23,28,'Jesus, porém, voltando-se para elas, disse: Filhas de Jerusalém, não choreis por mim; chorai antes por vós mesmas, e por vossos filhos.'),
('acf','lc',23,29,'Porque eis que hão de vir dias em que dirão: Bem-aventuradas as estéreis, e os ventres que não geraram, e os peitos que não amamentaram!'),
('acf','lc',23,30,'Então começarão a dizer aos montes: Caí sobre nós, e aos outeiros: Cobri-nos.'),
('acf','lc',23,31,'Porque, se ao madeiro verde fazem isto, que se fará ao seco?'),
('acf','lc',23,32,'E também conduziram outros dois, que eram malfeitores, para com ele serem mortos.'),
('acf','lc',23,33,'E, quando chegaram ao lugar chamado a Caveira, ali o crucificaram, e aos malfeitores, um à direita e outro à esquerda.'),
('acf','lc',23,34,'E dizia Jesus: Pai, perdoa-lhes, porque não sabem o que fazem. E, repartindo as suas vestes, lançaram sortes.'),
('acf','lc',23,35,'E o povo estava olhando. E também os príncipes zombavam dele, dizendo: Aos outros salvou, salve-se a si mesmo, se este é o Cristo, o escolhido de Deus.'),
('acf','lc',23,36,'E também os soldados o escarneciam, chegando-se a ele, e apresentando-lhe vinagre.'),
('acf','lc',23,37,'E dizendo: Se tu és o Rei dos Judeus, salva-te a ti mesmo.'),
('acf','lc',23,38,'E também por cima dele, estava um título, escrito em letras gregas, romanas, e hebraicas: ESTE É O REI DOS JUDEUS.'),
('acf','lc',23,39,'E um dos malfeitores que estavam pendurados blasfemava dele, dizendo: Se tu és o Cristo, salva-te a ti mesmo, e a nós.'),
('acf','lc',23,40,'Respondendo, porém, o outro, repreendia-o, dizendo: Tu nem ainda temes a Deus, estando na mesma condenação?'),
('acf','lc',23,41,'E nós, na verdade, com justiça, porque recebemos o que os nossos feitos mereciam; mas este nenhum mal fez.'),
('acf','lc',23,42,'E disse a Jesus: Senhor, lembra-te de mim, quando entrares no teu reino.'),
('acf','lc',23,43,'E disse-lhe Jesus: Em verdade te digo que hoje estarás comigo no Paraíso.'),
('acf','lc',23,44,'E era já quase a hora sexta, e houve trevas em toda a terra até à hora nona, escurecendo-se o sol;'),
('acf','lc',23,45,'E rasgou-se ao meio o véu do templo.'),
('acf','lc',23,46,'E, clamando Jesus com grande voz, disse: Pai, nas tuas mãos entrego o meu espírito. E, havendo dito isto, expirou.'),
('acf','lc',23,47,'E o centurião, vendo o que tinha acontecido, deu glória a Deus, dizendo: Na verdade, este homem era justo.'),
('acf','lc',23,48,'E toda a multidão que se ajuntara a este espetáculo, vendo o que havia acontecido, voltava batendo nos peitos.'),
('acf','lc',23,49,'E todos os seus conhecidos, e as mulheres que juntamente o haviam seguido desde a Galiléia, estavam de longe vendo estas coisas.'),
('acf','lc',23,50,'E eis que um homem por nome José, senador, homem de bem e justo,'),
('acf','lc',23,51,'Que não tinha consentido no conselho e nos atos dos outros, de Arimatéia, cidade dos judeus, e que também esperava o reino de Deus;'),
('acf','lc',23,52,'Esse, chegando a Pilatos, pediu o corpo de Jesus.'),
('acf','lc',23,53,'E, havendo-o tirado, envolveu-o num lençol, e pô-lo num sepulcro escavado numa penha, onde ninguém ainda havia sido posto.'),
('acf','lc',23,54,'E era o dia da preparação, e amanhecia o sábado.'),
('acf','lc',23,55,'E as mulheres, que tinham vindo com ele da Galiléia, seguiram também e viram o sepulcro, e como foi posto o seu corpo.'),
('acf','lc',23,56,'E, voltando elas, prepararam especiarias e ungüentos; e no sábado repousaram, conforme o mandamento.'),
('acf','lc',24,1,'E no primeiro dia da semana, muito de madrugada, foram elas ao sepulcro, levando as especiarias que tinham preparado, e algumas outras com elas.'),
('acf','lc',24,2,'E acharam a pedra revolvida do sepulcro.'),
('acf','lc',24,3,'E, entrando, não acharam o corpo do Senhor Jesus.'),
('acf','lc',24,4,'E aconteceu que, estando elas muito perplexas a esse respeito, eis que pararam junto delas dois homens, com vestes resplandecentes.'),
('acf','lc',24,5,'E, estando elas muito atemorizadas, e abaixando o rosto para o chão, eles lhes disseram: Por que buscais o vivente entre os mortos?'),
('acf','lc',24,6,'Não está aqui, mas ressuscitou. Lembrai-vos como vos falou, estando ainda na Galiléia,'),
('acf','lc',24,7,'Dizendo: Convém que o Filho do homem seja entregue nas mãos de homens pecadores, e seja crucificado, e ao terceiro dia ressuscite.'),
('acf','lc',24,8,'E lembraram-se das suas palavras.'),
('acf','lc',24,9,'E, voltando do sepulcro, anunciaram todas estas coisas aos onze e a todos os demais.'),
('acf','lc',24,10,'E eram Maria Madalena, e Joana, e Maria, mãe de Tiago, e as outras que com elas estavam, as que diziam estas coisas aos apóstolos.'),
('acf','lc',24,11,'E as suas palavras lhes pareciam como desvario, e não as creram.'),
('acf','lc',24,12,'Pedro, porém, levantando-se, correu ao sepulcro e, abaixando-se, viu só os lençóis ali postos; e retirou-se, admirando consigo aquele caso.'),
('acf','lc',24,13,'E eis que no mesmo dia iam dois deles para uma aldeia, que distava de Jerusalém sessenta estádios, cujo nome era Emaús.'),
('acf','lc',24,14,'E iam falando entre si de tudo aquilo que havia sucedido.'),
('acf','lc',24,15,'E aconteceu que, indo eles falando entre si, e fazendo perguntas um ao outro, o mesmo Jesus se aproximou, e ia com eles.'),
('acf','lc',24,16,'Mas os olhos deles estavam como que fechados, para que o não conhecessem.'),
('acf','lc',24,17,'E ele lhes disse: Que palavras são essas que, caminhando, trocais entre vós, e por que estais tristes?'),
('acf','lc',24,18,'E, respondendo um, cujo nome era Cléopas, disse-lhe: És tu só peregrino em Jerusalém, e não sabes as coisas que nela têm sucedido nestes dias?'),
('acf','lc',24,19,'E ele lhes perguntou: Quais? E eles lhe disseram: As que dizem respeito a Jesus Nazareno, que foi homem profeta, poderoso em obras e palavras diante de Deus e de todo o povo;'),
('acf','lc',24,20,'E como os principais dos sacerdotes e os nossos príncipes o entregaram à condenação de morte, e o crucificaram.'),
('acf','lc',24,21,'E nós esperávamos que fosse ele o que remisse Israel; mas agora, sobre tudo isso, é já hoje o terceiro dia desde que essas coisas aconteceram.'),
('acf','lc',24,22,'É verdade que também algumas mulheres dentre nós nos maravilharam, as quais de madrugada foram ao sepulcro;'),
('acf','lc',24,23,'E, não achando o seu corpo, voltaram, dizendo que também tinham visto uma visão de anjos, que dizem que ele vive.'),
('acf','lc',24,24,'E alguns dos que estavam conosco foram ao sepulcro, e acharam ser assim como as mulheres haviam dito; porém, a ele não o viram.'),
('acf','lc',24,25,'E ele lhes disse: Ó néscios, e tardos de coração para crer tudo o que os profetas disseram!'),
('acf','lc',24,26,'Porventura não convinha que o Cristo padecesse estas coisas e entrasse na sua glória?'),
('acf','lc',24,27,'E, começando por Moisés, e por todos os profetas, explicava-lhes o que dele se achava em todas as Escrituras.'),
('acf','lc',24,28,'E chegaram à aldeia para onde iam, e ele fez como quem ia para mais longe.'),
('acf','lc',24,29,'E eles o constrangeram, dizendo: Fica conosco, porque já é tarde, e já declinou o dia. E entrou para ficar com eles.'),
('acf','lc',24,30,'E aconteceu que, estando com eles à mesa, tomando o pão, o abençoou e partiu-o, e lho deu.'),
('acf','lc',24,31,'Abriram-se-lhes então os olhos, e o conheceram, e ele desapareceu-lhes.'),
('acf','lc',24,32,'E disseram um para o outro: Porventura não ardia em nós o nosso coração quando, pelo caminho, nos falava, e quando nos abria as Escrituras?'),
('acf','lc',24,33,'E na mesma hora, levantando-se, tornaram para Jerusalém, e acharam congregados os onze, e os que estavam com eles,'),
('acf','lc',24,34,'Os quais diziam: Ressuscitou verdadeiramente o Senhor, e já apareceu a Simão.'),
('acf','lc',24,35,'E eles lhes contaram o que lhes acontecera no caminho, e como deles fora conhecido no partir do pão.'),
('acf','lc',24,36,'E falando eles destas coisas, o mesmo Jesus se apresentou no meio deles, e disse-lhes: Paz seja convosco.'),
('acf','lc',24,37,'E eles, espantados e atemorizados, pensavam que viam algum espírito.'),
('acf','lc',24,38,'E ele lhes disse: Por que estais perturbados, e por que sobem tais pensamentos aos vossos corações?'),
('acf','lc',24,39,'Vede as minhas mãos e os meus pés, que sou eu mesmo; apalpai-me e vede, pois um espírito não tem carne nem ossos, como vedes que eu tenho.'),
('acf','lc',24,40,'E, dizendo isto, mostrou-lhes as mãos e os pés.'),
('acf','lc',24,41,'E, não o crendo eles ainda por causa da alegria, e estando maravilhados, disse-lhes: Tendes aqui alguma coisa que comer?'),
('acf','lc',24,42,'Então eles apresentaram-lhe parte de um peixe assado, e um favo de mel;'),
('acf','lc',24,43,'O que ele tomou, e comeu diante deles.'),
('acf','lc',24,44,'E disse-lhes: São estas as palavras que vos disse estando ainda convosco: Que convinha que se cumprisse tudo o que de mim estava escrito na lei de Moisés, e nos profetas e nos Salmos.'),
('acf','lc',24,45,'Então abriu-lhes o entendimento para compreenderem as Escrituras.'),
('acf','lc',24,46,'E disse-lhes: Assim está escrito, e assim convinha que o Cristo padecesse, e ao terceiro dia ressuscitasse dentre os mortos,'),
('acf','lc',24,47,'E em seu nome se pregasse o arrependimento e a remissão dos pecados, em todas as nações, começando por Jerusalém.'),
('acf','lc',24,48,'E destas coisas sois vós testemunhas.'),
('acf','lc',24,49,'E eis que sobre vós envio a promessa de meu Pai; ficai, porém, na cidade de Jerusalém, até que do alto sejais revestidos de poder.'),
('acf','lc',24,50,'E levou-os fora, até betânia; e, levantando as suas mãos, os abençoou.'),
('acf','lc',24,51,'E aconteceu que, abençoando-os ele, se apartou deles e foi elevado ao céu.'),
('acf','lc',24,52,'E, adorando-o eles, tornaram com grande júbilo para Jerusalém.'),
('acf','lc',24,53,'E estavam sempre no templo, louvando e bendizendo a Deus. Amém.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','jo',1,1,'No princípio era o Verbo, e o Verbo estava com Deus, e o Verbo era Deus.'),
('acf','jo',1,2,'Ele estava no princípio com Deus.'),
('acf','jo',1,3,'Todas as coisas foram feitas por ele, e sem ele nada do que foi feito se fez.'),
('acf','jo',1,4,'Nele estava a vida, e a vida era a luz dos homens.'),
('acf','jo',1,5,'E a luz resplandece nas trevas, e as trevas não a compreenderam.'),
('acf','jo',1,6,'Houve um homem enviado de Deus, cujo nome era João.'),
('acf','jo',1,7,'Este veio para testemunho, para que testificasse da luz, para que todos cressem por ele.'),
('acf','jo',1,8,'Não era ele a luz, mas para que testificasse da luz.'),
('acf','jo',1,9,'Ali estava a luz verdadeira, que ilumina a todo o homem que vem ao mundo.'),
('acf','jo',1,10,'Estava no mundo, e o mundo foi feito por ele, e o mundo não o conheceu.'),
('acf','jo',1,11,'Veio para o que era seu, e os seus não o receberam.'),
('acf','jo',1,12,'Mas, a todos quantos o receberam, deu-lhes o poder de serem feitos filhos de Deus, aos que crêem no seu nome;'),
('acf','jo',1,13,'Os quais não nasceram do sangue, nem da vontade da carne, nem da vontade do homem, mas de Deus.'),
('acf','jo',1,14,'E o Verbo se fez carne, e habitou entre nós, e vimos a sua glória, como a glória do unigênito do Pai, cheio de graça e de verdade.'),
('acf','jo',1,15,'João testificou dele, e clamou, dizendo: Este era aquele de quem eu dizia: O que vem após mim é antes de mim, porque foi primeiro do que eu.'),
('acf','jo',1,16,'E todos nós recebemos também da sua plenitude, e graça por graça.'),
('acf','jo',1,17,'Porque a lei foi dada por Moisés; a graça e a verdade vieram por Jesus Cristo.'),
('acf','jo',1,18,'Deus nunca foi visto por alguém. O Filho unigênito, que está no seio do Pai, esse o revelou.'),
('acf','jo',1,19,'E este é o testemunho de João, quando os judeus mandaram de Jerusalém sacerdotes e levitas para que lhe perguntassem: Quem és tu?'),
('acf','jo',1,20,'E confessou, e não negou; confessou: Eu não sou o Cristo.'),
('acf','jo',1,21,'E perguntaram-lhe: Então quê? És tu Elias? E disse: Não sou. És tu profeta? E respondeu: Não.'),
('acf','jo',1,22,'Disseram-lhe pois: Quem és? para que demos resposta àqueles que nos enviaram; que dizes de ti mesmo?'),
('acf','jo',1,23,'Disse: Eu sou a voz do que clama no deserto: Endireitai o caminho do Senhor, como disse o profeta Isaías.'),
('acf','jo',1,24,'E os que tinham sido enviados eram dos fariseus.'),
('acf','jo',1,25,'E perguntaram-lhe, e disseram-lhe: Por que batizas, pois, se tu não és o Cristo, nem Elias, nem o profeta?'),
('acf','jo',1,26,'João respondeu-lhes, dizendo: Eu batizo com água; mas no meio devós está um a quem vós não conheceis.'),
('acf','jo',1,27,'Este é aquele que vem após mim, que é antes de mim, do qual eu não sou digno de desatar a correia da alparca.'),
('acf','jo',1,28,'Estas coisas aconteceram em Betabara, do outro lado do Jordão, onde João estava batizando.'),
('acf','jo',1,29,'No dia seguinte João viu a Jesus, que vinha para ele, e disse: Eis o Cordeiro de Deus, que tira o pecado do mundo.'),
('acf','jo',1,30,'Este é aquele do qual eu disse: Após mim vem um homem que é antes de mim, porque foi primeiro do que eu.'),
('acf','jo',1,31,'E eu não o conhecia; mas, para que ele fosse manifestado a Israel, vim eu, por isso, batizando com água.'),
('acf','jo',1,32,'E João testificou, dizendo: Eu vi o Espírito descer do céu como pomba, e repousar sobre ele.'),
('acf','jo',1,33,'E eu não o conhecia, mas o que me mandou a batizar com água, esse me disse: Sobre aquele que vires descer o Espírito, e sobre ele repousar, esse é o que batiza com o Espírito Santo.'),
('acf','jo',1,34,'E eu vi, e tenho testificado que este é o Filho de Deus.'),
('acf','jo',1,35,'No dia seguinte João estava outra vez ali, e dois dos seus discípulos;'),
('acf','jo',1,36,'E, vendo passar a Jesus, disse: Eis aqui o Cordeiro de Deus.'),
('acf','jo',1,37,'E os dois discípulos ouviram-no dizer isto, e seguiram a Jesus.'),
('acf','jo',1,38,'E Jesus, voltando-se e vendo que eles o seguiam, disse-lhes: Que buscais? E eles disseram: Rabi (que, traduzido, quer dizer Mestre), onde moras?'),
('acf','jo',1,39,'Ele lhes disse: Vinde, e vede. Foram, e viram onde morava, e ficaram com ele aquele dia; e era já quase a hora décima.'),
('acf','jo',1,40,'Era André, irmão de Simão Pedro, um dos dois que ouviram aquilo de João, e o haviam seguido.'),
('acf','jo',1,41,'Este achou primeiro a seu irmão Simão, e disse-lhe: Achamos o Messias (que, traduzido, é o Cristo).'),
('acf','jo',1,42,'E levou-o a Jesus. E, olhando Jesus para ele, disse: Tu és Simão, filho de Jonas; tu serás chamado Cefas (que quer dizer Pedro).'),
('acf','jo',1,43,'No dia seguinte quis Jesus ir à Galiléia, e achou a Filipe, e disse-lhe: Segue-me.'),
('acf','jo',1,44,'E Filipe era de Betsaida, cidade de André e de Pedro.'),
('acf','jo',1,45,'Filipe achou Natanael, e disse-lhe: Havemos achado aquele de quem Moisés escreveu na lei, e os profetas: Jesus de Nazaré, filho de José.'),
('acf','jo',1,46,'Disse-lhe Natanael: Pode vir alguma coisa boa de Nazaré? Disse-lhe Filipe: Vem, e vê.'),
('acf','jo',1,47,'Jesus viu Natanael vir ter com ele, e disse dele: Eis aqui um verdadeiro israelita, em quem não há dolo.'),
('acf','jo',1,48,'Disse-lhe Natanael: De onde me conheces tu? Jesus respondeu, e disse-lhe: Antes que Filipe te chamasse, te vi eu, estando tu debaixo da figueira.'),
('acf','jo',1,49,'Natanael respondeu, e disse-lhe: Rabi, tu és o Filho de Deus; tu és o Rei de Israel.'),
('acf','jo',1,50,'Jesus respondeu, e disse-lhe: Porque te disse: Vi-te debaixo da figueira, crês? Coisas maiores do que estas verás.'),
('acf','jo',1,51,'E disse-lhe: Na verdade, na verdade vos digo que daqui em diante vereis o céu aberto, e os anjos de Deus subindo e descendo sobre o Filho do homem.'),
('acf','jo',2,1,'E, ao terceiro dia, fizeram-se umas bodas em Caná da Galiléia; e estava ali a mãe de Jesus.'),
('acf','jo',2,2,'E foi também convidado Jesus e os seus discípulos para as bodas.'),
('acf','jo',2,3,'E, faltando vinho, a mãe de Jesus lhe disse: Não têm vinho.'),
('acf','jo',2,4,'Disse-lhe Jesus: Mulher, que tenho eu contigo? Ainda não é chegada a minha hora.'),
('acf','jo',2,5,'Sua mãe disse aos serventes: Fazei tudo quanto ele vos disser.'),
('acf','jo',2,6,'E estavam ali postas seis talhas de pedra, para as purificações dos judeus, e em cada uma cabiam dois ou três almudes.'),
('acf','jo',2,7,'Disse-lhes Jesus: Enchei de água essas talhas. E encheram-nas até em cima.'),
('acf','jo',2,8,'E disse-lhes: Tirai agora, e levai ao mestre-sala. E levaram.'),
('acf','jo',2,9,'E, logo que o mestre-sala provou a água feita vinho (não sabendo de onde viera, se bem que o sabiam os serventes que tinham tirado a água), chamou o mestre-sala ao esposo,'),
('acf','jo',2,10,'E disse-lhe: Todo o homem põe primeiro o vinho bom e, quando já têm bebido bem, então o inferior; mas tu guardaste até agora o bom vinho.'),
('acf','jo',2,11,'Jesus principiou assim os seus sinais em Caná da Galiléia, e manifestou a sua glória; e os seus discípulos creram nele.'),
('acf','jo',2,12,'Depois disto desceu a Cafarnaum, ele, e sua mãe, e seus irmãos, e seus discípulos; e ficaram ali não muitos dias.'),
('acf','jo',2,13,'E estava próxima a páscoa dos judeus, e Jesus subiu a Jerusalém.'),
('acf','jo',2,14,'E achou no templo os que vendiam bois, e ovelhas, e pombos, e os cambiadores assentados.'),
('acf','jo',2,15,'E tendo feito um azorrague de cordéis, lançou todos fora do templo, também os bois e ovelhas; e espalhou o dinheiro dos cambiadores, e derribou as mesas;'),
('acf','jo',2,16,'E disse aos que vendiam pombos: Tirai daqui estes, e não façais da casa de meu Pai casa de venda.'),
('acf','jo',2,17,'E os seus discípulos lembraram-se do que está escrito: O zelo da tua casa me devorou.'),
('acf','jo',2,18,'Responderam, pois, os judeus, e disseram-lhe: Que sinal nos mostras para fazeres isto?'),
('acf','jo',2,19,'Jesus respondeu, e disse-lhes: Derribai este templo, e em três dias o levantarei.'),
('acf','jo',2,20,'Disseram, pois, os judeus: Em quarenta e seis anos foi edificado este templo, e tu o levantarás em três dias?'),
('acf','jo',2,21,'Mas ele falava do templo do seu corpo.'),
('acf','jo',2,22,'Quando, pois, ressuscitou dentre os mortos, os seus discípulos lembraram-se de que lhes dissera isto; e creram na Escritura, e na palavra que Jesus tinha dito.'),
('acf','jo',2,23,'E, estando ele em Jerusalém pela páscoa, durante a festa, muitos, vendo os sinais que fazia, creram no seu nome.'),
('acf','jo',2,24,'Mas o mesmo Jesus não confiava neles, porque a todos conhecia;'),
('acf','jo',2,25,'E não necessitava de que alguém testificasse do homem, porque ele bem sabia o que havia no homem.'),
('acf','jo',3,1,'E havia entre os fariseus um homem, chamado Nicodemos, príncipe dos judeus.'),
('acf','jo',3,2,'Este foi ter de noite com Jesus, e disse-lhe: Rabi, bem sabemos que és Mestre, vindo de Deus; porque ninguém pode fazer estes sinais que tu fazes, se Deus não for com ele.'),
('acf','jo',3,3,'Jesus respondeu, e disse-lhe: Na verdade, na verdade te digo que aquele que não nascer de novo, não pode ver o reino de Deus.'),
('acf','jo',3,4,'Disse-lhe Nicodemos: Como pode um homem nascer, sendo velho? Pode, porventura, tornar a entrar no ventre de sua mãe, e nascer?'),
('acf','jo',3,5,'Jesus respondeu: Na verdade, na verdade te digo que aquele que não nascer da água e do Espírito, não pode entrar no reino de Deus.'),
('acf','jo',3,6,'O que é nascido da carne é carne, e o que é nascido do Espírito é espírito.'),
('acf','jo',3,7,'Não te maravilhes de te ter dito: Necessário vos é nascer de novo.'),
('acf','jo',3,8,'O vento assopra onde quer, e ouves a sua voz, mas não sabes de onde vem, nem para onde vai; assim étodo aquele que é nascido do Espírito.'),
('acf','jo',3,9,'Nicodemos respondeu, e disse-lhe: Como pode ser isso?'),
('acf','jo',3,10,'Jesus respondeu, e disse-lhe: Tu és mestre de Israel, e não sabes isto?'),
('acf','jo',3,11,'Na verdade, na verdade te digo que nós dizemos o que sabemos, e testificamos o que vimos; e não aceitais o nosso testemunho.'),
('acf','jo',3,12,'Se vos falei de coisas terrestres, e não crestes, como crereis, se vos falar das celestiais?'),
('acf','jo',3,13,'Ora, ninguém subiu ao céu, senão o que desceu do céu, o Filho do homem, que está no céu.'),
('acf','jo',3,14,'E, como Moisés levantou a serpente no deserto, assim importa que o Filho do homem seja levantado;'),
('acf','jo',3,15,'Para que todo aquele que nele crê não pereça, mas tenha a vida eterna.'),
('acf','jo',3,16,'Porque Deus amou o mundo de tal maneira que deu o seu Filho unigênito, para que todo aquele que nele crê não pereça, mas tenha a vida eterna.'),
('acf','jo',3,17,'Porque Deus enviou o seu Filho ao mundo, não para que condenasse o mundo, mas para que o mundo fosse salvo por ele.'),
('acf','jo',3,18,'Quem crê nele não é condenado; mas quem não crê já está condenado, porquanto não crê no nome do unigênito Filho de Deus.'),
('acf','jo',3,19,'E a condenação é esta: Que a luz veio ao mundo, e os homens amaram mais as trevas do que a luz, porque as suas obras eram más.'),
('acf','jo',3,20,'Porque todo aquele que faz o mal odeia a luz, e não vem para a luz, para que as suas obras não sejam reprovadas.'),
('acf','jo',3,21,'Mas quem pratica a verdade vem para a luz, a fim de que as suas obras sejam manifestas, porque são feitas em Deus.'),
('acf','jo',3,22,'Depois disto foi Jesus com os seus discípulos para a terra da Judéia; e estava ali com eles, e batizava.'),
('acf','jo',3,23,'Ora, João batizava também em Enom, junto a Salim, porque havia ali muitas águas; e vinham ali, e eram batizados.'),
('acf','jo',3,24,'Porque ainda João não tinha sido lançado na prisão.'),
('acf','jo',3,25,'Houve então uma questão entre os discípulos de João e os judeus acerca da purificação.'),
('acf','jo',3,26,'E foram ter com João, e disseram-lhe: Rabi, aquele que estava contigo além do Jordão, do qual tu deste testemunho, ei-lo batizando, e todos vão ter com ele.'),
('acf','jo',3,27,'João respondeu, e disse: O homem não pode receber coisa alguma, se não lhe for dada do céu.'),
('acf','jo',3,28,'Vós mesmos me sois testemunhas de que disse: Eu não sou o Cristo, mas sou enviado adiante dele.'),
('acf','jo',3,29,'Aquele que tem a esposa é o esposo; mas o amigo do esposo, que lhe assiste e o ouve, alegra-se muito com a voz do esposo. Assim, pois, já este meu gozo está cumprido.'),
('acf','jo',3,30,'É necessário que ele cresça e que eu diminua.'),
('acf','jo',3,31,'Aquele que vem de cima é sobre todos; aquele que vem da terra é da terra e fala da terra. Aquele que vem do céu é sobre todos.'),
('acf','jo',3,32,'E aquilo que ele viu e ouviu isso testifica; e ninguém aceita o seu testemunho.'),
('acf','jo',3,33,'Aquele que aceitou o seu testemunho, esse confirmou que Deus é verdadeiro.'),
('acf','jo',3,34,'Porque aquele que Deus enviou fala as palavras de Deus; pois não lhe dá Deus o Espírito por medida.'),
('acf','jo',3,35,'O Pai ama o Filho, e todas as coisas entregou nas suas mãos.'),
('acf','jo',3,36,'Aquele que crê no Filho tem a vida eterna; mas aquele que não crê no Filho não verá a vida, mas a ira de Deus sobre ele permanece.'),
('acf','jo',4,1,'E quando o Senhor entendeu que os fariseus tinham ouvido que Jesus fazia e batizava mais discípulos do que João'),
('acf','jo',4,2,'(Ainda que Jesus mesmo não batizava, mas os seus discípulos),'),
('acf','jo',4,3,'Deixou a Judéia, e foi outra vez para a Galiléia.'),
('acf','jo',4,4,'E era-lhe necessário passar por Samaria.'),
('acf','jo',4,5,'Foi, pois, a uma cidade de Samaria, chamada Sicar, junto da herdade que Jacó tinha dado a seu filho José.'),
('acf','jo',4,6,'E estava ali a fonte de Jacó. Jesus, pois, cansado do caminho, assentou-se assim junto da fonte. Era isto quase à hora sexta.'),
('acf','jo',4,7,'Veio uma mulher de Samaria tirar água. Disse-lhe Jesus: Dá-me de beber.'),
('acf','jo',4,8,'Porque os seus discípulos tinham ido à cidade comprar comida.'),
('acf','jo',4,9,'Disse-lhe, pois, a mulher samaritana: Como, sendo tu judeu, me pedes de beber a mim, que sou mulher samaritana? (porque os judeus não se comunicam com os samaritanos).'),
('acf','jo',4,10,'Jesus respondeu, e disse-lhe: Se tu conheceras o dom de Deus, e quem é o que te diz: Dá-me de beber, tu lhe pedirias, e ele te daria água viva.'),
('acf','jo',4,11,'Disse-lhe a mulher: Senhor, tu não tens com que a tirar, e o poço é fundo; onde, pois, tens a água viva?'),
('acf','jo',4,12,'És tu maior do que o nosso pai Jacó, que nos deu o poço, bebendo ele próprio dele, e os seus filhos, e o seu gado?'),
('acf','jo',4,13,'Jesus respondeu, e disse-lhe: Qualquer que beber desta água tornará a ter sede;'),
('acf','jo',4,14,'Mas aquele que beber da água que eu lhe der nunca terá sede, porque a água que eu lhe der se fará nele uma fonte de água que salte para a vida eterna.'),
('acf','jo',4,15,'Disse-lhe a mulher: Senhor, dá-me dessa água, para que não mais tenha sede, e não venha aqui tirá-la.'),
('acf','jo',4,16,'Disse-lhe Jesus: Vai, chama o teu marido, e vem cá.'),
('acf','jo',4,17,'A mulher respondeu, e disse: Não tenho marido. Disse-lhe Jesus: Disseste bem: Não tenho marido;'),
('acf','jo',4,18,'Porque tiveste cinco maridos, e o que agora tens não é teu marido; isto disseste com verdade.'),
('acf','jo',4,19,'Disse-lhe a mulher: Senhor, vejo que és profeta.'),
('acf','jo',4,20,'Nossos pais adoraram neste monte, e vós dizeis que é em Jerusalém o lugar onde se deve adorar.'),
('acf','jo',4,21,'Disse-lhe Jesus: Mulher, crê-me que a hora vem, em que nem neste monte nem em Jerusalém adorareis o Pai.'),
('acf','jo',4,22,'Vós adorais o que não sabeis; nós adoramos o que sabemos porque a salvação vem dos judeus.'),
('acf','jo',4,23,'Mas a hora vem, e agora é, em que os verdadeiros adoradores adorarão o Pai em espírito e em verdade; porque o Pai procura a tais que assim o adorem.'),
('acf','jo',4,24,'Deus é Espírito, e importa que os que o adoram o adorem em espírito e em verdade.'),
('acf','jo',4,25,'A mulher disse-lhe: Eu sei que o Messias (que se chama o Cristo) vem; quando ele vier, nos anunciará tudo.'),
('acf','jo',4,26,'Jesus disse-lhe: Eu o sou, eu que falo contigo.'),
('acf','jo',4,27,'E nisto vieram os seus discípulos, e maravilharam-se de que estivesse falando com uma mulher; todavia nenhum lhe disse: Que perguntas? ou: Por que falas com ela?'),
('acf','jo',4,28,'Deixou, pois, a mulher o seu cântaro, e foi à cidade, e disse àqueles homens:'),
('acf','jo',4,29,'Vinde, vede um homem que me disse tudo quanto tenho feito. Porventura não é este o Cristo?'),
('acf','jo',4,30,'Saíram, pois, da cidade, e foram ter com ele.'),
('acf','jo',4,31,'E entretanto os seus discípulos lhe rogaram, dizendo: Rabi, come.'),
('acf','jo',4,32,'Ele, porém, lhes disse: Uma comida tenho para comer, que vós não conheceis.'),
('acf','jo',4,33,'Então os discípulos diziam uns aos outros: Trouxe-lhe, porventura, alguém algo de comer?'),
('acf','jo',4,34,'Jesus disse-lhes: A minha comida é fazer a vontade daquele que me enviou, e realizar a sua obra.'),
('acf','jo',4,35,'Não dizeis vós que ainda há quatro meses até que venha a ceifa? Eis que eu vos digo: Levantai os vossos olhos, e vede as terras, que já estão brancas para a ceifa.'),
('acf','jo',4,36,'E o que ceifa recebe galardão, e ajunta fruto para a vida eterna; para que, assim o que semeia como o que ceifa, ambos se regozijem.'),
('acf','jo',4,37,'Porque nisto é verdadeiro o ditado, que um é o que semeia, e outro o que ceifa.'),
('acf','jo',4,38,'Eu vos enviei a ceifar onde vós não trabalhastes; outros trabalharam, e vós entrastes no seu trabalho.'),
('acf','jo',4,39,'E muitos dos samaritanos daquela cidade creram nele, pela palavra da mulher, que testificou: Disse-me tudo quanto tenho feito.'),
('acf','jo',4,40,'Indo, pois, ter com ele os samaritanos, rogaram-lhe que ficasse com eles; e ficou ali dois dias.'),
('acf','jo',4,41,'E muitos mais creram nele, por causa da sua palavra.'),
('acf','jo',4,42,'E diziam à mulher: Já não é pelo teu dito que nós cremos; porque nós mesmos o temos ouvido, e sabemos que este é verdadeiramente o Cristo, o Salvador do mundo.'),
('acf','jo',4,43,'E dois dias depois partiu dali, e foi para a Galiléia.'),
('acf','jo',4,44,'Porque Jesus mesmo testificou que um profeta não tem honra na sua própria pátria.'),
('acf','jo',4,45,'Chegando, pois, à Galiléia, os galileus o receberam, vistas todas as coisas que fizera em Jerusalém, no dia da festa; porque também eles tinham ido à festa.'),
('acf','jo',4,46,'Segunda vez foi Jesus a Caná da Galiléia, onde da água fizera vinho. E havia ali um nobre, cujo filho estava enfermo em Cafarnaum.'),
('acf','jo',4,47,'Ouvindo este que Jesus vinha da Judéia para a Galiléia, foi ter com ele, e rogou-lhe que descesse, e curasse o seu filho, porque já estava à morte.'),
('acf','jo',4,48,'Então Jesus lhe disse: Se não virdes sinais e milagres, não crereis.'),
('acf','jo',4,49,'Disse-lhe o nobre: Senhor, desce, antes que meu filho morra.'),
('acf','jo',4,50,'Disse-lhe Jesus: Vai, o teu filho vive. E o homem creu na palavra que Jesus lhe disse, e partiu.'),
('acf','jo',4,51,'E descendo ele logo, saíram-lhe ao encontro os seus servos, e lhe anunciaram, dizendo: O teu filho vive.'),
('acf','jo',4,52,'Perguntou-lhes, pois, a que hora se achara melhor. E disseram-lhe: Ontem às sete horas a febre o deixou.'),
('acf','jo',4,53,'Entendeu, pois, o pai que era aquela hora a mesma em que Jesus lhe disse: O teu filho vive; e creu ele, e toda a sua casa.'),
('acf','jo',4,54,'Jesus fez este segundo milagre, quando ia da Judéia para a Galiléia.'),
('acf','jo',5,1,'Depois disto havia uma festa entre os judeus, e Jesus subiu a Jerusalém.'),
('acf','jo',5,2,'Ora, em Jerusalém há, próximo à porta das ovelhas, um tanque, chamado em hebreu Betesda, o qual tem cinco alpendres.'),
('acf','jo',5,3,'Nestes jazia grande multidão de enfermos, cegos, mancos e ressicados, esperando o movimento da água.'),
('acf','jo',5,4,'Porquanto um anjo descia em certo tempo ao tanque, e agitava a água; e o primeiro que ali descia, depois do movimento da água, sarava de qualquer enfermidade que tivesse.'),
('acf','jo',5,5,'E estava ali um homem que, havia trinta e oito anos, se achava enfermo.'),
('acf','jo',5,6,'E Jesus, vendo este deitado, e sabendo que estava neste estado havia muito tempo, disse-lhe: Queres ficar são?'),
('acf','jo',5,7,'O enfermo respondeu-lhe: Senhor, não tenho homem algum que, quando a água é agitada, me ponha no tanque; mas, enquanto eu vou, desce outro antes de mim.'),
('acf','jo',5,8,'Jesus disse-lhe: Levanta-te, toma o teu leito, e anda.'),
('acf','jo',5,9,'Logo aquele homem ficou são; e tomou o seu leito, e andava. E aquele dia era sábado.'),
('acf','jo',5,10,'Então os judeus disseram àquele que tinha sido curado: É sábado, não te é lícito levar o leito.'),
('acf','jo',5,11,'Ele respondeu-lhes: Aquele que me curou, ele próprio disse: Toma o teu leito, e anda.'),
('acf','jo',5,12,'Perguntaram-lhe, pois: Quem é o homem que te disse: Toma o teu leito, e anda?'),
('acf','jo',5,13,'E o que fora curado não sabia quem era; porque Jesus se havia retirado, em razão de naquele lugar haver grande multidão.'),
('acf','jo',5,14,'Depois Jesus encontrou-o no templo, e disse-lhe: Eis que já estás são; não peques mais, para que não te suceda alguma coisa pior.'),
('acf','jo',5,15,'E aquele homem foi, e anunciou aos judeus que Jesus era o que o curara.'),
('acf','jo',5,16,'E por esta causa os judeus perseguiram a Jesus, e procuravam matá-lo, porque fazia estas coisas no sábado.'),
('acf','jo',5,17,'E Jesus lhes respondeu: Meu Pai trabalha até agora, e eu trabalho também.'),
('acf','jo',5,18,'Por isso, pois, os judeus ainda mais procuravam matá-lo, porque não só quebrantava o sábado, mas também dizia que Deus era seu próprio Pai, fazendo-se igual a Deus.'),
('acf','jo',5,19,'Mas Jesus respondeu, e disse-lhes: Na verdade, na verdade vos digo que o Filho por si mesmo não pode fazer coisa alguma, se o não vir fazer o Pai; porque tudo quanto ele faz, o Filho o faz igualmente.'),
('acf','jo',5,20,'Porque o Pai ama o Filho, e mostra-lhe tudo o que faz; e ele lhe mostrará maiores obras do que estas, para que vos maravilheis.'),
('acf','jo',5,21,'Pois, assim como o Pai ressuscita os mortos, e os vivifica, assim também o Filho vivifica aqueles que quer.'),
('acf','jo',5,22,'E também o Pai a ninguém julga, mas deu ao Filho todo o juízo;'),
('acf','jo',5,23,'Para que todos honrem o Filho, como honram o Pai. Quem não honra o Filho, não honra o Pai que o enviou.'),
('acf','jo',5,24,'Na verdade, na verdade vos digo que quem ouve a minha palavra, e crê naquele que me enviou, tem a vida eterna, e não entrará em condenação, mas passou da morte para a vida.'),
('acf','jo',5,25,'Em verdade, em verdade vos digo que vem a hora, e agora é, em que os mortos ouvirão a voz do Filho de Deus, e os que a ouvirem viverão.'),
('acf','jo',5,26,'Porque, como o Pai tem a vida em si mesmo, assim deu também ao Filho ter a vida em si mesmo;'),
('acf','jo',5,27,'E deu-lhe o poder de exercer o juízo, porque é o Filho do homem.'),
('acf','jo',5,28,'Não vos maravilheis disto; porque vem a hora em que todos os que estão nos sepulcros ouvirão a sua voz.'),
('acf','jo',5,29,'E os que fizeram o bem sairão para a ressurreição da vida; e os que fizeram o mal para a ressurreição da condenação.'),
('acf','jo',5,30,'Eu não posso de mim mesmo fazer coisa alguma. Como ouço, assim julgo; e o meu juízo é justo, porque não busco a minha vontade, mas a vontade do Pai que me enviou.'),
('acf','jo',5,31,'Se eu testifico de mim mesmo, o meu testemunho não é verdadeiro.'),
('acf','jo',5,32,'Há outro que testifica de mim, e sei que o testemunho que ele dá de mim é verdadeiro.'),
('acf','jo',5,33,'Vós mandastes mensageiros a João, e ele deu testemunho da verdade.'),
('acf','jo',5,34,'Eu, porém, não recebo testemunho de homem; mas digo isto, para que vos salveis.'),
('acf','jo',5,35,'Ele era a candeia que ardia e alumiava, e vós quisestes alegrar-vos por um pouco de tempo com a sua luz.'),
('acf','jo',5,36,'Mas eu tenho maior testemunho do que o de João; porque as obras que o Pai me deu para realizar, as mesmas obras que eu faço, testificam de mim, que o Pai me enviou.'),
('acf','jo',5,37,'E o Pai, que me enviou, ele mesmo testificou de mim. Vós nunca ouvistes a sua voz, nem vistes o seu parecer.'),
('acf','jo',5,38,'E a sua palavra não permanece em vós, porque naquele que ele enviou não credes vós.'),
('acf','jo',5,39,'Examinais as Escrituras, porque vós cuidais ter nelas a vida eterna, e são elas que de mim testificam;'),
('acf','jo',5,40,'E não quereis vir a mim para terdes vida.'),
('acf','jo',5,41,'Eu não recebo glória dos homens;'),
('acf','jo',5,42,'Mas bem vos conheço, que não tendes em vós o amor de Deus.'),
('acf','jo',5,43,'Eu vim em nome de meu Pai, e não me aceitais; se outro vier em seu próprio nome, a esse aceitareis.'),
('acf','jo',5,44,'Como podeis vós crer, recebendo honra uns dos outros, e não buscando a honra que vem só de Deus?'),
('acf','jo',5,45,'Não cuideis que eu vos hei de acusar para com o Pai. Há um que vos acusa, Moisés, em quem vós esperais.'),
('acf','jo',5,46,'Porque, se vós crêsseis em Moisés, creríeis em mim; porque de mim escreveu ele.'),
('acf','jo',5,47,'Mas, se não credes nos seus escritos, como crereis nas minhas palavras?'),
('acf','jo',6,1,'Depois disto partiu Jesus para o outro lado do mar da Galiléia, que é o de Tiberíades.'),
('acf','jo',6,2,'E grande multidão o seguia, porque via os sinais que operava sobre os enfermos.'),
('acf','jo',6,3,'E Jesus subiu ao monte, e assentou-se ali com os seus discípulos.'),
('acf','jo',6,4,'E a páscoa, a festa dos judeus, estava próxima.'),
('acf','jo',6,5,'Então Jesus, levantando os olhos, e vendo que uma grande multidão vinha ter com ele, disse a Filipe: Onde compraremos pão, para estes comerem?'),
('acf','jo',6,6,'Mas dizia isto para o experimentar; porque ele bem sabia o que havia de fazer.'),
('acf','jo',6,7,'Filipe respondeu-lhe: Duzentos dinheiros de pão não lhes bastarão, para que cada um deles tome um pouco.'),
('acf','jo',6,8,'E um dos seus discípulos, André, irmão de Simão Pedro, disse-lhe:'),
('acf','jo',6,9,'Está aqui um rapaz que tem cinco pães de cevada e dois peixinhos; mas que é isto para tantos?'),
('acf','jo',6,10,'E disse Jesus: Mandai assentar os homens. E havia muita relva naquele lugar. Assentaram-se, pois, os homens em número de quase cinco mil.'),
('acf','jo',6,11,'E Jesus tomou os pães e, havendo dado graças, repartiu-os pelos discípulos, e os discípulos pelos que estavam assentados; e igualmente também dos peixes, quanto eles queriam.'),
('acf','jo',6,12,'E, quando estavam saciados, disse aos seus discípulos: Recolhei os pedaços que sobejaram, para que nada se perca.'),
('acf','jo',6,13,'Recolheram-nos, pois, e encheram doze alcofas de pedaços dos cinco pães de cevada, que sobejaram aos que haviam comido.'),
('acf','jo',6,14,'Vendo, pois, aqueles homens o milagre que Jesus tinha feito, diziam: Este é verdadeiramente o profeta que devia vir ao mundo.'),
('acf','jo',6,15,'Sabendo, pois, Jesus que haviam de vir arrebatá-lo, para o fazerem rei, tornou a retirar-se, ele só, para o monte.'),
('acf','jo',6,16,'E, quando veio a tarde, os seus discípulos desceram para o mar.'),
('acf','jo',6,17,'E, entrando no barco, atravessaram o mar em direção a Cafarnaum; e era já escuro, e ainda Jesus não tinha chegado ao pé deles.'),
('acf','jo',6,18,'E o mar se levantou, porque um grande vento assoprava.'),
('acf','jo',6,19,'E, tendo navegado uns vinte e cinco ou trinta estádios, viram a Jesus, andando sobre o mar e aproximando-se do barco; e temeram.'),
('acf','jo',6,20,'Mas ele lhes disse: Sou eu, não temais.'),
('acf','jo',6,21,'Então eles de boa mente o receberam no barco; e logo o barco chegou à terra para onde iam.'),
('acf','jo',6,22,'No dia seguinte, a multidão que estava do outro lado do mar, vendo que não havia ali mais do que um barquinho, a não ser aquele no qual os discípulos haviam entrado, e que Jesus não entrara com os seus discípulos naquele barquinho, mas que os seus discípulos tinham ido sozinhos'),
('acf','jo',6,23,'(Contudo, outros barquinhos tinham chegado de Tiberíades, perto do lugar onde comeram o pão, havendo o Senhor dado graças).'),
('acf','jo',6,24,'Vendo, pois, a multidão que Jesus não estava ali nem os seus discípulos, entraram eles também nos barcos, e foram a Cafarnaum, em busca de Jesus.'),
('acf','jo',6,25,'E, achando-o no outro lado do mar, disseram-lhe: Rabi, quando chegaste aqui?'),
('acf','jo',6,26,'Jesus respondeu-lhes e disse: Na verdade, na verdade vos digo que me buscais, não pelos sinais que vistes, mas porque comestes do pão e vos saciastes.'),
('acf','jo',6,27,'Trabalhai, não pela comida que perece, mas pela comida que permanece para a vida eterna, a qual o Filho do homem vos dará; porque a este o Pai, Deus, o selou.'),
('acf','jo',6,28,'Disseram-lhe, pois: Que faremos para executarmos as obras de Deus?'),
('acf','jo',6,29,'Jesus respondeu, e disse-lhes: A obra de Deus é esta: Que creiais naquele que ele enviou.'),
('acf','jo',6,30,'Disseram-lhe, pois: Que sinal, pois, fazes tu, para que o vejamos, e creiamos em ti? Que operas tu?'),
('acf','jo',6,31,'Nossos pais comeram o maná no deserto, como está escrito: Deu-lhes a comer o pão do céu.'),
('acf','jo',6,32,'Disse-lhes, pois, Jesus: Na verdade, na verdade vos digo: Moisés não vos deu o pão do céu; mas meu Pai vos dá o verdadeiro pão do céu.'),
('acf','jo',6,33,'Porque o pão de Deus é aquele que desce do céu e dá vida ao mundo.'),
('acf','jo',6,34,'Disseram-lhe, pois: Senhor, dá-nos sempre desse pão.'),
('acf','jo',6,35,'E Jesus lhes disse: Eu sou o pão da vida; aquele que vem a mim não terá fome, e quem crê em mim nunca terá sede.'),
('acf','jo',6,36,'Mas já vos disse que também vós me vistes, e contudo não credes.'),
('acf','jo',6,37,'Todo o que o Pai me dá virá a mim; e o que vem a mim de maneira nenhuma o lançarei fora.'),
('acf','jo',6,38,'Porque eu desci do céu, não para fazer a minha vontade, mas a vontade daquele que me enviou.'),
('acf','jo',6,39,'E a vontade do Pai que me enviou é esta: Que nenhum de todos aqueles que me deu se perca, mas que o ressuscite no último dia.'),
('acf','jo',6,40,'Porquanto a vontade daquele que me enviou é esta: Que todo aquele que vê o Filho, e crê nele, tenha a vida eterna; e eu o ressuscitarei no último dia.'),
('acf','jo',6,41,'Murmuravam, pois, dele os judeus, porque dissera: Eu sou o pão que desceu do céu.'),
('acf','jo',6,42,'E diziam: Não é este Jesus, o filho de José, cujo pai e mãe nós conhecemos? Como, pois, diz ele: Desci do céu?'),
('acf','jo',6,43,'Respondeu, pois, Jesus, e disse-lhes: Não murmureis entre vós.'),
('acf','jo',6,44,'Ninguém pode vir a mim, se o Pai que me enviou o não trouxer; e eu o ressuscitarei no último dia.'),
('acf','jo',6,45,'Está escrito nos profetas: E serão todos ensinados por Deus. Portanto, todo aquele que do Pai ouviu e aprendeu vem a mim.'),
('acf','jo',6,46,'Não que alguém visse ao Pai, a não ser aquele que é de Deus; este tem visto ao Pai.'),
('acf','jo',6,47,'Na verdade, na verdade vos digo que aquele que crê em mim tem a vida eterna.'),
('acf','jo',6,48,'Eu sou o pão da vida.'),
('acf','jo',6,49,'Vossos pais comeram o maná no deserto, e morreram.'),
('acf','jo',6,50,'Este é o pão que desce do céu, para que o que dele comer não morra.'),
('acf','jo',6,51,'Eu sou o pão vivo que desceu do céu; se alguém comer deste pão, viverá para sempre; e o pão que eu der é a minha carne, que eu darei pela vida do mundo.'),
('acf','jo',6,52,'Disputavam, pois, os judeus entre si, dizendo: Como nos pode dar este a sua carne a comer?'),
('acf','jo',6,53,'Jesus, pois, lhes disse: Na verdade, na verdade vos digo que, se não comerdes a carne do Filho do homem, e não beberdes o seu sangue, não tereis vida em vós mesmos.'),
('acf','jo',6,54,'Quem come a minha carne e bebe o meu sangue tem a vida eterna, e eu o ressuscitarei no último dia.'),
('acf','jo',6,55,'Porque a minha carne verdadeiramente é comida, e o meu sangue verdadeiramente é bebida.'),
('acf','jo',6,56,'Quem come a minha carne e bebe o meu sangue permanece em mim e eu nele.'),
('acf','jo',6,57,'Assim como o Pai, que vive, me enviou, e eu vivo pelo Pai, assim, quem de mim se alimenta, também viverá por mim.'),
('acf','jo',6,58,'Este é o pão que desceu do céu; não é o caso de vossos pais, que comeram o maná e morreram; quem comer este pão viverá para sempre.'),
('acf','jo',6,59,'Ele disse estas coisas na sinagoga, ensinando em Cafarnaum.'),
('acf','jo',6,60,'Muitos, pois, dos seus discípulos, ouvindo isto, disseram: Duro é este discurso; quem o pode ouvir?'),
('acf','jo',6,61,'Sabendo, pois, Jesus em si mesmo que os seus discípulos murmuravam disto, disse-lhes: Isto escandaliza-vos?'),
('acf','jo',6,62,'Que seria, pois, se vísseis subir o Filho do homem para onde primeiro estava?'),
('acf','jo',6,63,'O espírito é o que vivifica, a carne para nada aproveita; as palavras que eu vos digo são espírito e vida.'),
('acf','jo',6,64,'Mas há alguns de vós que não crêem. Porque bem sabia Jesus, desde o princípio, quem eram os que não criam, e quem era o que o havia de entregar.'),
('acf','jo',6,65,'E dizia: Por isso eu vos disse que ninguém pode vir a mim, se por meu Pai não lhe for concedido.'),
('acf','jo',6,66,'Desde então muitos dos seus discípulos tornaram para trás, e já não andavam com ele.'),
('acf','jo',6,67,'Então disse Jesus aos doze: Quereis vós também retirar-vos?'),
('acf','jo',6,68,'Respondeu-lhe, pois, Simão Pedro: Senhor, para quem iremos nós? Tu tens as palavras da vida eterna.'),
('acf','jo',6,69,'E nós temos crido e conhecido que tu és o Cristo, o Filho do Deus vivente.'),
('acf','jo',6,70,'Respondeu-lhe Jesus: Não vos escolhi a vós os doze? e um de vós é um diabo.'),
('acf','jo',6,71,'E isto dizia ele de Judas Iscariotes, filho de Simão; porque este o havia de entregar, sendo um dos doze.'),
('acf','jo',7,1,'E depois disto Jesus andava pela Galiléia, e já não queria andar pela Judéia, pois os judeus procuravam matá-lo.'),
('acf','jo',7,2,'E estava próxima a festa dos judeus, a dos tabernáculos.'),
('acf','jo',7,3,'Disseram-lhe, pois, seus irmãos: Sai daqui, e vai para a Judéia, para que também os teus discípulos vejam as obras que fazes.'),
('acf','jo',7,4,'Porque não há ninguém que procure ser conhecido que faça coisa alguma em oculto. Se fazes estas coisas, manifesta-te ao mundo.'),
('acf','jo',7,5,'Porque nem mesmo seus irmãos criam nele.'),
('acf','jo',7,6,'Disse-lhes, pois, Jesus: Ainda não é chegado o meu tempo, mas o vosso tempo sempre está pronto.'),
('acf','jo',7,7,'O mundo não vos pode odiar, mas ele me odeia a mim, porquanto dele testifico que as suas obras são más.'),
('acf','jo',7,8,'Subi vós a esta festa; eu não subo ainda a esta festa, porque ainda o meu tempo não está cumprido.'),
('acf','jo',7,9,'E, havendo-lhes dito isto, ficou na Galiléia.'),
('acf','jo',7,10,'Mas, quando seus irmãos já tinham subido à festa, então subiu ele também, não manifestamente, mas como em oculto.'),
('acf','jo',7,11,'Ora, os judeus procuravam-no na festa, e diziam: Onde está ele?'),
('acf','jo',7,12,'E havia grande murmuração entre a multidão a respeito dele. Diziam alguns: Ele é bom. E outros diziam: Não, antes engana o povo.'),
('acf','jo',7,13,'Todavia ninguém falava dele abertamente, por medo dos judeus.'),
('acf','jo',7,14,'Mas, no meio da festa subiu Jesus ao templo, e ensinava.'),
('acf','jo',7,15,'E os judeus maravilhavam-se, dizendo: Como sabe este letras, não as tendo aprendido?'),
('acf','jo',7,16,'Jesus lhes respondeu, e disse: A minha doutrina não é minha, mas daquele que me enviou.'),
('acf','jo',7,17,'Se alguém quiser fazer a vontade dele, pela mesma doutrina conhecerá se ela é de Deus, ou se eu falo de mim mesmo.'),
('acf','jo',7,18,'Quem fala de si mesmo busca a sua própria glória; mas o que busca a glória daquele que o enviou, esse é verdadeiro, e não há nele injustiça.'),
('acf','jo',7,19,'Não vos deu Moisés a lei? e nenhum de vós observa a lei. Por que procurais matar-me?'),
('acf','jo',7,20,'A multidão respondeu, e disse: Tens demônio; quem procura matar-te?'),
('acf','jo',7,21,'Respondeu Jesus, e disse-lhes: Fiz uma só obra, e todos vos maravilhais.'),
('acf','jo',7,22,'Pelo motivo de que Moisés vos deu a circuncisão (não que fosse de Moisés, mas dos pais), no sábado circuncidais um homem.'),
('acf','jo',7,23,'Se o homem recebe a circuncisão no sábado, para que a lei de Moisés não seja quebrantada, indignais-vos contra mim, porque no sábado curei de todo um homem?'),
('acf','jo',7,24,'Não julgueis segundo a aparência, mas julgai segundo a reta justiça.'),
('acf','jo',7,25,'Então alguns dos de Jerusalém diziam: Não é este o que procuram matar?'),
('acf','jo',7,26,'E ei-lo aí está falando abertamente, e nada lhe dizem. Porventura sabem verdadeiramente os príncipes que de fato este é o Cristo?'),
('acf','jo',7,27,'Todavia bem sabemos de onde este é; mas, quando vier o Cristo, ninguém saberá de onde ele é.'),
('acf','jo',7,28,'Clamava, pois, Jesus no templo, ensinando, e dizendo: Vós conheceis-me, e sabeis de onde sou; e eu não vim de mim mesmo, mas aquele que me enviou é verdadeiro, o qual vós não conheceis.'),
('acf','jo',7,29,'Mas eu conheço-o, porque dele sou e ele me enviou.'),
('acf','jo',7,30,'Procuravam, pois, prendê-lo, mas ninguém lançou mão dele, porque ainda não era chegada a sua hora.'),
('acf','jo',7,31,'E muitos da multidão creram nele, e diziam: Quando o Cristo vier, fará ainda mais sinais do que os que este tem feito?'),
('acf','jo',7,32,'Os fariseus ouviram que a multidão murmurava dele estas coisas; e os fariseus e os principais dos sacerdotes mandaram servidores para o prenderem.'),
('acf','jo',7,33,'Disse-lhes, pois, Jesus: Ainda um pouco de tempo estou convosco, e depois vou para aquele que me enviou.'),
('acf','jo',7,34,'Vós me buscareis, e não me achareis; e onde eu estou, vós não podeis vir.'),
('acf','jo',7,35,'Disseram, pois, os judeus uns para os outros: Para onde irá este, que o não acharemos? Irá porventura para os dispersos entre os gregos, e ensinará os gregos?'),
('acf','jo',7,36,'Que palavra é esta que disse: Buscar-me-eis, e não me achareis; e: Aonde eu estou vós não podeis ir?'),
('acf','jo',7,37,'E no último dia, o grande dia da festa, Jesus pôs-se em pé, e clamou, dizendo: Se alguém tem sede, venha a mim, e beba.'),
('acf','jo',7,38,'Quem crê em mim, como diz a Escritura, rios de água viva correrão do seu ventre.'),
('acf','jo',7,39,'E isto disse ele do Espírito que haviam de receber os que nele cressem; porque o Espírito Santo ainda não fora dado, por ainda Jesus não ter sido glorificado.'),
('acf','jo',7,40,'Então muitos da multidão, ouvindo esta palavra, diziam: Verdadeiramente este é o Profeta.'),
('acf','jo',7,41,'Outros diziam: Este é o Cristo; mas diziam outros: Vem, pois, o Cristo da Galiléia?'),
('acf','jo',7,42,'Não diz a Escritura que o Cristo vem da descendência de Davi, e de Belém, da aldeia de onde era Davi?'),
('acf','jo',7,43,'Assim entre o povo havia dissensão por causa dele.'),
('acf','jo',7,44,'E alguns deles queriam prendê-lo, mas ninguém lançou mão dele.'),
('acf','jo',7,45,'E os servidores foram ter com os principais dos sacerdotes e fariseus; e eles lhes perguntaram: Por que não o trouxestes?'),
('acf','jo',7,46,'Responderam os servidores: Nunca homem algum falou assim como este homem.'),
('acf','jo',7,47,'Responderam-lhes, pois, os fariseus: Também vós fostes enganados?'),
('acf','jo',7,48,'Creu nele porventura algum dos principais ou dos fariseus?'),
('acf','jo',7,49,'Mas esta multidão, que não sabe a lei, é maldita.'),
('acf','jo',7,50,'Nicodemos, que era um deles (o que de noite fora ter com Jesus), disse-lhes:'),
('acf','jo',7,51,'Porventura condena a nossa lei um homem sem primeiro o ouvir e ter conhecimento do que faz?'),
('acf','jo',7,52,'Responderam eles, e disseram-lhe: És tu também da Galiléia? Examina, e verás que da Galiléia nenhum profeta surgiu.'),
('acf','jo',7,53,'E cada um foi para sua casa.'),
('acf','jo',8,1,'Jesus, porém, foi para o Monte das Oliveiras.'),
('acf','jo',8,2,'E pela manhã cedo tornou para o templo, e todo o povo vinha ter com ele, e, assentando-se, os ensinava.'),
('acf','jo',8,3,'E os escribas e fariseus trouxeram-lhe uma mulher apanhada em adultério;'),
('acf','jo',8,4,'E, pondo-a no meio, disseram-lhe: Mestre, esta mulher foi apanhada, no próprio ato, adulterando.'),
('acf','jo',8,5,'E na lei nos mandou Moisés que as tais sejam apedrejadas. Tu, pois, que dizes?'),
('acf','jo',8,6,'Isto diziam eles, tentando-o, para que tivessem de que o acusar. Mas Jesus, inclinando-se, escrevia com o dedo na terra.'),
('acf','jo',8,7,'E, como insistissem, perguntando-lhe, endireitou-se, e disse-lhes: Aquele que de entre vós está sem pecado seja o primeiro que atire pedra contra ela.'),
('acf','jo',8,8,'E, tornando a inclinar-se, escrevia na terra.'),
('acf','jo',8,9,'Quando ouviram isto, redargüidos da consciência, saíram um a um, a começar pelos mais velhos até aos últimos; ficou só Jesus e a mulher que estava no meio.'),
('acf','jo',8,10,'E, endireitando-se Jesus, e não vendo ninguém mais do que a mulher, disse-lhe: Mulher, onde estão aqueles teus acusadores? Ninguém te condenou?'),
('acf','jo',8,11,'E ela disse: Ninguém, Senhor. E disse-lhe Jesus: Nem eu também te condeno; vai-te, e não peques mais.'),
('acf','jo',8,12,'Falou-lhes, pois, Jesus outra vez, dizendo: Eu sou a luz do mundo; quem me segue não andará em trevas, mas terá a luz da vida.'),
('acf','jo',8,13,'Disseram-lhe, pois, os fariseus: Tu testificas de ti mesmo; o teu testemunho não é verdadeiro.'),
('acf','jo',8,14,'Respondeu Jesus, e disse-lhes: Ainda que eu testifico de mim mesmo, o meu testemunho é verdadeiro, porque sei de onde vim, e para onde vou; mas vós não sabeis de onde venho, nem para onde vou.'),
('acf','jo',8,15,'Vós julgais segundo a carne; eu a ninguém julgo.'),
('acf','jo',8,16,'E, se na verdade julgo, o meu juízo é verdadeiro, porque não sou eu só, mas eu e o Pai que me enviou.'),
('acf','jo',8,17,'E na vossa lei está também escrito que o testemunho de dois homens é verdadeiro.'),
('acf','jo',8,18,'Eu sou o que testifico de mim mesmo, e de mim testifica também o Pai que me enviou.'),
('acf','jo',8,19,'Disseram-lhe, pois: Onde está teu Pai? Jesus respondeu: Não me conheceis a mim, nem a meu Pai; se vós me conhecêsseis a mim, também conheceríeis a meu Pai.'),
('acf','jo',8,20,'Estas palavras disse Jesus no lugar do tesouro, ensinando no templo, e ninguém o prendeu, porque ainda não era chegada a sua hora.'),
('acf','jo',8,21,'Disse-lhes, pois, Jesus outra vez: Eu retiro-me, e buscar-me-eis, e morrereis no vosso pecado. Para onde eu vou, não podeis vós vir.'),
('acf','jo',8,22,'Diziam, pois, os judeus: Porventura quererá matar-se a si mesmo, pois diz: Para onde eu vou não podeis vir?'),
('acf','jo',8,23,'E dizia-lhes: Vós sois de baixo, eu sou de cima; vós sois deste mundo, eu não sou deste mundo.'),
('acf','jo',8,24,'Por isso vos disse que morrereis em vossos pecados, porque se não crerdes que eu sou, morrereis em vossos pecados.'),
('acf','jo',8,25,'Disseram-lhe, pois: Quem és tu? Jesus lhes disse: Isso mesmo que já desde o princípio vos disse.'),
('acf','jo',8,26,'Muito tenho que dizer e julgar de vós, mas aquele que me enviou é verdadeiro; e o que dele tenho ouvido, isso falo ao mundo.'),
('acf','jo',8,27,'Mas não entenderam que ele lhes falava do Pai.'),
('acf','jo',8,28,'Disse-lhes, pois, Jesus: Quando levantardes o Filho do homem, então conhecereis que EU SOU, e que nada faço por mim mesmo; mas isto falo como meu Pai me ensinou.'),
('acf','jo',8,29,'E aquele que me enviou está comigo. O Pai não me tem deixado só, porque eu faço sempre o que lhe agrada.'),
('acf','jo',8,30,'Dizendo ele estas coisas, muitos creram nele.'),
('acf','jo',8,31,'Jesus dizia, pois, aos judeus que criam nele: Se vós permanecerdes na minha palavra, verdadeiramente sereis meus discípulos;'),
('acf','jo',8,32,'E conhecereis a verdade, e a verdade vos libertará.'),
('acf','jo',8,33,'Responderam-lhe: Somos descendência de Abraão, e nunca servimos a ninguém; como dizes tu: Sereis livres?'),
('acf','jo',8,34,'Respondeu-lhes Jesus: Em verdade, em verdade vos digo que todo aquele que comete pecado é servo do pecado.'),
('acf','jo',8,35,'Ora o servo não fica para sempre em casa; o Filho fica para sempre.'),
('acf','jo',8,36,'Se, pois, o Filho vos libertar, verdadeiramente sereis livres.'),
('acf','jo',8,37,'Bem sei que sois descendência de Abraão; contudo, procurais matar-me, porque a minha palavra não entra em vós.'),
('acf','jo',8,38,'Eu falo do que vi junto de meu Pai, e vós fazeis o que também vistes junto de vosso pai.'),
('acf','jo',8,39,'Responderam, e disseram-lhe: Nosso pai é Abraão. Jesus disse-lhes: Se fôsseis filhos de Abraão, faríeis as obras de Abraão.'),
('acf','jo',8,40,'Mas agora procurais matar-me, a mim, homem que vos tem dito a verdade que de Deus tem ouvido; Abraão não fez isto.'),
('acf','jo',8,41,'Vós fazeis as obras de vosso pai. Disseram-lhe, pois: Nós não somos nascidos de fornicação; temos um Pai, que é Deus.'),
('acf','jo',8,42,'Disse-lhes, pois, Jesus: Se Deus fosse o vosso Pai, certamente me amaríeis, pois que eu saí, e vim de Deus; não vim de mim mesmo, mas ele me enviou.'),
('acf','jo',8,43,'Por que não entendeis a minha linguagem? Por não poderdes ouvir a minha palavra.'),
('acf','jo',8,44,'Vós tendes por pai ao diabo, e quereis satisfazer os desejos de vosso pai. Ele foi homicida desde o princípio, e não se firmou na verdade, porque não há verdade nele. Quando ele profere mentira, fala do que lhe é próprio, porque é mentiroso, e pai da mentira.'),
('acf','jo',8,45,'Mas, porque vos digo a verdade, não me credes.'),
('acf','jo',8,46,'Quem dentre vós me convence de pecado? E se vos digo a verdade, por que não credes?'),
('acf','jo',8,47,'Quem é de Deus escuta as palavras de Deus; por isso vós não as escutais, porque não sois de Deus.'),
('acf','jo',8,48,'Responderam, pois, os judeus, e disseram-lhe: Não dizemos nós bem que és samaritano, e que tens demônio?'),
('acf','jo',8,49,'Jesus respondeu: Eu não tenho demônio, antes honro a meu Pai, e vós me desonrais.'),
('acf','jo',8,50,'Eu não busco a minha glória; há quem a busque, e julgue.'),
('acf','jo',8,51,'Em verdade, em verdade vos digo que, se alguém guardar a minha palavra, nunca verá a morte.'),
('acf','jo',8,52,'Disseram-lhe, pois, os judeus: Agora conhecemos que tens demônio. Morreu Abraão e os profetas; e tu dizes: Se alguém guardar a minha palavra, nunca provará a morte.'),
('acf','jo',8,53,'És tu maior do que o nosso pai Abraão, que morreu? E também os profetas morreram. Quem te fazes tu ser?'),
('acf','jo',8,54,'Jesus respondeu: Se eu me glorifico a mim mesmo, a minha glória não é nada; quem me glorifica é meu Pai, o qual dizeis que é vosso Deus.'),
('acf','jo',8,55,'E vós não o conheceis, mas eu conheço-o. E, se disser que o não conheço, serei mentiroso como vós; mas conheço-o e guardo a sua palavra.'),
('acf','jo',8,56,'Abraão, vosso pai, exultou por ver o meu dia, e viu-o, e alegrou-se.'),
('acf','jo',8,57,'Disseram-lhe, pois, os judeus: Ainda não tens cinqüenta anos, e viste Abraão?'),
('acf','jo',8,58,'Disse-lhes Jesus: Em verdade, em verdade vos digo que antes que Abraão existisse, eu sou.'),
('acf','jo',8,59,'Então pegaram em pedras para lhe atirarem; mas Jesus ocultou-se, e saiu do templo, passando pelo meio deles, e assim se retirou.'),
('acf','jo',9,1,'E, passando Jesus, viu um homem cego de nascença.'),
('acf','jo',9,2,'E os seus discípulos lhe perguntaram, dizendo: Rabi, quem pecou, este ou seus pais, para que nascesse cego?'),
('acf','jo',9,3,'Jesus respondeu: Nem ele pecou nem seus pais; mas foi assim para que se manifestem nele as obras de Deus.'),
('acf','jo',9,4,'Convém que eu faça as obras daquele que me enviou, enquanto é dia; a noite vem, quando ninguém pode trabalhar.'),
('acf','jo',9,5,'Enquanto estou no mundo, sou a luz do mundo.'),
('acf','jo',9,6,'Tendo dito isto, cuspiu na terra, e com a saliva fez lodo, e untou com o lodo os olhos do cego.'),
('acf','jo',9,7,'E disse-lhe: Vai, lava-te no tanque de Siloé (que significa o Enviado). Foi, pois, e lavou-se, e voltou vendo.'),
('acf','jo',9,8,'Então os vizinhos, e aqueles que dantes tinham visto que era cego, diziam: Não é este aquele que estava assentado e mendigava?'),
('acf','jo',9,9,'Uns diziam: É este. E outros: Parece-se com ele. Ele dizia: Sou eu.'),
('acf','jo',9,10,'Diziam-lhe, pois: Como se te abriram os olhos?'),
('acf','jo',9,11,'Ele respondeu, e disse: O homem, chamado Jesus, fez lodo, e untou-me os olhos, e disse-me: Vai ao tanque de Siloé, e lava-te. Então fui, e lavei-me, e vi.'),
('acf','jo',9,12,'Disseram-lhe, pois: Onde está ele? Respondeu: Não sei.'),
('acf','jo',9,13,'Levaram, pois, aos fariseus o que dantes era cego.'),
('acf','jo',9,14,'E era sábado quando Jesus fez o lodo e lhe abriu os olhos.'),
('acf','jo',9,15,'Tornaram, pois, também os fariseus a perguntar-lhe como vira, e ele lhes disse: Pôs-me lodo sobre os olhos, lavei-me, e vejo.'),
('acf','jo',9,16,'Então alguns dos fariseus diziam: Este homem não é de Deus, pois não guarda o sábado. Diziam outros: Como pode um homem pecador fazer tais sinais? E havia dissensão entre eles.'),
('acf','jo',9,17,'Tornaram, pois, a dizer ao cego: Tu, que dizes daquele que te abriu os olhos? E ele respondeu: Que é profeta.'),
('acf','jo',9,18,'Os judeus, porém, não creram que ele tivesse sido cego, e que agora visse, enquanto não chamaram os pais do que agora via.'),
('acf','jo',9,19,'E perguntaram-lhes, dizendo: É este o vosso filho, que vós dizeis ter nascido cego? Como, pois, vê agora?'),
('acf','jo',9,20,'Seus pais lhes responderam, e disseram: Sabemos que este é o nosso filho, e que nasceu cego;'),
('acf','jo',9,21,'Mas como agora vê, não sabemos; ou quem lhe tenha aberto os olhos, não sabemos. Tem idade, perguntai-lho a ele mesmo; e ele falará por si mesmo.'),
('acf','jo',9,22,'Seus pais disseram isto, porque temiam os judeus. Porquanto já os judeus tinham resolvido que, se alguém confessasse ser ele o Cristo, fosse expulso da sinagoga.'),
('acf','jo',9,23,'Por isso é que seus pais disseram: Tem idade, perguntai-lho a ele mesmo.'),
('acf','jo',9,24,'Chamaram, pois, pela segunda vez o homem que tinha sido cego, e disseram-lhe: Dá glória a Deus; nós sabemos que esse homem é pecador.'),
('acf','jo',9,25,'Respondeu ele pois, e disse: Se é pecador, não sei; uma coisa sei, é que, havendo eu sido cego, agora vejo.'),
('acf','jo',9,26,'E tornaram a dizer-lhe: Que te fez ele? Como te abriu os olhos?'),
('acf','jo',9,27,'Respondeu-lhes: Já vo-lo disse, e não ouvistes; para que o quereis tornar a ouvir? Quereis vós porventura fazer-vos também seus discípulos?'),
('acf','jo',9,28,'Então o injuriaram, e disseram: Discípulo dele sejas tu; nós, porém, somos discípulos de Moisés.'),
('acf','jo',9,29,'Nós bem sabemos que Deus falou a Moisés, mas este não sabemos de onde é.'),
('acf','jo',9,30,'O homem respondeu, e disse-lhes: Nisto, pois, está a maravilha, que vós não saibais de onde ele é, e contudo me abrisse os olhos.'),
('acf','jo',9,31,'Ora, nós sabemos que Deus não ouve a pecadores; mas, se alguém é temente a Deus, e faz a sua vontade, a esse ouve.'),
('acf','jo',9,32,'Desde o princípio do mundo nunca se ouviu que alguém abrisse os olhos a um cego de nascença.'),
('acf','jo',9,33,'Se este não fosse de Deus, nada poderia fazer.'),
('acf','jo',9,34,'Responderam eles, e disseram-lhe: Tu és nascido todo em pecados, e nos ensinas a nós? E expulsaram-no.'),
('acf','jo',9,35,'Jesus ouviu que o tinham expulsado e, encontrando-o, disse-lhe: Crês tu no Filho de Deus?'),
('acf','jo',9,36,'Ele respondeu, e disse: Quem é ele, Senhor, para que nele creia?'),
('acf','jo',9,37,'E Jesus lhe disse: Tu já o tens visto, e é aquele que fala contigo.'),
('acf','jo',9,38,'Ele disse: Creio, Senhor. E o adorou.'),
('acf','jo',9,39,'E disse-lhe Jesus: Eu vim a este mundo para juízo, a fim de que os que não vêem vejam, e os que vêem sejam cegos.'),
('acf','jo',9,40,'E aqueles dos fariseus, que estavam com ele, ouvindo isto, disseram-lhe: Também nós somos cegos?'),
('acf','jo',9,41,'Disse-lhes Jesus: Se fôsseis cegos, não teríeis pecado; mas como agora dizeis: Vemos; por isso o vosso pecado permanece.'),
('acf','jo',10,1,'Na verdade, na verdade vos digo que aquele que não entra pela porta no curral das ovelhas, mas sobe por outra parte, é ladrão e salteador.'),
('acf','jo',10,2,'Aquele, porém, que entra pela porta é o pastor das ovelhas.'),
('acf','jo',10,3,'A este o porteiro abre, e as ovelhas ouvem a sua voz, e chama pelo nome às suas ovelhas, e as traz para fora.'),
('acf','jo',10,4,'E, quando tira para fora as suas ovelhas, vai adiante delas, e as ovelhas o seguem, porque conhecem a sua voz.'),
('acf','jo',10,5,'Mas de modo nenhum seguirão o estranho, antes fugirão dele, porque não conhecem a voz dos estranhos.'),
('acf','jo',10,6,'Jesus disse-lhes esta parábola; mas eles não entenderam o que era que lhes dizia.'),
('acf','jo',10,7,'Tornou, pois, Jesus a dizer-lhes: Em verdade, em verdade vos digo que eu sou a porta das ovelhas.'),
('acf','jo',10,8,'Todos quantos vieram antes de mim são ladrões e salteadores; mas as ovelhas não os ouviram.'),
('acf','jo',10,9,'Eu sou a porta; se alguém entrar por mim, salvar-se-á, e entrará, e sairá, e achará pastagens.'),
('acf','jo',10,10,'O ladrão não vem senão a roubar, a matar, e a destruir; eu vim para que tenham vida, e a tenham com abundância.'),
('acf','jo',10,11,'Eu sou o bom Pastor; o bom Pastor dá a sua vida pelas ovelhas.'),
('acf','jo',10,12,'Mas o mercenário, e o que não é pastor, de quem não são as ovelhas, vê vir o lobo, e deixa as ovelhas, e foge; e o lobo as arrebata e dispersa as ovelhas.'),
('acf','jo',10,13,'Ora, o mercenário foge, porque é mercenário, e não tem cuidado das ovelhas.'),
('acf','jo',10,14,'Eu sou o bom Pastor, e conheço as minhas ovelhas, e das minhas sou conhecido.'),
('acf','jo',10,15,'Assim como o Pai me conhece a mim, também eu conheço o Pai, e dou a minha vida pelas ovelhas.'),
('acf','jo',10,16,'Ainda tenho outras ovelhas que não são deste aprisco; também me convém agregar estas, e elas ouvirão a minha voz, e haverá um rebanho e um Pastor.'),
('acf','jo',10,17,'Por isto o Pai me ama, porque dou a minha vida para tornar a tomá-la.'),
('acf','jo',10,18,'Ninguém ma tira de mim, mas eu de mim mesmo a dou; tenho poder para a dar, e poder para tornar a tomá-la. Este mandamento recebi de meu Pai.'),
('acf','jo',10,19,'Tornou, pois, a haver divisão entre os judeus por causa destas palavras.'),
('acf','jo',10,20,'E muitos deles diziam: Tem demônio, e está fora de si; por que o ouvis?'),
('acf','jo',10,21,'Diziam outros: Estas palavras não são de endemoninhado. Pode, porventura, um demônio abrir os olhos aos cegos?'),
('acf','jo',10,22,'E em Jerusalém havia a festa da dedicação, e era inverno.'),
('acf','jo',10,23,'E Jesus andava passeando no templo, no alpendre de Salomão.'),
('acf','jo',10,24,'Rodearam-no, pois, os judeus, e disseram-lhe: Até quando terás a nossa alma suspensa? Se tu és o Cristo, dize-no-lo abertamente.'),
('acf','jo',10,25,'Respondeu-lhes Jesus: Já vo-lo tenho dito, e não o credes. As obras que eu faço, em nome de meu Pai, essas testificam de mim.'),
('acf','jo',10,26,'Mas vós não credes porque não sois das minhas ovelhas, como já vo-lo tenho dito.'),
('acf','jo',10,27,'As minhas ovelhas ouvem a minha voz, e eu conheço-as, e elas me seguem;'),
('acf','jo',10,28,'E dou-lhes a vida eterna, e nunca hão de perecer, e ninguém as arrebatará da minha mão.'),
('acf','jo',10,29,'Meu Pai, que mas deu, é maior do que todos; e ninguém pode arrebatá-las da mão de meu Pai.'),
('acf','jo',10,30,'Eu e o Pai somos um.'),
('acf','jo',10,31,'Os judeus pegaram então outra vez em pedras para o apedrejar.'),
('acf','jo',10,32,'Respondeu-lhes Jesus: Tenho-vos mostrado muitas obras boas procedentes de meu Pai; por qual destas obras me apedrejais?'),
('acf','jo',10,33,'Os judeus responderam, dizendo-lhe: Não te apedrejamos por alguma obra boa, mas pela blasfêmia; porque, sendo tu homem, te fazes Deus a ti mesmo.'),
('acf','jo',10,34,'Respondeu-lhes Jesus: Não está escrito na vossa lei: Eu disse: Sois deuses?'),
('acf','jo',10,35,'Pois, se a lei chamou deuses àqueles a quem a palavra de Deus foi dirigida, e a Escritura não pode ser anulada,'),
('acf','jo',10,36,'«quele a quem o Pai santificou, e enviou ao mundo, vós dizeis: Blasfemas, porque disse: Sou Filho de Deus?'),
('acf','jo',10,37,'Se não faço as obras de meu Pai, não me acrediteis.'),
('acf','jo',10,38,'Mas, se as faço, e não credes em mim, crede nas obras; para que conheçais e acrediteis que o Pai está em mim e eu nele.'),
('acf','jo',10,39,'Procuravam, pois, prendê-lo outra vez, mas ele escapou-se de suas mãos,'),
('acf','jo',10,40,'E retirou-se outra vez para além do Jordão, para o lugar onde João tinha primeiramente batizado; e ali ficou.'),
('acf','jo',10,41,'E muitos iam ter com ele, e diziam: Na verdade João não fez sinal algum, mas tudo quanto João disse deste era verdade.'),
('acf','jo',10,42,'E muitos ali creram nele.'),
('acf','jo',11,1,'Estava, porém, enfermo um certo Lázaro, de betânia, aldeia de Maria e de sua irmã Marta.'),
('acf','jo',11,2,'E Maria era aquela que tinha ungido o Senhor com ungüento, e lhe tinha enxugado os pés com os seus cabelos, cujo irmão Lázaro estava enfermo.'),
('acf','jo',11,3,'Mandaram-lhe, pois, suas irmãs dizer: Senhor, eis que está enfermo aquele que tu amas.'),
('acf','jo',11,4,'E Jesus, ouvindo isto, disse: Esta enfermidade não é para morte, mas para glória de Deus, para que o Filho de Deus seja glorificado por ela.'),
('acf','jo',11,5,'Ora, Jesus amava a Marta, e a sua irmã, e a Lázaro.'),
('acf','jo',11,6,'Ouvindo, pois, que estava enfermo, ficou ainda dois dias no lugar onde estava.'),
('acf','jo',11,7,'Depois disto, disse aos seus discípulos: Vamos outra vez para a Judéia.'),
('acf','jo',11,8,'Disseram-lhe os discípulos: Rabi, ainda agora os judeus procuravam apedrejar-te, e tornas para lá?'),
('acf','jo',11,9,'Jesus respondeu: Não há doze horas no dia? Se alguém andar de dia, não tropeça, porque vê a luz deste mundo;'),
('acf','jo',11,10,'Mas, se andar de noite, tropeça, porque nele não há luz.'),
('acf','jo',11,11,'Assim falou; e depois disse-lhes: Lázaro, o nosso amigo, dorme, mas vou despertá-lo do sono.'),
('acf','jo',11,12,'Disseram, pois, os seus discípulos: Senhor, se dorme, estará salvo.'),
('acf','jo',11,13,'Mas Jesus dizia isto da sua morte; eles, porém, cuidavam que falava do repouso do sono.'),
('acf','jo',11,14,'Então Jesus disse-lhes claramente: Lázaro está morto;'),
('acf','jo',11,15,'E folgo, por amor de vós, de que eu lá não estivesse, para que acrediteis; mas vamos ter com ele.'),
('acf','jo',11,16,'Disse, pois, Tomé, chamado Dídimo, aos condiscípulos: Vamos nós também, para morrermos com ele.'),
('acf','jo',11,17,'Chegando, pois, Jesus, achou que já havia quatro dias que estava na sepultura.'),
('acf','jo',11,18,'(Ora Betânia distava de Jerusalém quase quinze estádios. )'),
('acf','jo',11,19,'E muitos dos judeus tinham ido consolar a Marta e a Maria, acerca de seu irmão.'),
('acf','jo',11,20,'Ouvindo, pois, Marta que Jesus vinha, saiu-lhe ao encontro; Maria, porém, ficou assentada em casa.'),
('acf','jo',11,21,'Disse, pois, Marta a Jesus: Senhor, se tu estivesses aqui, meu irmão não teria morrido.'),
('acf','jo',11,22,'Mas também agora sei que tudo quanto pedires a Deus, Deus to concederá.'),
('acf','jo',11,23,'Disse-lhe Jesus: Teu irmão há de ressuscitar.'),
('acf','jo',11,24,'Disse-lhe Marta: Eu sei que há de ressuscitar na ressurreição do último dia.'),
('acf','jo',11,25,'Disse-lhe Jesus: Eu sou a ressurreição e a vida; quem crê em mim, ainda que esteja morto, viverá;'),
('acf','jo',11,26,'E todo aquele que vive, e crê em mim, nunca morrerá. Crês tu isto?'),
('acf','jo',11,27,'Disse-lhe ela: Sim, Senhor, creio que tu és o Cristo, o Filho de Deus, que havia de vir ao mundo.'),
('acf','jo',11,28,'E, dito isto, partiu, e chamou em segredo a Maria, sua irmã, dizendo: O Mestre está cá, e chama-te.'),
('acf','jo',11,29,'Ela, ouvindo isto, levantou-se logo, e foi ter com ele.'),
('acf','jo',11,30,'(Pois, Jesus ainda não tinha chegado à aldeia, mas estava no lugar onde Marta o encontrara.)'),
('acf','jo',11,31,'Vendo, pois, os judeus, que estavam com ela em casa e a consolavam, que Maria apressadamente se levantara e saíra, seguiram-na, dizendo: Vai ao sepulcro para chorar ali.'),
('acf','jo',11,32,'Tendo, pois, Maria chegado aonde Jesus estava, e vendo-o, lançou-se aos seus pés, dizendo-lhe: Senhor, se tu estivesses aqui, meu irmão não teria morrido.'),
('acf','jo',11,33,'Jesus pois, quando a viu chorar, e também chorando os judeus que com ela vinham, moveu-se muito em espírito, e perturbou-se.'),
('acf','jo',11,34,'E disse: Onde o pusestes? Disseram-lhe: Senhor, vem, e vê.'),
('acf','jo',11,35,'Jesus chorou.'),
('acf','jo',11,36,'Disseram, pois, os judeus: Vede como o amava.'),
('acf','jo',11,37,'E alguns deles disseram: Não podia ele, que abriu os olhos ao cego, fazer também com que este não morresse?'),
('acf','jo',11,38,'Jesus, pois, movendo-se outra vez muito em si mesmo, veio ao sepulcro; e era uma caverna, e tinha uma pedra posta sobre ela.'),
('acf','jo',11,39,'Disse Jesus: Tirai a pedra. Marta, irmã do defunto, disse-lhe: Senhor, já cheira mal, porque é já de quatro dias.'),
('acf','jo',11,40,'Disse-lhe Jesus: Não te hei dito que, se creres, verás a glória de Deus?'),
('acf','jo',11,41,'Tiraram, pois, a pedra de onde o defunto jazia. E Jesus, levantando os olhos para cima, disse: Pai, graças te dou, por me haveres ouvido.'),
('acf','jo',11,42,'Eu bem sei que sempre me ouves, mas eu disse isto por causa da multidão que está em redor, para que creiam que tu me enviaste.'),
('acf','jo',11,43,'E, tendo dito isto, clamou com grande voz: Lázaro, sai para fora.'),
('acf','jo',11,44,'E o defunto saiu, tendo as mãos e os pés ligados com faixas, e o seu rosto envolto num lenço. Disse-lhes Jesus: Desligai-o, e deixai-o ir.'),
('acf','jo',11,45,'Muitos, pois, dentre os judeus que tinham vindo a Maria, e que tinham visto o que Jesus fizera, creram nele.'),
('acf','jo',11,46,'Mas alguns deles foram ter com os fariseus, e disseram-lhes o que Jesus tinha feito.'),
('acf','jo',11,47,'Depois os principais dos sacerdotes e os fariseus formaram conselho, e diziam: Que faremos? porquanto este homem faz muitos sinais.'),
('acf','jo',11,48,'Se o deixamos assim, todos crerão nele, e virão os romanos, e tirar-nos-ão o nosso lugar e a nação.'),
('acf','jo',11,49,'E Caifás, um deles que era sumo sacerdote naquele ano, lhes disse: Vós nada sabeis,'),
('acf','jo',11,50,'Nem considerais que nos convém que um homem morra pelo povo, e que não pereça toda a nação.'),
('acf','jo',11,51,'Ora ele não disse isto de si mesmo, mas, sendo o sumo sacerdote naquele ano, profetizou que Jesus devia morrer pela nação.'),
('acf','jo',11,52,'E não somente pela nação, mas também para reunir em um corpo os filhos de Deus que andavam dispersos.'),
('acf','jo',11,53,'Desde aquele dia, pois, consultavam-se para o matarem.'),
('acf','jo',11,54,'Jesus, pois, já não andava manifestamente entre os judeus, mas retirou-se dali para a terra junto do deserto, para uma cidade chamada Efraim; e ali ficou com os seus discípulos.'),
('acf','jo',11,55,'E estava próxima a páscoa dos judeus, e muitos daquela região subiram a Jerusalém antes da páscoa para se purificarem.'),
('acf','jo',11,56,'Buscavam, pois, a Jesus, e diziam uns aos outros, estando no templo: Que vos parece? Não virá à festa?'),
('acf','jo',11,57,'Ora, os principais dos sacerdotes e os fariseus tinham dado ordem para que, se alguém soubesse onde ele estava, o denunciasse, para o prenderem.'),
('acf','jo',12,1,'Foi, pois, Jesus seis dias antes da páscoa a betânia, onde estava Lázaro, o que falecera, e a quem ressuscitara dentre os mortos.'),
('acf','jo',12,2,'Fizeram-lhe, pois, ali uma ceia, e Marta servia, e Lázaro era um dos que estavam à mesa com ele.'),
('acf','jo',12,3,'Então Maria, tomando um arrátel de ungüento de nardo puro, de muito preço, ungiu os pés de Jesus, e enxugou-lhe os pés com os seus cabelos; e encheu-se a casa do cheiro do ungüento.'),
('acf','jo',12,4,'Então, um dos seus discípulos, Judas Iscariotes, filho de Simão, o que havia de traí-lo, disse:'),
('acf','jo',12,5,'Por que não se vendeu este ungüento por trezentos dinheiros e não se deu aos pobres?'),
('acf','jo',12,6,'Ora, ele disse isto, não pelo cuidado que tivesse dos pobres, mas porque era ladrão e tinha a bolsa, e tirava o que ali se lançava.'),
('acf','jo',12,7,'Disse, pois, Jesus: Deixai-a; para o dia da minha sepultura guardou isto;'),
('acf','jo',12,8,'Porque os pobres sempre os tendes convosco, mas a mim nem sempre me tendes.'),
('acf','jo',12,9,'E muita gente dos judeus soube que ele estava ali; e foram, não só por causa de Jesus, mas também para ver a Lázaro, a quem ressuscitara dentre os mortos.'),
('acf','jo',12,10,'E os principais dos sacerdotes tomaram deliberação para matar também a Lázaro;'),
('acf','jo',12,11,'Porque muitos dos judeus, por causa dele, iam e criam em Jesus.'),
('acf','jo',12,12,'No dia seguinte, ouvindo uma grande multidão, que viera à festa, que Jesus vinha a Jerusalém,'),
('acf','jo',12,13,'Tomaram ramos de palmeiras, e saíram-lhe ao encontro, e clamavam: Hosana! Bendito o Rei de Israel que vem em nome do Senhor.'),
('acf','jo',12,14,'E achou Jesus um jumentinho, e assentou-se sobre ele, como está escrito:'),
('acf','jo',12,15,'Não temas, ó filha de Sião; eis que o teu Rei vem assentado sobre o filho de uma jumenta.'),
('acf','jo',12,16,'Os seus discípulos, porém, não entenderam isto no princípio; mas, quando Jesus foi glorificado, então se lembraram de que isto estava escrito dele, e que isto lhe fizeram.'),
('acf','jo',12,17,'A multidão, pois, que estava com ele quando Lázaro foi chamado da sepultura, testificava que ele o ressuscitara dentre os mortos.'),
('acf','jo',12,18,'Por isso a multidão lhe saiu ao encontro, porque tinham ouvido que ele fizera este sinal.'),
('acf','jo',12,19,'Disseram, pois, os fariseus entre si: Vedes que nada aproveitais? Eis que toda a gente vai após ele.'),
('acf','jo',12,20,'Ora, havia alguns gregos, entre os que tinham subido a adorar no dia da festa.'),
('acf','jo',12,21,'Estes, pois, dirigiram-se a Filipe, que era de Betsaida da Galiléia, e rogaram-lhe, dizendo: Senhor, queríamos ver a Jesus.'),
('acf','jo',12,22,'Filipe foi dizê-lo a André, e então André e Filipe o disseram a Jesus.'),
('acf','jo',12,23,'E Jesus lhes respondeu, dizendo: É chegada a hora em que o Filho do homem há de ser glorificado.'),
('acf','jo',12,24,'Na verdade, na verdade vos digo que, se o grão de trigo, caindo na terra, não morrer, fica ele só; mas se morrer, dá muito fruto.'),
('acf','jo',12,25,'Quem ama a sua vida perdê-la-á, e quem neste mundo odeia a sua vida, guardá-la-á para a vida eterna.'),
('acf','jo',12,26,'Se alguém me serve, siga-me, e onde eu estiver, ali estará também o meu servo. E, se alguém me servir, meu Pai o honrará.'),
('acf','jo',12,27,'Agora a minha alma está perturbada; e que direi eu? Pai, salva-me desta hora; mas para isto vim a esta hora.'),
('acf','jo',12,28,'Pai, glorifica o teu nome. Então veio uma voz do céu que dizia: Já o tenho glorificado, e outra vez o glorificarei.'),
('acf','jo',12,29,'Ora, a multidão que ali estava, e que a ouvira, dizia que havia sido um trovão. Outros diziam: Um anjo lhe falou.'),
('acf','jo',12,30,'Respondeu Jesus, e disse: Não veio esta voz por amor de mim, mas por amor de vós.'),
('acf','jo',12,31,'Agora é o juízo deste mundo; agora será expulso o príncipe deste mundo.'),
('acf','jo',12,32,'E eu, quando for levantado da terra, todos atrairei a mim.'),
('acf','jo',12,33,'E dizia isto, significando de que morte havia de morrer.'),
('acf','jo',12,34,'Respondeu-lhe a multidão: Nós temos ouvido da lei, que o Cristo permanece para sempre; e como dizes tu que convém que o Filho do homem seja levantado? Quem é esse Filho do homem?'),
('acf','jo',12,35,'Disse-lhes, pois, Jesus: A luz ainda está convosco por um pouco de tempo. Andai enquanto tendes luz, para que as trevas não vos apanhem; pois quem anda nas trevas não sabe para onde vai.'),
('acf','jo',12,36,'Enquanto tendes luz, crede na luz, para que sejais filhos da luz. Estas coisas disse Jesus e, retirando-se, escondeu-se deles.'),
('acf','jo',12,37,'E, ainda que tinha feito tantos sinais diante deles, não criam nele;'),
('acf','jo',12,38,'Para que se cumprisse a palavra do profeta Isaías, que diz: Senhor, quem creu na nossa pregação? E a quem foi revelado o braço do Senhor?'),
('acf','jo',12,39,'Por isso não podiam crer, entào Isaías disse outra vez:'),
('acf','jo',12,40,'Cegou-lhes os olhos, e endureceu-lhes o coração, A fim de que não vejam com os olhos, e compreendam no coração, E se convertam, E eu os cure.'),
('acf','jo',12,41,'Isaías disse isto quando viu a sua glória e falou dele.'),
('acf','jo',12,42,'Apesar de tudo, até muitos dos principais creram nele; mas não o confessavam por causa dos fariseus, para não serem expulsos da sinagoga.'),
('acf','jo',12,43,'Porque amavam mais a glória dos homens do que a glória de Deus.'),
('acf','jo',12,44,'E Jesus clamou, e disse: Quem crê em mim, crê, não em mim, mas naquele que me enviou.'),
('acf','jo',12,45,'E quem me vê a mim, vê aquele que me enviou.'),
('acf','jo',12,46,'Eu sou a luz que vim ao mundo, para que todo aquele que crê em mim não permaneça nas trevas.'),
('acf','jo',12,47,'E se alguém ouvir as minhas palavras, e não crer, eu não o julgo; porque eu vim, não para julgar o mundo, mas para salvar o mundo.'),
('acf','jo',12,48,'Quem me rejeitar a mim, e não receber as minhas palavras, já tem quem o julgue; a palavra que tenho pregado, essa o há de julgar no último dia.'),
('acf','jo',12,49,'Porque eu não tenho falado de mim mesmo; mas o Pai, que me enviou, ele me deu mandamento sobre o que hei de dizer e sobre o que hei de falar.'),
('acf','jo',12,50,'E sei que o seu mandamento é a vida eterna. Portanto, o que eu falo, falo-o como o Pai mo tem dito.'),
('acf','jo',13,1,'Ora, antes da festa da páscoa, sabendo Jesus que já era chegada a sua hora de passar deste mundo para o Pai, como havia amado os seus, que estavam no mundo, amou-os até o fim.'),
('acf','jo',13,2,'E, acabada a ceia, tendo já o diabo posto no coração de Judas Iscariotes, filho de Simão, que o traísse,'),
('acf','jo',13,3,'Jesus, sabendo que o Pai tinha depositado nas suas mãos todas as coisas, e que havia saído de Deus e ia para Deus,'),
('acf','jo',13,4,'Levantou-se da ceia, tirou as vestes, e, tomando uma toalha, cingiu-se.'),
('acf','jo',13,5,'Depois deitou água numa bacia, e começou a lavar os pés aos discípulos, e a enxugar-lhos com a toalha com que estava cingido.'),
('acf','jo',13,6,'Aproximou-se, pois, de Simão Pedro, que lhe disse: Senhor, tu lavas-me os pés a mim?'),
('acf','jo',13,7,'Respondeu Jesus, e disse-lhe: O que eu faço não o sabes tu agora, mas tu o saberás depois.'),
('acf','jo',13,8,'Disse-lhe Pedro: Nunca me lavarás os pés. Respondeu-lhe Jesus: Se eu te não lavar, não tens parte comigo.'),
('acf','jo',13,9,'Disse-lhe Simão Pedro: Senhor, não só os meus pés, mas também as mãos e a cabeça.'),
('acf','jo',13,10,'Disse-lhe Jesus: Aquele que está lavado não necessita de lavar senão os pés, pois no mais todo está limpo. Ora vós estais limpos, mas não todos.'),
('acf','jo',13,11,'Porque bem sabia ele quem o havia de trair; por isso disse: Nem todos estais limpos.'),
('acf','jo',13,12,'Depois que lhes lavou os pés, e tomou as suas vestes, e se assentou outra vez à mesa, disse-lhes: Entendeis o que vos tenho feito?'),
('acf','jo',13,13,'Vós me chamais Mestre e Senhor, e dizeis bem, porque eu o sou.'),
('acf','jo',13,14,'Ora, se eu, Senhor e Mestre, vos lavei os pés, vós deveis também lavar os pés uns aos outros.'),
('acf','jo',13,15,'Porque eu vos dei o exemplo, para que, como eu vos fiz, façais vós também.'),
('acf','jo',13,16,'Na verdade, na verdade vos digo que não é o servo maior do que o seu senhor, nem o enviado maior do que aquele que o enviou.'),
('acf','jo',13,17,'Se sabeis estas coisas, bem-aventurados sois se as fizerdes.'),
('acf','jo',13,18,'Não falo de todos vós; eu bem sei os que tenho escolhido; mas para que se cumpra a Escritura: O que come o pão comigo, levantou contra mim o seu calcanhar.'),
('acf','jo',13,19,'Desde agora vo-lo digo, antes que aconteça, para que, quando acontecer, acrediteis que eu sou.'),
('acf','jo',13,20,'Na verdade, na verdade vos digo: Se alguém receber o que eu enviar, me recebe a mim, e quem me recebe a mim, recebe aquele que me enviou.'),
('acf','jo',13,21,'Tendo Jesus dito isto, turbou-se em espírito, e afirmou, dizendo: Na verdade, na verdade vos digo que um de vós me há de trair.'),
('acf','jo',13,22,'Então os discípulos olhavam uns para os outros, duvidando de quem ele falava.'),
('acf','jo',13,23,'Ora, um de seus discípulos, aquele a quem Jesus amava, estava reclinado no seio de Jesus.'),
('acf','jo',13,24,'Então Simão Pedro fez sinal a este, para que perguntasse quem era aquele de quem ele falava.'),
('acf','jo',13,25,'E, inclinando-se ele sobre o peito de Jesus, disse-lhe: Senhor, quem é?'),
('acf','jo',13,26,'Jesus respondeu: É aquele a quem eu der o bocado molhado. E, molhando o bocado, o deu a Judas Iscariotes, filho de Simão.'),
('acf','jo',13,27,'E, após o bocado, entrou nele Satanás. Disse, pois, Jesus: O que fazes, faze-o depressa.'),
('acf','jo',13,28,'E nenhum dos que estavam assentados à mesa compreendeu a que propósito lhe dissera isto.'),
('acf','jo',13,29,'Porque, como Judas tinha a bolsa, pensavam alguns que Jesus lhe tinha dito: Compra o que nos é necessário para a festa; ou que desse alguma coisa aos pobres.'),
('acf','jo',13,30,'E, tendo Judas tomado o bocado, saiu logo. E era já noite.'),
('acf','jo',13,31,'Tendo ele, pois, saído, disse Jesus: Agora é glorificado o Filho do homem, e Deus é glorificado nele.'),
('acf','jo',13,32,'Se Deus é glorificado nele, também Deus o glorificará em si mesmo, e logo o há de glorificar.'),
('acf','jo',13,33,'Filhinhos, ainda por um pouco estou convosco. Vós me buscareis, mas, como tenho dito aos judeus: Para onde eu vou não podeis vós ir; eu vo-lo digo também agora.'),
('acf','jo',13,34,'Um novo mandamento vos dou: Que vos ameis uns aos outros; como eu vos amei a vós, que também vós uns aos outros vos ameis.'),
('acf','jo',13,35,'Nisto todos conhecerão que sois meus discípulos, se vos amardes uns aos outros.'),
('acf','jo',13,36,'Disse-lhe Simão Pedro: Senhor, para onde vais? Jesus lhe respondeu: Para onde eu vou não podes agora seguir-me, mas depois me seguirás.'),
('acf','jo',13,37,'Disse-lhe Pedro: Por que não posso seguir-te agora? Por ti darei a minha vida.'),
('acf','jo',13,38,'Respondeu-lhe Jesus: Tu darás a tua vida por mim? Na verdade, na verdade te digo que não cantará o galo enquanto não me tiveres negado três vezes.'),
('acf','jo',14,1,'Não se turbe o vosso coração; credes em Deus, crede também em mim.'),
('acf','jo',14,2,'Na casa de meu Pai há muitas moradas; se não fosse assim, eu vo-lo teria dito. Vou preparar-vos lugar.'),
('acf','jo',14,3,'E quando eu for, e vos preparar lugar, virei outra vez, e vos levarei para mim mesmo, para que onde eu estiver estejais vós também.'),
('acf','jo',14,4,'Mesmo vós sabeis para onde vou, e conheceis o caminho.'),
('acf','jo',14,5,'Disse-lhe Tomé: Senhor, nós não sabemos para onde vais; e como podemos saber o caminho?'),
('acf','jo',14,6,'Disse-lhe Jesus: Eu sou o caminho, e a verdade e a vida; ninguém vem ao Pai, senão por mim.'),
('acf','jo',14,7,'Se vós me conhecêsseis a mim, também conheceríeis a meu Pai; e já desde agora o conheceis, e o tendes visto.'),
('acf','jo',14,8,'Disse-lhe Filipe: Senhor, mostra-nos o Pai, o que nos basta.'),
('acf','jo',14,9,'Disse-lhe Jesus: Estou há tanto tempo convosco, e não me tendes conhecido, Filipe? Quem me vê a mim vê o Pai; e como dizes tu: Mostra-nos o Pai?'),
('acf','jo',14,10,'Não crês tu que eu estou no Pai, e que o Pai está em mim? As palavras que eu vos digo não as digo de mim mesmo, mas o Pai, que está em mim, é quem faz as obras.'),
('acf','jo',14,11,'Crede-me que estou no Pai, e o Pai em mim; crede-me, ao menos, por causa das mesmas obras.'),
('acf','jo',14,12,'Na verdade, na verdade vos digo que aquele que crê em mim também fará as obras que eu faço, e as fará maiores do que estas, porque eu vou para meu Pai.'),
('acf','jo',14,13,'E tudo quanto pedirdes em meu nome eu o farei, para que o Pai seja glorificado no Filho.'),
('acf','jo',14,14,'Se pedirdes alguma coisa em meu nome, eu o farei.'),
('acf','jo',14,15,'Se me amais, guardai os meus mandamentos.'),
('acf','jo',14,16,'E eu rogarei ao Pai, e ele vos dará outro Consolador, para que fique convosco para sempre;'),
('acf','jo',14,17,'O Espírito de verdade, que o mundo não pode receber, porque não o vê nem o conhece; mas vós o conheceis, porque habita convosco, e estará em vós.'),
('acf','jo',14,18,'Não vos deixarei órfãos; voltarei para vós.'),
('acf','jo',14,19,'Ainda um pouco, e o mundo não me verá mais, mas vós me vereis; porque eu vivo, e vós vivereis.'),
('acf','jo',14,20,'Naquele dia conhecereis que estou em meu Pai, e vós em mim, e eu em vós.'),
('acf','jo',14,21,'Aquele que tem os meus mandamentos e os guarda esse é o que me ama; e aquele que me ama será amado de meu Pai, e eu o amarei, e me manifestarei a ele.'),
('acf','jo',14,22,'Disse-lhe Judas (não o Iscariotes): Senhor, de onde vem que te hás de manifestar a nós, e não ao mundo?'),
('acf','jo',14,23,'Jesus respondeu, e disse-lhe: Se alguém me ama, guardará a minha palavra, e meu Pai o amará, e viremos para ele, e faremos nele morada.'),
('acf','jo',14,24,'Quem não me ama não guarda as minhas palavras; ora, a palavra que ouvistes não é minha, mas do Pai que me enviou.'),
('acf','jo',14,25,'Tenho-vos dito isto, estando convosco.'),
('acf','jo',14,26,'Mas aquele Consolador, o Espírito Santo, que o Pai enviará em meu nome, esse vos ensinará todas as coisas, e vos fará lembrar de tudo quanto vos tenho dito.'),
('acf','jo',14,27,'Deixo-vos a paz, a minha paz vos dou; não vo-la dou como o mundo a dá. Não se turbe o vosso coração, nem se atemorize.'),
('acf','jo',14,28,'Ouvistes que eu vos disse: Vou, e venho para vós. Se me amásseis, certamente exultaríeis porque eu disse: Vou para o Pai; porque meu Pai é maior do que eu.'),
('acf','jo',14,29,'Eu vo-lo disse agora antes que aconteça, para que, quando acontecer, vós acrediteis.'),
('acf','jo',14,30,'Já não falarei muito convosco, porque se aproxima o príncipe deste mundo, e nada tem em mim;'),
('acf','jo',14,31,'Mas é para que o mundo saiba que eu amo o Pai, e que faço como o Pai me mandou. Levantai-vos, vamo-nos daqui.'),
('acf','jo',15,1,'Eu sou a videira verdadeira, e meu Pai é o lavrador.'),
('acf','jo',15,2,'Toda a vara em mim, que não dá fruto, a tira; e limpa toda aquela que dá fruto, para que dê mais fruto.'),
('acf','jo',15,3,'Vós já estais limpos, pela palavra que vos tenho falado.'),
('acf','jo',15,4,'Estai em mim, e eu em vós; como a vara de si mesma não pode dar fruto, se não estiver na videira, assim também vós, se não estiverdes em mim.'),
('acf','jo',15,5,'Eu sou a videira, vós as varas; quem está em mim, e eu nele, esse dá muito fruto; porque sem mim nada podeis fazer.'),
('acf','jo',15,6,'Se alguém não estiver em mim, será lançado fora, como a vara, e secará; e os colhem e lançam no fogo, e ardem.'),
('acf','jo',15,7,'Se vós estiverdes em mim, e as minhas palavras estiverem em vós, pedireis tudo o que quiserdes, e vos será feito.'),
('acf','jo',15,8,'Nisto é glorificado meu Pai, que deis muito fruto; e assim sereis meus discípulos.'),
('acf','jo',15,9,'Como o Pai me amou, também eu vos amei a vós; permanecei no meu amor.'),
('acf','jo',15,10,'Se guardardes os meus mandamentos, permanecereis no meu amor; do mesmo modo que eu tenho guardado os mandamentos de meu Pai, e permaneço no seu amor.'),
('acf','jo',15,11,'Tenho-vos dito isto, para que o meu gozo permaneça em vós, e o vosso gozo seja completo.'),
('acf','jo',15,12,'O meu mandamento é este: Que vos ameis uns aos outros, assim como eu vos amei.'),
('acf','jo',15,13,'Ninguém tem maior amor do que este, de dar alguém a sua vida pelos seus amigos.'),
('acf','jo',15,14,'Vós sereis meus amigos, se fizerdes o que eu vos mando.'),
('acf','jo',15,15,'Já vos não chamarei servos, porque o servo não sabe o que faz o seu senhor; mas tenho-vos chamado amigos, porque tudo quanto ouvi de meu Pai vos tenho feito conhecer.'),
('acf','jo',15,16,'Não me escolhestes vós a mim, mas eu vos escolhi a vós, e vos nomeei, para que vades e deis fruto, e o vosso fruto permaneça; a fim de que tudo quanto em meu nome pedirdes ao Pai ele vo-lo conceda.'),
('acf','jo',15,17,'Isto vos mando: Que vos ameis uns aos outros.'),
('acf','jo',15,18,'Se o mundo vos odeia, sabei que, primeiro do que a vós, me odiou a mim.'),
('acf','jo',15,19,'Se vós fôsseis do mundo, o mundo amaria o que era seu, mas porque não sois do mundo, antes eu vos escolhi do mundo, por isso é que o mundo vos odeia.'),
('acf','jo',15,20,'Lembrai-vos da palavra que vos disse: Não é o servo maior do que o seu senhor. Se a mim me perseguiram, também vos perseguirão a vós; se guardaram a minha palavra, também guardarão a vossa.'),
('acf','jo',15,21,'Mas tudo isto vos farão por causa do meu nome, porque não conhecem aquele que me enviou.'),
('acf','jo',15,22,'Se eu não viera, nem lhes houvera falado, não teriam pecado, mas agora não têm desculpa do seu pecado.'),
('acf','jo',15,23,'Aquele que me odeia, odeia também a meu Pai.'),
('acf','jo',15,24,'Se eu entre eles não fizesse tais obras, quais nenhum outro tem feito, não teriam pecado; mas agora, viram-nas e me odiaram a mim e a meu Pai.'),
('acf','jo',15,25,'Mas é para que se cumpra a palavra que está escrita na sua lei: Odiaram-me sem causa.'),
('acf','jo',15,26,'Mas, quando vier o Consolador, que eu da parte do Pai vos hei de enviar, aquele Espírito de verdade, que procede do Pai, ele testificará de mim.'),
('acf','jo',15,27,'E vós também testificareis, pois estivestes comigo desde o princípio.'),
('acf','jo',16,1,'Tenho-vos dito estas coisas para que vos não escandalizeis.'),
('acf','jo',16,2,'Expulsar-vos-ão das sinagogas; vem mesmo a hora em que qualquer que vos matar cuidará fazer um serviço a Deus.'),
('acf','jo',16,3,'E isto vos farão, porque não conheceram ao Pai nem a mim.'),
('acf','jo',16,4,'Mas tenho-vos dito isto, a fim de que, quando chegar aquela hora, vos lembreis de que já vo-lo tinha dito. E eu não vos disse isto desde o princípio, porque estava convosco.'),
('acf','jo',16,5,'E agora vou para aquele que me enviou; e nenhum de vós me pergunta: Para onde vais?'),
('acf','jo',16,6,'Antes, porque isto vos tenho dito, o vosso coração se encheu de tristeza.'),
('acf','jo',16,7,'Todavia digo-vos a verdade, que vos convém que eu vá; porque, se eu não for, o Consolador não virá a vós; mas, quando eu for, vo-lo enviarei.'),
('acf','jo',16,8,'E, quando ele vier, convencerá o mundo do pecado, e da justiça e do juízo.'),
('acf','jo',16,9,'Do pecado, porque não crêem em mim;'),
('acf','jo',16,10,'Da justiça, porque vou para meu Pai, e não me vereis mais;'),
('acf','jo',16,11,'E do juízo, porque já o príncipe deste mundo está julgado.'),
('acf','jo',16,12,'Ainda tenho muito que vos dizer, mas vós não o podeis suportar agora.'),
('acf','jo',16,13,'Mas, quando vier aquele Espírito de verdade, ele vos guiará em toda a verdade; porque não falará de si mesmo, mas dirá tudo o que tiver ouvido, e vos anunciará o que há de vir.'),
('acf','jo',16,14,'Ele me glorificará, porque há de receber do que é meu, e vo-lo há de anunciar.'),
('acf','jo',16,15,'Tudo quanto o Pai tem é meu; por isso vos disse que há de receber do que é meu e vo-lo há de anunciar.'),
('acf','jo',16,16,'Um pouco, e não me vereis; e outra vez um pouco, e ver-me-eis; porquanto vou para o Pai.'),
('acf','jo',16,17,'Então alguns dos seus discípulos disseram uns aos outros: Que é isto que nos diz? Um pouco, e não me vereis; e outra vez um pouco, e ver-me-eis; e: Porquanto vou para o Pai?'),
('acf','jo',16,18,'Diziam, pois: Que quer dizer isto: Um pouco? Não sabemos o que diz.'),
('acf','jo',16,19,'Conheceu, pois, Jesus que o queriam interrogar, e disse-lhes: Indagais entre vós acerca disto que disse: Um pouco, e não me vereis, e outra vez um pouco, e ver-me-eis?'),
('acf','jo',16,20,'Na verdade, na verdade vos digo que vós chorareis e vos lamentareis, e o mundo se alegrará, e vós estareis tristes, mas a vossa tristeza se converterá em alegria.'),
('acf','jo',16,21,'A mulher, quando está para dar à luz, sente tristeza, porque é chegada a sua hora; mas, depois de ter dado à luz a criança, já não se lembra da aflição, pelo prazer de haver nascido um homem no mundo.'),
('acf','jo',16,22,'Assim também vós agora, na verdade, tendes tristeza; mas outra vez vos verei, e o vosso coração se alegrará, e a vossa alegria ninguém vo-la tirará.'),
('acf','jo',16,23,'E naquele dia nada me perguntareis. Na verdade, na verdade vos digo que tudo quanto pedirdes a meu Pai, em meu nome, ele vo-lo há de dar.'),
('acf','jo',16,24,'Até agora nada pedistes em meu nome; pedi, e recebereis, para que o vosso gozo se cumpra.'),
('acf','jo',16,25,'Disse-vos isto por parábolas; chega, porém, a hora em que não vos falarei mais por parábolas, mas abertamente vos falarei acerca do Pai.'),
('acf','jo',16,26,'Naquele dia pedireis em meu nome, e não vos digo que eu rogarei por vós ao Pai;'),
('acf','jo',16,27,'Pois o mesmo Pai vos ama, visto como vós me amastes, e crestes que saí de Deus.'),
('acf','jo',16,28,'Saí do Pai, e vim ao mundo; outra vez deixo o mundo, e vou para o Pai.'),
('acf','jo',16,29,'Disseram-lhe os seus discípulos: Eis que agora falas abertamente, e não dizes parábola alguma.'),
('acf','jo',16,30,'Agora conhecemos que sabes tudo, e não precisas de que alguém te interrogue. Por isso cremos que saíste de Deus.'),
('acf','jo',16,31,'Respondeu-lhes Jesus: Credes agora?'),
('acf','jo',16,32,'Eis que chega a hora, e já se aproxima, em que vós sereis dispersos cada um para sua parte, e me deixareis só; mas não estou só, porque o Pai está comigo.'),
('acf','jo',16,33,'Tenho-vos dito isto, para que em mim tenhais paz; no mundo tereis aflições, mas tende bom ânimo, eu venci o mundo.'),
('acf','jo',17,1,'Jesus falou assim e, levantando seus olhos ao céu, e disse: Pai, é chegada a hora; glorifica a teu Filho, para que também o teu Filho te glorifique a ti;'),
('acf','jo',17,2,'Assim como lhe deste poder sobre toda a carne, para que dê a vida eterna a todos quantos lhe deste.'),
('acf','jo',17,3,'E a vida eterna é esta: que te conheçam, a ti só, por único Deus verdadeiro, e a Jesus Cristo, a quem enviaste.'),
('acf','jo',17,4,'Eu glorifiquei-te na terra, tendo consumado a obra que me deste a fazer.'),
('acf','jo',17,5,'E agora glorifica-me tu, ó Pai, junto de ti mesmo, com aquela glória que tinha contigo antes que o mundo existisse.'),
('acf','jo',17,6,'Manifestei o teu nome aos homens que do mundo me deste; eram teus, e tu mos deste, e guardaram a tua palavra.'),
('acf','jo',17,7,'Agora já têm conhecido que tudo quanto me deste provém de ti;'),
('acf','jo',17,8,'Porque lhes dei as palavras que tu me deste; e eles as receberam, e têm verdadeiramente conhecido que saí de ti, e creram que me enviaste.'),
('acf','jo',17,9,'Eu rogo por eles; não rogo pelo mundo, mas por aqueles que me deste, porque são teus.'),
('acf','jo',17,10,'E todas as minhas coisas são tuas, e as tuas coisas são minhas; e neles sou glorificado.'),
('acf','jo',17,11,'E eu já não estou mais no mundo, mas eles estão no mundo, e eu vou para ti. Pai santo, guarda em teu nome aqueles que me deste, para que sejam um, assim como nós.'),
('acf','jo',17,12,'Estando eu com eles no mundo, guardava-os em teu nome. Tenho guardado aqueles que tu me deste, e nenhum deles se perdeu, senão o filho da perdição, para que a Escritura se cumprisse.'),
('acf','jo',17,13,'Mas agora vou para ti, e digo isto no mundo, para que tenham a minha alegria completa em si mesmos.'),
('acf','jo',17,14,'Dei-lhes a tua palavra, e o mundo os odiou, porque não são do mundo, assim como eu não sou do mundo.'),
('acf','jo',17,15,'Não peço que os tires do mundo, mas que os livres do mal.'),
('acf','jo',17,16,'Não são do mundo, como eu do mundo não sou.'),
('acf','jo',17,17,'Santifica-os na tua verdade; a tua palavra é a verdade.'),
('acf','jo',17,18,'Assim como tu me enviaste ao mundo, também eu os enviei ao mundo.'),
('acf','jo',17,19,'E por eles me santifico a mim mesmo, para que também eles sejam santificados na verdade.'),
('acf','jo',17,20,'E não rogo somente por estes, mas também por aqueles que pela tua palavra hão de crer em mim;'),
('acf','jo',17,21,'Para que todos sejam um, como tu, ó Pai, o és em mim, e eu em ti; que também eles sejam um em nós, para que o mundo creia que tu me enviaste.'),
('acf','jo',17,22,'E eu dei-lhes a glória que a mim me deste, para que sejam um, como nós somos um.'),
('acf','jo',17,23,'Eu neles, e tu em mim, para que eles sejam perfeitos em unidade, e para que o mundo conheça que tu me enviaste a mim, e que os tens amado a eles como me tens amado a mim.'),
('acf','jo',17,24,'Pai, aqueles que me deste quero que, onde eu estiver, também eles estejam comigo, para que vejam a minha glória que me deste; porque tu me amaste antes da fundação do mundo.'),
('acf','jo',17,25,'Pai justo, o mundo não te conheceu; mas eu te conheci, e estes conheceram que tu me enviaste a mim.'),
('acf','jo',17,26,'E eu lhes fiz conhecer o teu nome, e lho farei conhecer mais, para que o amor com que me tens amado esteja neles, e eu neles esteja.'),
('acf','jo',18,1,'Tendo Jesus dito isto, saiu com os seus discípulos para além do ribeiro de Cedrom, onde havia um horto, no qual ele entrou e seus discípulos.'),
('acf','jo',18,2,'E Judas, que o traía, também conhecia aquele lugar, porque Jesus muitas vezes se ajuntava ali com os seus discípulos.'),
('acf','jo',18,3,'Tendo, pois, Judas recebido a coorte e oficiais dos principais sacerdotes e fariseus, veio para ali com lanternas, e archotes e armas.'),
('acf','jo',18,4,'Sabendo, pois, Jesus todas as coisas que sobre ele haviam de vir, adiantou-se, e disse-lhes: A quem buscais?'),
('acf','jo',18,5,'Responderam-lhe: A Jesus Nazareno. Disse-lhes Jesus: Sou eu. E Judas, que o traía, estava com eles.'),
('acf','jo',18,6,'Quando, pois, lhes disse: Sou eu, recuaram, e caíram por terra.'),
('acf','jo',18,7,'Tornou-lhes, pois, a perguntar: A quem buscais? E eles disseram: A Jesus Nazareno.'),
('acf','jo',18,8,'Jesus respondeu: Já vos disse que sou eu; se, pois, me buscais a mim, deixai ir estes;'),
('acf','jo',18,9,'Para que se cumprisse a palavra que tinha dito: Dos que me deste nenhum deles perdi.'),
('acf','jo',18,10,'Então Simão Pedro, que tinha espada, desembainhou-a, e feriu o servo do sumo sacerdote, cortando-lhe a orelha direita. E o nome do servo era Malco.'),
('acf','jo',18,11,'Mas Jesus disse a Pedro: Põe a tua espada na bainha; não beberei eu o cálice que o Pai me deu?'),
('acf','jo',18,12,'Então a coorte, e o tribuno, e os servos dos judeus prenderam a Jesus e o maniataram.'),
('acf','jo',18,13,'E conduziram-no primeiramente a Anás, por ser sogro de Caifás, que era o sumo sacerdote daquele ano.'),
('acf','jo',18,14,'Ora, Caifás era quem tinha aconselhado aos judeus que convinha que um homem morresse pelo povo.'),
('acf','jo',18,15,'E Simão Pedro e outro discípulo seguiam a Jesus. E este discípulo era conhecido do sumo sacerdote, e entrou com Jesus na sala do sumo sacerdote.'),
('acf','jo',18,16,'E Pedro estava da parte de fora, à porta. Saiu então o outro discípulo que era conhecido do sumo sacerdote, e falou à porteira, levando Pedro para dentro.'),
('acf','jo',18,17,'Então a porteira disse a Pedro: Não és tu também dos discípulos deste homem? Disse ele: Não sou.'),
('acf','jo',18,18,'Ora, estavam ali os servos e os servidores, que tinham feito brasas, e se aquentavam, porque fazia frio; e com eles estava Pedro, aquentando-se também.'),
('acf','jo',18,19,'E o sumo sacerdote interrogou Jesus acerca dos seus discípulos e da sua doutrina.'),
('acf','jo',18,20,'Jesus lhe respondeu: Eu falei abertamente ao mundo; eu sempre ensinei na sinagoga e no templo, onde os judeus sempre se ajuntam, e nada disse em oculto.'),
('acf','jo',18,21,'Para que me perguntas a mim? Pergunta aos que ouviram o que é que lhes ensinei; eis que eles sabem o que eu lhes tenho dito.'),
('acf','jo',18,22,'E, tendo dito isto, um dos servidores que ali estavam, deu uma bofetada em Jesus, dizendo: Assim respondes ao sumo sacerdote?'),
('acf','jo',18,23,'Respondeu-lhe Jesus: Se falei mal, dá testemunho do mal; e, se bem, por que me feres?'),
('acf','jo',18,24,'E Anás mandou-o, maniatado, ao sumo sacerdote Caifás.'),
('acf','jo',18,25,'E Simão Pedro estava ali, e aquentava-se. Disseram-lhe, pois: Não és também tu um dos seus discípulos? Ele negou, e disse: Não sou.'),
('acf','jo',18,26,'E um dos servos do sumo sacerdote, parente daquele a quem Pedro cortara a orelha, disse: Não te vi eu no horto com ele?'),
('acf','jo',18,27,'E Pedro negou outra vez, e logo o galo cantou.'),
('acf','jo',18,28,'Depois levaram Jesus da casa de Caifás para a audiência. E era pela manhã cedo. E não entraram na audiência, para não se contaminarem, mas poderem comer a páscoa.'),
('acf','jo',18,29,'Então Pilatos saiu fora e disse-lhes: Que acusação trazeis contra este homem?'),
('acf','jo',18,30,'Responderam, e disseram-lhe: Se este não fosse malfeitor, não to entregaríamos.'),
('acf','jo',18,31,'Disse-lhes, pois, Pilatos: Levai-o vós, e julgai-o segundo a vossa lei. Disseram-lhe então os judeus: A nós não nos é lícito matar pessoa alguma.'),
('acf','jo',18,32,'(Para que se cumprisse a palavra que Jesus tinha dito, significando de que morte havia de morrer).'),
('acf','jo',18,33,'Tornou, pois, a entrar Pilatos na audiência, e chamou a Jesus, e disse-lhe: Tu és o Rei dos Judeus?'),
('acf','jo',18,34,'Respondeu-lhe Jesus: Tu dizes isso de ti mesmo, ou disseram-to outros de mim?'),
('acf','jo',18,35,'Pilatos respondeu: Porventura sou eu judeu? A tua nação e os principais dos sacerdotes entregaram-te a mim. Que fizeste?'),
('acf','jo',18,36,'Respondeu Jesus: O meu reino não é deste mundo; se o meu reino fosse deste mundo, pelejariam os meus servos, para que eu não fosse entregue aos judeus; mas agora o meu reino não é daqui.'),
('acf','jo',18,37,'Disse-lhe, pois, Pilatos: Logo tu és rei? Jesus respondeu: Tu dizes que eu sou rei. Eu para isso nasci, e para isso vim ao mundo, a fim de dar testemunho da verdade. Todo aquele que é da verdade ouve a minha voz.'),
('acf','jo',18,38,'Disse-lhe Pilatos: Que é a verdade? E, dizendo isto, tornou a ir ter com os judeus, e disse-lhes: Não acho nele crime algum.'),
('acf','jo',18,39,'Mas vós tendes por costume que eu vos solte alguém pela páscoa. Quereis, pois, que vos solte o Rei dos Judeus?'),
('acf','jo',18,40,'Então todos tornaram a clamar, dizendo: Este não, mas Barrabás. E Barrabás era um salteador.'),
('acf','jo',19,1,'Pilatos, pois, tomou então a Jesus, e o açoitou.'),
('acf','jo',19,2,'E os soldados, tecendo uma coroa de espinhos, lha puseram sobre a cabeça, e lhe vestiram roupa de púrpura.'),
('acf','jo',19,3,'E diziam: Salve, Rei dos Judeus. E davam-lhe bofetadas.'),
('acf','jo',19,4,'Então Pilatos saiu outra vez fora, e disse-lhes: Eis aqui vo-lo trago fora, para que saibais que não acho nele crime algum.'),
('acf','jo',19,5,'Saiu, pois, Jesus fora, levando a coroa de espinhos e roupa de púrpura. E disse-lhes Pilatos: Eis aqui o homem.'),
('acf','jo',19,6,'Vendo-o, pois, os principais dos sacerdotes e os servos, clamaram, dizendo: Crucifica-o, crucifica-o. Disse-lhes Pilatos: Tomai-o vós, e crucificai-o; porque eu nenhum crime acho nele.'),
('acf','jo',19,7,'Responderam-lhe os judeus: Nós temos uma lei e, segundo a nossa lei, deve morrer, porque se fez Filho de Deus.'),
('acf','jo',19,8,'E Pilatos, quando ouviu esta palavra, mais atemorizado ficou.'),
('acf','jo',19,9,'E entrou outra vez na audiência, e disse a Jesus: De onde és tu? Mas Jesus não lhe deu resposta.'),
('acf','jo',19,10,'Disse-lhe, pois, Pilatos: Não me falas a mim? Não sabes tu que tenho poder para te crucificar e tenho poder para te soltar?'),
('acf','jo',19,11,'Respondeu Jesus: Nenhum poder terias contra mim, se de cima não te fosse dado; mas aquele que me entregou a ti maior pecado tem.'),
('acf','jo',19,12,'Desde então Pilatos procurava soltá-lo; mas os judeus clamavam, dizendo: Se soltas este, não és amigo de César; qualquer que se faz rei é contra César.'),
('acf','jo',19,13,'Ouvindo, pois, Pilatos este dito, levou Jesus para fora, e assentou-se no tribunal, no lugar chamado Litóstrotos, e em hebraico Gabatá.'),
('acf','jo',19,14,'E era a preparação da páscoa, e quase à hora sexta; e disse aos judeus: Eis aqui o vosso Rei.'),
('acf','jo',19,15,'Mas eles bradaram: Tira, tira, crucifica-o. Disse-lhes Pilatos: Hei de crucificar o vosso Rei? Responderam os principais dos sacerdotes: Não temos rei, senão César.'),
('acf','jo',19,16,'Então, consequentemente entregou-lho, para que fosse crucificado. E tomaram a Jesus, e o levaram.'),
('acf','jo',19,17,'E, levando ele às costas a sua cruz, saiu para o lugar chamado Caveira, que em hebraico se chama Gólgota,'),
('acf','jo',19,18,'Onde o crucificaram, e com ele outros dois, um de cada lado, e Jesus no meio.'),
('acf','jo',19,19,'E Pilatos escreveu também um título, e pô-lo em cima da cruz; e nele estava escrito: JESUS NAZARENO, O REI DOS JUDEUS.'),
('acf','jo',19,20,'E muitos dos judeus leram este título; porque o lugar onde Jesus estava crucificado era próximo da cidade; e estava escrito em hebraico, grego e latim.'),
('acf','jo',19,21,'Diziam, pois, os principais sacerdotes dos judeus a Pilatos: Não escrevas, O Rei dos Judeus, mas que ele disse: Sou o Rei dos Judeus.'),
('acf','jo',19,22,'Respondeu Pilatos: O que escrevi, escrevi.'),
('acf','jo',19,23,'Tendo, pois, os soldados crucificado a Jesus, tomaram as suas vestes, e fizeram quatro partes, para cada soldado uma parte; e também a túnica. A túnica, porém, tecida toda de alto a baixo, não tinha costura.'),
('acf','jo',19,24,'Disseram, pois, uns aos outros: Não a rasguemos, mas lancemos sortes sobre ela, para ver de quem será. Para que se cumprisse a Escritura que diz: Repartiram entre si as minhas vestes, E sobre a minha vestidura lançaram sortes. Os soldados, pois, fizeram estas coisas.'),
('acf','jo',19,25,'E junto à cruz de Jesus estava sua mãe, e a irmã de sua mãe, Maria mulher de Clopas, e Maria Madalena.'),
('acf','jo',19,26,'Ora Jesus, vendo ali sua mãe, e que o discípulo a quem ele amava estava presente, disse a sua mãe: Mulher, eis aí o teu filho.'),
('acf','jo',19,27,'Depois disse ao discípulo: Eis aí tua mãe. E desde aquela hora o discípulo a recebeu em sua casa.'),
('acf','jo',19,28,'Depois, sabendo Jesus que já todas as coisas estavam terminadas, para que a Escritura se cumprisse, disse: Tenho sede.'),
('acf','jo',19,29,'Estava, pois, ali um vaso cheio de vinagre. E encheram de vinagre uma esponja, e, pondo-a num hissopo, lha chegaram à boca.'),
('acf','jo',19,30,'E, quando Jesus tomou o vinagre, disse: Está consumado. E, inclinando a cabeça, entregou o espírito.'),
('acf','jo',19,31,'Os judeus, pois, para que no sábado não ficassem os corpos na cruz, visto como era a preparação (pois era grande o dia de sábado), rogaram a Pilatos que se lhes quebrassem as pernas, e fossem tirados.'),
('acf','jo',19,32,'Foram, pois, os soldados, e, na verdade, quebraram as pernas ao primeiro, e ao outro que como ele fora crucificado;'),
('acf','jo',19,33,'Mas, vindo a Jesus, e vendo-o já morto, não lhe quebraram as pernas.'),
('acf','jo',19,34,'Contudo um dos soldados lhe furou o lado com uma lança, e logo saiu sangue e água.'),
('acf','jo',19,35,'E aquele que o viu testificou, e o seu testemunho é verdadeiro; e sabe que é verdade o que diz, para que também vós o creiais.'),
('acf','jo',19,36,'Porque isto aconteceu para que se cumprisse a Escritura, que diz: Nenhum dos seus ossos será quebrado.'),
('acf','jo',19,37,'E outra vez diz a Escritura: Verão aquele que traspassaram.'),
('acf','jo',19,38,'Depois disto, José de Arimatéia (o que era discípulo de Jesus, mas oculto, por medo dos judeus) rogou a Pilatos que lhe permitisse tirar o corpo de Jesus. E Pilatos lho permitiu. Então foi e tirou o corpo de Jesus.'),
('acf','jo',19,39,'E foi também Nicodemos (aquele que anteriormente se dirigira de noite a Jesus), levando quase cem arráteis de um composto de mirra e aloés.'),
('acf','jo',19,40,'Tomaram, pois, o corpo de Jesus e o envolveram em lençóis com as especiarias, como os judeus costumam fazer, na preparação para o sepulcro.'),
('acf','jo',19,41,'E havia um horto naquele lugar onde fora crucificado, e no horto um sepulcro novo, em que ainda ninguém havia sido posto.'),
('acf','jo',19,42,'Ali, pois (por causa da preparação dos judeus, e por estar perto aquele sepulcro), puseram a Jesus.'),
('acf','jo',20,1,'E no primeiro dia da semana, Maria Madalena foi ao sepulcro de madrugada, sendo ainda escuro, e viu a pedra tirada do sepulcro.'),
('acf','jo',20,2,'Correu, pois, e foi a Simão Pedro, e ao outro discípulo, a quem Jesus amava, e disse-lhes: Levaram o Senhor do sepulcro, e não sabemos onde o puseram.'),
('acf','jo',20,3,'Então Pedro saiu com o outro discípulo, e foram ao sepulcro.'),
('acf','jo',20,4,'E os dois corriam juntos, mas o outro discípulo correu mais apressadamente do que Pedro, e chegou primeiro ao sepulcro.'),
('acf','jo',20,5,'E, abaixando-se, viu no chão os lençóis; todavia não entrou.'),
('acf','jo',20,6,'Chegou, pois, Simão Pedro, que o seguia, e entrou no sepulcro, e viu no chão os lençóis,'),
('acf','jo',20,7,'E que o lenço, que tinha estado sobre a sua cabeça, não estava com os lençóis, mas enrolado num lugar à parte.'),
('acf','jo',20,8,'Então entrou também o outro discípulo, que chegara primeiro ao sepulcro, e viu, e creu.'),
('acf','jo',20,9,'Porque ainda não sabiam a Escritura, que era necessário que ressuscitasse dentre os mortos.'),
('acf','jo',20,10,'Tornaram, pois, os discípulos para casa.'),
('acf','jo',20,11,'E Maria estava chorando fora, junto ao sepulcro. Estando ela, pois, chorando, abaixou-se para o sepulcro.'),
('acf','jo',20,12,'E viu dois anjos vestidos de branco, assentados onde jazera o corpo de Jesus, um à cabeceira e outro aos pés.'),
('acf','jo',20,13,'E disseram-lhe eles: Mulher, por que choras? Ela lhes disse: Porque levaram o meu Senhor, e não sei onde o puseram.'),
('acf','jo',20,14,'E, tendo dito isto, voltou-se para trás, e viu Jesus em pé, mas não sabia que era Jesus.'),
('acf','jo',20,15,'Disse-lhe Jesus: Mulher, por que choras? Quem buscas? Ela, cuidando que era o hortelão, disse-lhe: Senhor, se tu o levaste, dize-me onde o puseste, e eu o levarei.'),
('acf','jo',20,16,'Disse-lhe Jesus: Maria! Ela, voltando-se, disse-lhe: Raboni, que quer dizer: Mestre.'),
('acf','jo',20,17,'Disse-lhe Jesus: Não me detenhas, porque ainda não subi para meu Pai, mas vai para meus irmãos, e dize-lhes que eu subo para meu Pai e vosso Pai, meu Deus e vosso Deus.'),
('acf','jo',20,18,'Maria Madalena foi e anunciou aos discípulos que vira o Senhor, e que ele lhe dissera isto.'),
('acf','jo',20,19,'Chegada, pois, a tarde daquele dia, o primeiro da semana, e cerradas as portas onde os discípulos, com medo dos judeus, se tinham ajuntado, chegou Jesus, e pôs-se no meio, e disse-lhes: Paz seja convosco.'),
('acf','jo',20,20,'E, dizendo isto, mostrou-lhes as suas mãos e o lado. De sorte que os discípulos se alegraram, vendo o Senhor.'),
('acf','jo',20,21,'Disse-lhes, pois, Jesus outra vez: Paz seja convosco; assim como o Pai me enviou, também eu vos envio a vós.'),
('acf','jo',20,22,'E, havendo dito isto, assoprou sobre eles e disse-lhes: Recebei o Espírito Santo.'),
('acf','jo',20,23,'«queles a quem perdoardes os pecados lhes são perdoados; e àqueles a quem os retiverdes lhes são retidos.'),
('acf','jo',20,24,'Ora, Tomé, um dos doze, chamado Dídimo, não estava com eles quando veio Jesus.'),
('acf','jo',20,25,'Disseram-lhe, pois, os outros discípulos: Vimos o Senhor. Mas ele disse-lhes: Se eu não vir o sinal dos cravos em suas mãos, e não puser o meu dedo no lugar dos cravos, e não puser a minha mão no seu lado, de maneira nenhuma o crerei.'),
('acf','jo',20,26,'E oito dias depois estavam outra vez os seus discípulos dentro, e com eles Tomé. Chegou Jesus, estando as portas fechadas, e apresentou-se no meio, e disse: Paz seja convosco.'),
('acf','jo',20,27,'Depois disse a Tomé: Põe aqui o teu dedo, e vê as minhas mãos; e chega a tua mão, e põe-na no meu lado; e não sejas incrédulo, mas crente.'),
('acf','jo',20,28,'E Tomé respondeu, e disse-lhe: Senhor meu, e Deus meu!'),
('acf','jo',20,29,'Disse-lhe Jesus: Porque me viste, Tomé, creste; bem-aventurados os que não viram e creram.'),
('acf','jo',20,30,'Jesus, pois, operou também em presença de seus discípulos muitos outros sinais, que não estão escritos neste livro.'),
('acf','jo',20,31,'Estes, porém, foram escritos para que creiais que Jesus é o Cristo, o Filho de Deus, e para que, crendo, tenhais vida em seu nome.'),
('acf','jo',21,1,'Depois disto manifestou-se Jesus outra vez aos discípulos junto do mar de Tiberíades; e manifestou-se assim:'),
('acf','jo',21,2,'Estavam juntos Simão Pedro, e Tomé, chamado Dídimo, e Natanael, que era de Caná da Galiléia, os filhos de Zebedeu, e outros dois dos seus discípulos.'),
('acf','jo',21,3,'Disse-lhes Simão Pedro: Vou pescar. Dizem-lhe eles: Também nós vamos contigo. Foram, e subiram logo para o barco, e naquela noite nada apanharam.'),
('acf','jo',21,4,'E, sendo já manhã, Jesus se apresentou na praia, mas os discípulos não conheceram que era Jesus.'),
('acf','jo',21,5,'Disse-lhes, pois, Jesus: Filhos, tendes alguma coisa de comer? Responderam-lhe: Não.'),
('acf','jo',21,6,'E ele lhes disse: Lançai a rede para o lado direito do barco, e achareis. Lançaram-na, pois, e já não a podiam tirar, pela multidão dos peixes.'),
('acf','jo',21,7,'Então aquele discípulo, a quem Jesus amava, disse a Pedro: É o Senhor. E, quando Simão Pedro ouviu que era o Senhor, cingiu-se com a túnica (porque estava nu) e lançou-se ao mar.'),
('acf','jo',21,8,'E os outros discípulos foram com o barco (porque não estavam distantes da terra senão quase duzentos côvados), levando a rede cheia de peixes.'),
('acf','jo',21,9,'Logo que desceram para terra, viram ali brasas, e um peixe posto em cima, e pão.'),
('acf','jo',21,10,'Disse-lhes Jesus: Trazei dos peixes que agora apanhastes.'),
('acf','jo',21,11,'Simão Pedro subiu e puxou a rede para terra, cheia de cento e cinqüenta e três grandes peixes e, sendo tantos, não se rompeu a rede.'),
('acf','jo',21,12,'Disse-lhes Jesus: Vinde, comei. E nenhum dos discípulos ousava perguntar-lhe: Quem és tu? sabendo que era o Senhor.'),
('acf','jo',21,13,'Chegou, pois, Jesus, e tomou o pão, e deu-lhes e, semelhantemente o peixe.'),
('acf','jo',21,14,'E já era a terceira vez que Jesus se manifestava aos seus discípulos, depois de ter ressuscitado dentre os mortos.'),
('acf','jo',21,15,'E, depois de terem jantado, disse Jesus a Simão Pedro: Simão, filho de Jonas, amas-me mais do que estes? E ele respondeu: Sim, Senhor, tu sabes que te amo. Disse-lhe: Apascenta os meus cordeiros.'),
('acf','jo',21,16,'Tornou a dizer-lhe segunda vez: Simão, filho de Jonas, amas-me? Disse-lhe: Sim, Senhor, tu sabes que te amo. Disse-lhe: Apascenta as minhas ovelhas.'),
('acf','jo',21,17,'Disse-lhe terceira vez: Simão, filho de Jonas, amas-me? Simão entristeceu-se por lhe ter dito terceira vez: Amas-me? E disse-lhe: Senhor, tu sabes tudo; tu sabes que eu te amo. Jesus disse-lhe: Apascenta as minhas ovelhas.'),
('acf','jo',21,18,'Na verdade, na verdade te digo que, quando eras mais moço, te cingias a ti mesmo, e andavas por onde querias; mas, quando já fores velho, estenderás as tuas mãos, e outro te cingirá, e te levará para onde tu não queiras.'),
('acf','jo',21,19,'E disse isto, significando com que morte havia ele de glorificar a Deus. E, dito isto, disse-lhe: Segue-me.'),
('acf','jo',21,20,'E Pedro, voltando-se, viu que o seguia aquele discípulo a quem Jesus amava, e que na ceia se recostara também sobre o seu peito, e que dissera: Senhor, quem é que te há de trair?'),
('acf','jo',21,21,'Vendo Pedro a este, disse a Jesus: Senhor, e deste que será?'),
('acf','jo',21,22,'Disse-lhe Jesus: Se eu quero que ele fique até que eu venha, que te importa a ti? Segue-me tu.'),
('acf','jo',21,23,'Divulgou-se, pois, entre os irmãos este dito, que aquele discípulo não havia de morrer. Jesus, porém, não lhe disse que não morreria, mas: Se eu quero que ele fique até que eu venha, que te importa a ti?'),
('acf','jo',21,24,'Este é o discípulo que testifica destas coisas e as escreveu; e sabemos que o seu testemunho é verdadeiro.'),
('acf','jo',21,25,'Há, porém, ainda muitas outras coisas que Jesus fez; e se cada uma das quais fosse escrita, cuido que nem ainda o mundo todo poderia conter os livros que se escrevessem. Amém.')
